function normalizeFigureMetaExpansionEntries(entries) {
    const allowed = new Set([
        'backgroundItems', 'scientificQuestions', 'innovationPoints', 'limitationPoints'
    ]);
    const normalized = new Map();
    (Array.isArray(entries) ? entries : []).slice(0, 8).forEach(entry => {
        const collection = Array.isArray(entry) ? String(entry[0] || '') : '';
        if (entry?.length >= 2 && allowed.has(collection)) {
            normalized.set(collection, entry[1] === true);
        }
    });
    return [...normalized.entries()];
}

function restoreFigureMetaExpansionState(state, entries) {
    if (!(state instanceof Map)) return state;
    state.clear();
    normalizeFigureMetaExpansionEntries(entries).forEach(([collection, expanded]) => {
        state.set(collection, expanded);
    });
    return state;
}

