function createMechanismChainSeedCoordinator(options) {
    options = options && typeof options === 'object' ? options : Object.create(null);
    const captureContext = typeof options.captureContext === 'function'
        ? options.captureContext : () => Object.freeze({});
    const keyForContext = typeof options.keyForContext === 'function'
        ? options.keyForContext : () => '';
    const seed = typeof options.seed === 'function'
        ? options.seed : () => Promise.resolve({ success: false });
    const maximum = Number.isSafeInteger(options.maximum)
        ? Math.max(1, Math.min(16, options.maximum)) : 8;
    const tasks = new Map();
    function start(payload, suppliedContext = null) {
        const captured = suppliedContext && typeof suppliedContext === 'object'
            ? suppliedContext : captureContext();
        const context = Object.freeze({ ...(captured && typeof captured === 'object'
            ? captured : {}) });
        const keyValue = keyForContext(context);
        const key = typeof keyValue === 'string' ? keyValue.slice(0, 1000) : '';
        if (!key) return Promise.resolve({
            success: false, code: 'FIGURE_WORKSPACE_CONTEXT_INVALID'
        });
        if (tasks.has(key)) return tasks.get(key);
        if (tasks.size >= maximum) return Promise.resolve({
            success: false, code: 'FIGURE_WORKSPACE_SEED_BUSY'
        });
        let dispatched;
        try {
            dispatched = seed(payload, context);
        } catch (error) {
            return Promise.reject(error);
        }
        const task = Promise.resolve(dispatched);
        tasks.set(key, task);
        const cleanup = () => {
            if (tasks.get(key) === task) tasks.delete(key);
        };
        task.then(cleanup, cleanup);
        return task;
    }
    return Object.freeze({
        start,
        getState() { return { pendingKeys: [...tasks.keys()] }; }
    });
}

function createMechanismActionCoordinator(options) {
    options = options && typeof options === 'object' ? options : Object.create(null);
    const getEditorState = typeof options.getEditorState === 'function'
        ? options.getEditorState : () => ({ active: null });
    const flushEditor = typeof options.flushEditor === 'function'
        ? options.flushEditor : async () => ({ status: 'idle' });
    const persist = typeof options.persist === 'function'
        ? options.persist : async () => ({ success: false });
    const status = typeof options.status === 'function' ? options.status : () => {};
    let tail = Promise.resolve();
    function run(mutation, context) {
        const operation = tail.catch(() => null).then(async () => {
            if (getEditorState()?.active) {
                const flushed = await flushEditor('mechanism-action');
                if (!['saved', 'unchanged', 'idle'].includes(flushed?.status)) {
                    status('请先完成当前编辑后再修改机制链', 'error');
                    return {
                        success: false,
                        code: 'FIGURE_WORKSPACE_ACTIVE_EDIT_NOT_SAVED'
                    };
                }
            }
            return persist(mutation, context);
        });
        tail = operation.catch(() => null);
        return operation;
    }
    return Object.freeze({ run });
}

function createMechanismNodeRemovalCoordinator(options) {
    options = options && typeof options === 'object' ? options : Object.create(null);
    const removeNode = typeof options.remove === 'function'
        ? options.remove : async () => ({ success: false });
    const setPending = typeof options.setPending === 'function'
        ? options.setPending : () => undefined;
    const pending = new Set();
    async function remove(nodeId) {
        const id = typeof nodeId === 'string' ? nodeId.slice(0, 200) : '';
        if (!id) return { success: false, pending: false };
        if (pending.has(id)) return { success: false, pending: true };
        pending.add(id);
        setPending(id, true);
        try {
            return await removeNode(id);
        } finally {
            pending.delete(id);
            setPending(id, false);
        }
    }
    return Object.freeze({ remove, isPending: nodeId => pending.has(nodeId) });
}

function finalizeSuccessfulMechanismGeneration(options) {
    options = options && typeof options === 'object' ? options : Object.create(null);
    const response = options.response;
    const seedMode = typeof options.seedMode === 'string' ? options.seedMode : 'none';
    const refresh = options.refresh;
    const seed = options.seed;
    const generationContext = options.generationContext;
    const isContextCurrent = typeof options.isContextCurrent === 'function'
        ? options.isContextCurrent : () => false;
    const matchesSnapshot = typeof options.matchesSnapshot === 'function'
        ? options.matchesSnapshot : () => false;
    const onBlocked = typeof options.onBlocked === 'function' ? options.onBlocked : () => {};
    const own = (value, key) => {
        if (!value || (typeof value !== 'object' && typeof value !== 'function')) {
            return undefined;
        }
        try {
            const descriptor = Object.getOwnPropertyDescriptor(value, key);
            return descriptor && Object.hasOwn(descriptor, 'value')
                ? descriptor.value : undefined;
        } catch (_) { return undefined; }
    };
    const seedable = typeof isSeedableMechanismGenerationResult === 'function'
        ? isSeedableMechanismGenerationResult
        : value => {
            if (!value || typeof value !== 'object' || Array.isArray(value)) return false;
            const descriptor = Object.getOwnPropertyDescriptor(value, 'mechanismEdges');
            const edges = descriptor && Object.hasOwn(descriptor, 'value')
                ? descriptor.value : null;
            if (!Array.isArray(edges) || !edges.length || edges.length > 256) return false;
            return edges.every(edge => {
                if (!edge || typeof edge !== 'object' || Array.isArray(edge)) return false;
                const from = Object.getOwnPropertyDescriptor(edge, 'from');
                const to = Object.getOwnPropertyDescriptor(edge, 'to');
                return from && Object.hasOwn(from, 'value') &&
                    typeof from.value === 'string' && Boolean(from.value.trim()) &&
                    to && Object.hasOwn(to, 'value') &&
                    typeof to.value === 'string' && Boolean(to.value.trim());
            });
        };
    const refreshed = typeof refresh === 'function' ? refresh() : null;
    return Promise.resolve(refreshed).then(snapshot => {
        const result = own(response, 'result');
        if (own(response, 'success') !== true || own(response, 'status') !== 'complete' ||
            !seedable(result)) {
            return { status: 'not_generated', snapshot };
        }
        if (!['auto', 'explicit'].includes(seedMode) || typeof seed !== 'function') {
            return { status: 'refreshed', snapshot, response };
        }
        if (!generationContext || !snapshot || !isContextCurrent(generationContext) ||
            !matchesSnapshot(snapshot, generationContext)) {
            const message = '机制链生成结果未写入：论文上下文已变化，请重试';
            onBlocked(message);
            return { status: 'stale_context', snapshot, response };
        }
        return Promise.resolve(seed(snapshot, {
            explicit: seedMode === 'explicit',
            crossLogic: result,
            generationContext
        })).then(seeded => ({ status: 'seeded', snapshot, response, seeded }));
    });
}

function buildFigureWorkspaceEditTarget(context = {}) {
    const workspaceId = String(context.workspaceId || '').trim().toLowerCase();
    const workspaceGeneration = Number(context.workspaceGeneration);
    const contentHash = String(context.workspaceContentHash || '')
        .trim().toLowerCase().replace(/^sha256:/u, '');
    let canonicalUrl = '';
    try {
        canonicalUrl = SciLLM.normalizeWorkspaceCanonicalUrl(
            context.workspaceCanonicalUrl
        );
    } catch (_) {}
    if (!/^workspace:[a-f0-9]{64}$/u.test(workspaceId) ||
        !Number.isSafeInteger(workspaceGeneration) || workspaceGeneration < 1 ||
        !/^[a-f0-9]{64}$/u.test(contentHash) || !canonicalUrl) {
        const error = new Error('FIGURE_WORKSPACE_CONTEXT_INVALID');
        error.code = 'FIGURE_WORKSPACE_CONTEXT_INVALID';
        throw error;
    }
    return { workspaceId, workspaceGeneration, canonicalUrl, contentHash };
}

function captureFigureWorkspaceEditContext() {
    const workspace = currentWorkspaceSnapshot?.localWorkspace || {};
    const draft = mechanismWorkspaceDraft(currentWorkspaceSnapshot) || {};
    return Object.freeze({
        tabId: Number(activePanelTabContext.tabId),
        contextKey: String(activePanelTabContext.key || ''),
        documentKey: String(
            currentWorkspaceSnapshot?.documentHash ||
            preparedDocumentState?.documentHash ||
            currentWorkspaceSnapshot?.documentKey ||
            currentWorkspaceSnapshot?.url || ''
        ),
        documentId: String(
            currentWorkspaceSnapshot?.documentId ||
            preparedDocumentState?.documentId || manualAnnotationState?.documentId || ''
        ),
        workspaceId: String(workspace.workspaceId || ''),
        workspaceGeneration: Number(workspace.workspaceGeneration),
        workspaceLifecycle: Number(currentWorkspaceSnapshot?.figures?.workspaceLifecycle),
        workspaceCanonicalUrl: String(workspace.canonicalUrl || currentWorkspaceSnapshot?.url || ''),
        workspaceContentHash: String(workspace.contentHash || workspace.revision || ''),
        draftRevision: Number(draft.revision),
        mechanismChainFingerprint: mechanismChainFingerprint(draft.mechanismChain)
    });
}

function isCurrentFigureWorkspaceEditContext(context) {
    const live = captureFigureWorkspaceEditContext();
    return Number(context?.tabId) === live.tabId &&
        String(context?.contextKey || '') === live.contextKey &&
        String(context?.documentKey || '') === live.documentKey &&
        String(context?.documentId || '') === live.documentId &&
        String(context?.workspaceId || '') === live.workspaceId &&
        Number(context?.workspaceGeneration) === live.workspaceGeneration &&
        Number(context?.workspaceLifecycle) === live.workspaceLifecycle &&
        String(context?.workspaceContentHash || '') === live.workspaceContentHash &&
        Number(context?.draftRevision) === live.draftRevision &&
        String(context?.mechanismChainFingerprint || '') ===
            live.mechanismChainFingerprint;
}

function mechanismSnapshotMatchesContext(snapshot, context) {
    const workspace = snapshot?.localWorkspace;
    const draft = mechanismWorkspaceDraft(snapshot) || {};
    if (!workspace || !context) return false;
    let snapshotUrl = '';
    let contextUrl = '';
    try {
        snapshotUrl = SciLLM.normalizeWorkspaceCanonicalUrl(workspace.canonicalUrl);
        contextUrl = SciLLM.normalizeWorkspaceCanonicalUrl(
            context.workspaceCanonicalUrl
        );
    } catch (_) { return false; }
    const snapshotHash = String(workspace.contentHash || workspace.revision || '')
        .trim().toLowerCase().replace(/^sha256:/u, '');
    const contextHash = String(context.workspaceContentHash || '')
        .trim().toLowerCase().replace(/^sha256:/u, '');
    return String(workspace.workspaceId || '').trim().toLowerCase() ===
            String(context.workspaceId || '').trim().toLowerCase() &&
        Number(workspace.workspaceGeneration) === Number(context.workspaceGeneration) &&
        Number(snapshot?.figures?.workspaceLifecycle) === Number(context.workspaceLifecycle) &&
        snapshotUrl === contextUrl && snapshotHash === contextHash &&
        Number(draft.revision) === Number(context.draftRevision) &&
        mechanismChainFingerprint(draft.mechanismChain) ===
            String(context.mechanismChainFingerprint || '');
}

function mechanismChainContextKey(context = {}) {
    const parts = [
        Number(context.tabId), context.contextKey, context.documentKey,
        context.documentId, context.workspaceId, Number(context.workspaceGeneration),
        Number(context.workspaceLifecycle), context.workspaceCanonicalUrl,
        context.workspaceContentHash, Number(context.draftRevision),
        context.mechanismChainFingerprint
    ];
    return parts.map(value => typeof value === 'string'
        ? value.slice(0, 240) : String(value)).join('\u0000').slice(0, 1000);
}

