const figureWorkspaceInlineEditController = createFigureWorkspaceInlineEditController({
    captureContext: captureFigureWorkspaceEditContext,
    isContextCurrent: isCurrentFigureWorkspaceEditContext,
    isMountAvailable(mount) {
        return !mount || mount.isConnected === true;
    },
    onActiveChange(active, _record, transition) {
        figureWorkspaceRenderCoordinator.setEditing(active, transition);
    },
    getExpectedRevision() {
        return Number(
            currentWorkspaceSnapshot?.figures?.draft?.revision ??
            currentWorkspaceSnapshot?.figureWorkspaceDraft?.revision ?? 0
        );
    },
    getCurrentRevision() {
        return Number(
            currentWorkspaceSnapshot?.figures?.draft?.revision ??
            currentWorkspaceSnapshot?.figureWorkspaceDraft?.revision ?? 0
        );
    },
    async persist(mutation, context) {
        if (!isCurrentFigureWorkspaceEditContext(context)) {
            const error = new Error('FIGURE_WORKSPACE_EDIT_CONTEXT_CHANGED');
            error.code = 'FIGURE_WORKSPACE_EDIT_CONTEXT_CHANGED';
            throw error;
        }
        const response = await SciLLM.sendTabMessageWithRecovery(chrome, context.tabId, {
            action: 'updateFigureWorkspaceDraft', mutation,
            workspaceTarget: buildFigureWorkspaceEditTarget(context)
        });
        if (!response?.success) {
            const error = new Error(response?.error || 'Figure 草稿保存失败');
            error.code = response?.code || response?.error;
            throw error;
        }
        return response;
    },
    async refresh(context) {
        if (!isCurrentFigureWorkspaceEditContext(context)) return null;
        const response = await SciLLM.sendTabMessageWithRecovery(chrome, context.tabId, {
            action: 'getArticleWorkspaceSnapshot'
        });
        if (!response?.success || !response.snapshot ||
            !isCurrentFigureWorkspaceEditContext(context)) return null;
        const returnedDraft = response.snapshot?.figures?.draft ||
            response.snapshot?.figureWorkspaceDraft || null;
        const returnedRevision = Number(returnedDraft?.revision);
        const liveRevision = Number(
            currentWorkspaceSnapshot?.figures?.draft?.revision ??
            currentWorkspaceSnapshot?.figureWorkspaceDraft?.revision ?? 0
        );
        if (!Number.isSafeInteger(returnedRevision) || returnedRevision < liveRevision) {
            return null;
        }
        currentWorkspaceSnapshot = response.snapshot;
        return returnedDraft;
    },
    integrate(draft, _options, context) {
        if (!currentWorkspaceSnapshot || !draft ||
            !isCurrentFigureWorkspaceEditContext(context)) return;
        const liveRevision = Number(
            currentWorkspaceSnapshot?.figures?.draft?.revision ??
            currentWorkspaceSnapshot?.figureWorkspaceDraft?.revision ?? 0
        );
        if (!Number.isSafeInteger(draft.revision) || draft.revision < liveRevision) return;
        currentWorkspaceSnapshot = {
            ...currentWorkspaceSnapshot,
            figureWorkspaceDraft: draft,
            figures: { ...(currentWorkspaceSnapshot.figures || {}), draft }
        };
    },
    close() {
        figureWorkspaceRenderCoordinator.request(currentWorkspaceSnapshot);
    },
    focus(descriptor, presentationHint) {
        requestAnimationFrame(() => {
            findFigureWorkspaceEditTarget(descriptor, presentationHint)
                ?.focus({ preventScroll: true });
        });
    },
    status(state) {
        if (state.type === 'saved') figureWorkspaceUnsavedContextWarning = '';
        updateFigureWorkspaceInlineEditStatus(state);
    },
    async flushDraft(context) {
        if (!context?.tabId || !isCurrentFigureWorkspaceEditContext(context)) {
            return { status: 'context_changed' };
        }
        return SciLLM.sendTabMessageWithRecovery(chrome, context.tabId, {
            action: 'flushFigureWorkspaceDraft',
            workspaceTarget: buildFigureWorkspaceEditTarget(context)
        }).catch(() => ({ success: false }));
    }
});
