async function initializeCurrentArticle({ retry = false } = {}) {
    articleInitializationState?.controller?.abort();
    const controller = new AbortController();
    const signal = controller.signal;
    const requestId = ++articlePreparationSequence;
    let finishInitialization;
    const initialization = {
        context: capturePanelContext(), ready: false, error: null, controller,
        promise: new Promise(resolve => { finishInitialization = resolve; })
    };
    articleInitializationState = initialization;
    const isCurrent = () => !signal.aborted && requestId === articlePreparationSequence &&
        isCurrentPanelContext(initialization.context);
    if (initialization.context.offlineMode === true) {
        try {
            const snapshot = await refreshArticleWorkspace({ throwOnError: true, panelContext: initialization.context, signal });
            if (!isCurrent()) return null;
            initialization.ready = Boolean(snapshot);
            renderOfflineArticleReadOnlyState(snapshot);
            return snapshot;
        } catch (error) {
            initialization.error = error;
            if (isCurrent()) renderArticleConnectionFailure(error);
            return null;
        } finally { finishInitialization(initialization.ready && isCurrent()); }
    }
    const retryButton = document.getElementById('retryArticlePreparation');
    if (retryButton) {
        retryButton.hidden = true;
        retryButton.disabled = true;
    }
    renderArticleConnectionStage(
        retry ? '正在重新提取当前论文…' : '正在读取当前页面结构…',
        retry ? (currentWorkspaceSnapshot?.title || '当前论文') : '正在连接当前论文…'
    );
    try {
        const snapshot = await withPreparationDeadline((async () => {
            renderArticleConnectionStage('正在生成本地标题层级与段落索引…');
            let workspace = null;
            let lastRefreshError = null;
            const readinessDelays = retry ? [0, 250, 600] : [0, 250, 750, 1400];
            for (const delay of readinessDelays) {
                if (delay) await new Promise(resolve => setTimeout(resolve, delay));
                if (!isCurrent()) return null;
                try {
                    workspace = await refreshArticleWorkspace({ throwOnError: true, forceRefresh: retry,
                        panelContext: initialization.context, signal });
                } catch (error) {
                    lastRefreshError = error;
                    if (error?.code !== 'ARTICLE_PAGE_LOADING') throw error;
                }
                if (!isCurrent()) return null;
                if (workspace) break;
                renderArticleConnectionStage('正文页面仍在加载，正在等待页面结构稳定…');
            }
            if (!workspace) throw lastRefreshError || new Error('当前页面结构不可用');
            if (analysisMode !== 'llm') {
                await refreshManualAnnotationSummary(initialization.context.tabId, { signal });
                if (!isCurrent()) return null;
                requestMatchCounts();
            }
            return workspace;
        })(), 15000, error => controller.abort(error));
        if (!isCurrent()) return null;
        renderArticleWorkspaceSnapshot(snapshot);
        const panelContext = initialization.context;
        let pristineBaselineProof = null;
        const restored = await awaitArticlePreparationOperation(tryAutoRestoreCurrentArticleWorkspace(panelContext, {
            signal,
            onPristineBaseline: proof => { if (isCurrent()) pristineBaselineProof = proof; },
            onFailure: error => { if (isCurrent()) initialization.error = error; }
        }), signal);
        if (!isCurrent()) return null;
        if (restored?.applied?.success === false) {
            initialization.error = new Error(restored.applied.error || 'ARTICLE_WORKSPACE_RESTORE_FAILED');
        }
        if (!isCurrent()) return null;
        // Create the per-article directory as soon as the page is activated, but
        // only after restoration has had the first chance to read existing data.
        // The baseline action writes structure/paragraphs only; it cannot replace
        // a saved chat index, Figure result, highlight, or analysis with empties.
        await awaitArticlePreparationOperation(sendTabMessage(panelContext.tabId, {
            action: 'saveArticleWorkspaceBaseline'
        }).catch(() => null), signal);
        if (!isCurrent()) return null;
        if (analysisMode === 'llm') {
            // Preparing the document is local indexing, not a model invocation.
            // Diagnostics alone never populate the state used by the Apply button.
            if (llmSettingsState?.effectiveMode === 'llm' &&
                !preparedDocumentState?.documentHash) {
                try {
                    await awaitArticlePreparationOperation(prepareArticleForAdaptiveAnalysis(panelContext.tabId, { isCurrent }), signal);
                } catch (error) {
                    initialization.error = error;
                    if (isCurrent()) {
                        prepareState = 'idle';
                        updateApplyButton();
                        showStatus(`正文准备失败：${error?.message || '请重试'}`, 'error');
                    }
                }
            }
            if (!isCurrent()) return null;
            void Promise.allSettled([
                refreshLlmDiagnostics(),
                restoreFigureAnalysisProgress(),
                restoreReviewOutlineProgress()
            ]);
        }
        if (!restored) void probeCurrentArticleArchive({ pristineBaselineProof });
        initialization.ready = isCurrent() && !initialization.error;
        return currentWorkspaceSnapshot || snapshot;
    } catch (error) {
        initialization.error = error;
        if (requestId !== articlePreparationSequence ||
            !isCurrentPanelContext(initialization.context)) return null;
        renderArticleConnectionFailure(error);
        showStatus(error?.code === 'ARTICLE_PAGE_LOADING'
            ? '页面正文尚未稳定，请等待加载完成后重新提取；页面稳定后侧栏也会自动刷新。'
            :
            `${error?.code === 'ARTICLE_PREPARATION_TIMEOUT' ? '正文提取超时' : '正文提取失败'}：` +
            '可重新提取，或导出适配诊断包用于修复',
            error?.code === 'ARTICLE_PAGE_LOADING' ? 'info' : 'error'
        );
        return null;
    } finally {
        finishInitialization(initialization.ready && isCurrent());
        if (requestId === articlePreparationSequence &&
            isCurrentPanelContext(initialization.context) && retryButton && retryButton.hidden) {
            retryButton.disabled = false;
        }
    }
}

let sharingHighlightControlRevision = 0;
function setupSharedHighlightNoteControls() {
    const host = document.getElementById('workspace-highlights');
    if (!host || document.getElementById('sharing-public-notes-toggle')) return;
    const section = createWorkspaceElement('section', 'sharing-public-note-controls');
    const label = createWorkspaceElement('label', '', '');
    const toggle = document.createElement('input'); toggle.type = 'checkbox'; toggle.id = 'sharing-public-notes-toggle';
    label.append(toggle, document.createTextNode('查看公开备注')); section.appendChild(label);
    const scope = document.createElement('select'); scope.id = 'sharing-public-notes-scope'; scope.setAttribute('aria-label', '公开备注作者范围');
    for (const [value, text] of [['all', '全部可见'], ['group', '仅课题组成员']]) {
        const option = document.createElement('option'); option.value = value; option.textContent = text; scope.appendChild(option);
    }
    const groups = document.createElement('select'); groups.id = 'sharing-public-notes-group';
    groups.setAttribute('aria-label', '选择课题组'); groups.hidden = true;
    const status = createWorkspaceElement('p', '', '默认关闭；开启后可点击正文虚线句子阅读与交流，需要登录。');
    status.setAttribute('role', 'status'); section.append(scope, groups, status); host.prepend(section);
    let sequence = 0;
    const apply = async () => {
        sharingHighlightControlRevision += 1;
        const seq = ++sequence; toggle.disabled = true;
        try {
            const tab = await queryPanelTargetTab();
            if (!tab?.id) throw new Error('请先打开一篇文献');
            const response = await sendTabMessage(tab.id, { action: 'SET_SHARED_HIGHLIGHT_NOTES',
                enabled: toggle.checked, groupId: scope.value === 'group' ? groups.value : '' });
            if (seq !== sequence) return;
            if (!response?.success) throw new Error(response?.error || '公开备注暂不可用');
            toggle.checked = response.enabled;
            status.textContent = response.enabled ? `已显示 ${response.count || 0} 处讨论；点击正文虚线句子阅读与交流。` : '已关闭公开备注；自己的高亮保持不变。';
        } catch (error) { if (seq === sequence) { toggle.checked = false; status.textContent = error.message; } }
        finally { if (seq === sequence) toggle.disabled = false; }
    };
    toggle.addEventListener('change', event => { if (event.isTrusted) void apply(); });
    scope.addEventListener('change', async event => {
        if (!event.isTrusted) return;
        groups.hidden = scope.value !== 'group';
        if (scope.value === 'group') {
            try {
                const rows = (await globalThis.BrevessSharingClient.api('/api/groups')).groups || [];
                groups.replaceChildren();
                for (const row of rows) { const option = document.createElement('option'); option.value = row.id; option.textContent = row.name; option.setAttribute('translate', 'no'); groups.appendChild(option); }
                if (!rows.length) throw new Error('当前账号尚未加入课题组');
            } catch (error) { status.textContent = error.message; scope.value = 'all'; groups.hidden = true; }
        }
        if (toggle.checked) void apply();
    });
    groups.addEventListener('change', event => { if (event.isTrusted && toggle.checked) void apply(); });
    chrome.runtime.onMessage.addListener(message => {
        if (message?.type === 'BREVESS_SHARING_SESSION_CHANGED') { sequence++; sharingHighlightControlRevision++; toggle.checked = false; toggle.disabled = false; groups.replaceChildren(); status.textContent = '账号已变化，请重新开启查看公开备注。'; }
    });
}

async function syncSharedHighlightNoteControls() {
    const toggle = document.getElementById('sharing-public-notes-toggle');
    if (!toggle || toggle.disabled) return;
    const context = capturePanelContext();
    const revision = sharingHighlightControlRevision;
    try {
        const response = await sendTabMessage(context.tabId, { action: 'GET_SHARED_HIGHLIGHT_NOTES' });
        if (!isCurrentPanelContext(context) || toggle.disabled || revision !== sharingHighlightControlRevision) return;
        toggle.checked = response?.enabled === true;
    } catch (_) { if (isCurrentPanelContext(context) && revision === sharingHighlightControlRevision) toggle.checked = false; }
}

