function updateFigureButton() {
    const figureButton = document.getElementById('analyzeFiguresFromFigures') ||
        document.getElementById('analyzeFigures');
    if (!figureButton) return;
    const ready = hasUsableLlm();
    const running = hasRunningFigureProgress(figureAnalysisState);
    figureButton.hidden = true;
    figureButton.disabled = running;
    figureButton.classList.toggle('is-llm-pending', running || crossFigureLogicRunning);
    figureButton.setAttribute('aria-busy', String(running || crossFigureLogicRunning));
    figureButton.title = ready
        ? (figureSelectedIds.size ? `仅解读所选 ${figureSelectedIds.size} 张 Figure` : '依次解读全部 Figure')
        : llmUnavailableMessage('全部解图');
    if (crossFigureLogicRunning && !running) {
        const presentation = mechanismGenerationUiController.presentation();
        figureButton.textContent = presentation.total > 0
            ? `机制关系 ${Math.min(presentation.completed, presentation.total)}/` +
                `${presentation.total}`
            : '正在生成图表梳理';
    } else if (!running) {
        figureButton.textContent = figureSelectedIds.size ? `解读所选 ${figureSelectedIds.size} 张` : '全部解图';
    } else {
        figureButton.textContent = figureButtonProgressLabel(figureAnalysisState) || '正在读取 Figure';
    }
    if (figureButton.dataset.moduleAction !== undefined) {
        setModuleActionLabel(figureButton, figureButton.textContent,
            running || crossFigureLogicRunning ? '处理中' : figureSelectedIds.size ? `解图 ${figureSelectedIds.size}` : '解图', 'figureHeaderTaskStatus');
        if (!ready) figureButton.title = llmUnavailableMessage('全部解图');
    }
    updateFigureTaskControls();
    renderFigureNativeDiagnostic(figureAnalysisState);
}

function updateReviewOutlineButton() {
    const button = document.getElementById('generateReviewOutline');
    const ready = hasUsableLlm();
    let statusText = '';
    if (!reviewOutlineState.running) {
        statusText = reviewOutlineState.hasOutline
            ? '重新生成整篇逐段摘要' : '生成整篇逐段摘要';
    } else if (reviewOutlineState.phase === 'review_reduce') {
        statusText = '正在综合章节结构';
    } else if (reviewOutlineState.totalParagraphs > 0) {
        statusText = `${reviewOutlineState.completedParagraphs}/` +
            `${reviewOutlineState.totalParagraphs} 段`;
    } else {
        statusText = '正在提取正文层级';
    }
    if (button) {
        button.hidden = false;
        button.disabled = reviewOutlineState.running;
        button.classList.toggle('is-llm-pending', reviewOutlineState.running);
        button.setAttribute('aria-busy', String(reviewOutlineState.running));
        button.title = ready
            ? '生成整篇逐段摘要'
            : llmUnavailableMessage('逐段摘要');
        if (reviewOutlineState.running && reviewOutlineState.totalChunks > 0) {
            button.title = `${button.title}；分块 ${Math.min(
                reviewOutlineState.completedChunks,
                reviewOutlineState.totalChunks
            )}/${reviewOutlineState.totalChunks}`;
        }
        button.textContent = statusText;
    }
}

