function validateAdapterDiagnosticBundle(value) {
    if (value?.kind !== 'sci-publisher-adapter-diagnostic' ||
        value?.schemaVersion !== 2 ||
        typeof value?.dom?.documentHtml !== 'string') {
        throw new Error('诊断包格式不完整');
    }
    return value;
}

async function diagnosticBlob(bundle) {
    const jsonBlob = new Blob([JSON.stringify(bundle, null, 2)], {
        type: 'application/json;charset=utf-8'
    });
    if (typeof CompressionStream !== 'function') {
        return { blob: jsonBlob, extension: '.json' };
    }
    const compressed = jsonBlob.stream().pipeThrough(new CompressionStream('gzip'));
    return {
        blob: await new Response(compressed).blob(),
        extension: '.json.gz'
    };
}

function diagnosticFilename(bundle, extension) {
    const hostname = String(bundle?.page?.hostname || 'page').toLowerCase()
        .replace(/[^a-z0-9.-]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 80) || 'page';
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    return `sci-adapter-diagnostic-${hostname}-${timestamp}${extension}`;
}

function downloadBlob(blob, filename) {
    const objectUrl = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = objectUrl;
    link.download = filename;
    link.hidden = true;
    document.body.appendChild(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(objectUrl), 1000);
}

let adapterDiagnosticExportPending = false;

async function exportAdapterDiagnosticBundle() {
    if (adapterDiagnosticExportPending) return;
    adapterDiagnosticExportPending = true;
    const buttons = [document.getElementById('exportAdapterDiagnosticBundle')].filter(Boolean);
    buttons.forEach(button => {
        button.disabled = true;
        button.dataset.originalText ||= button.textContent;
        button.textContent = '正在生成诊断包…';
    });
    try {
        const tab = await queryPanelTargetTab();
        if (!tab?.id) throw new Error('无法获取当前论文页面');
        const response = await sendTabMessage(tab.id, {
            action: 'buildAdapterDiagnosticBundle'
        });
        if (!response?.success) {
            throw new Error(response?.error || '页面没有返回适配诊断数据');
        }
        const bundle = validateAdapterDiagnosticBundle(response.bundle);
        const currentTab = await queryPanelTargetTab();
        if (currentTab?.id !== tab.id) {
            throw new Error('活动页面已变化，请在目标论文页重新导出');
        }
        const output = await diagnosticBlob(bundle);
        const filename = diagnosticFilename(bundle, output.extension);
        downloadBlob(output.blob, filename);
        showStatus(
            `适配诊断包已导出：${bundle.publisher?.family || 'generic'} · ` +
            `${bundle.candidates?.length || 0} 个候选正文根节点`,
            'success'
        );
    } catch (error) {
        showStatus('适配诊断包导出失败：' + error.message, 'error');
    } finally {
        adapterDiagnosticExportPending = false;
        buttons.forEach(button => {
            button.disabled = false;
            button.textContent = button.dataset.originalText || '导出适配诊断包';
        });
    }
}

function stopReviewOutlineProgressPolling() {
    if (reviewOutlineProgressTimer !== null) {
        clearInterval(reviewOutlineProgressTimer);
        reviewOutlineProgressTimer = null;
    }
}

function applyReviewOutlineProgress(response, announce = true) {
    if (!response?.status || typeof response.status !== 'object') return null;
    reviewOutlineState = {
        ...reviewOutlineState,
        ...response.status,
        running: Boolean(response.status.running),
        hasOutline: Boolean(response.hasOutline || reviewOutlineState.hasOutline)
    };
    updateReviewOutlineButton();
    if (announce && reviewOutlineState.running) {
        const isRecovery = reviewOutlineState.phase === 'review_retry' ||
            reviewOutlineState.phase === 'review_split';
        const progressText = isRecovery && reviewOutlineState.message
            ? reviewOutlineState.message
            : reviewOutlineState.phase === 'review_reduce'
                ? '正在综合章节结构…'
                : reviewOutlineState.totalParagraphs > 0
                    ? `正在生成逐段摘要：${reviewOutlineState.completedParagraphs}/` +
                        `${reviewOutlineState.totalParagraphs} 段…`
                    : (reviewOutlineState.message || '正在提取正文层级…');
        showStatus(progressText, 'success');
    }
    return reviewOutlineState;
}

async function refreshReviewOutlineProgress(
    tabId,
    announce = true,
    panelContext = capturePanelContext(reviewOutlineTaskGeneration),
    expectedOperationId = ''
) {
    if (!isCurrentReviewOutlineTask(panelContext) ||
        Number(tabId) !== Number(panelContext.tabId)) return null;
    try {
        const response = await sendTabMessage(tabId, { action: 'getReviewOutlineStatus' });
        if (!isCurrentReviewOutlineTask(panelContext)) return null;
        if (!response?.success) return null;
        if (expectedOperationId && response.status?.operationId !== expectedOperationId) return null;
        // A late polling reply must not regress the confirmed terminal receipt.
        if (expectedOperationId && reviewOutlineState.operationId === expectedOperationId &&
            reviewOutlineState.phase === 'completed' && response.status?.phase !== 'completed') return null;
        const status = applyReviewOutlineProgress(response, announce);
        const checkpoint = Number(response.status?.checkpointVersion) || 0;
        const checkpointKey = JSON.stringify([panelContext.key, tabId, response.status?.operationId, checkpoint]);
        if (checkpoint > 0 && refreshReviewOutlineProgress.renderedCheckpoint !== checkpointKey) {
            await refreshArticleWorkspace({ panelContext });
            if (!isCurrentReviewOutlineTask(panelContext)) return null;
            refreshReviewOutlineProgress.renderedCheckpoint = checkpointKey;
        }
        return status;
    } catch (error) {
        return null;
    }
}

function startReviewOutlineProgressPolling(
    tabId,
    panelContext = capturePanelContext(reviewOutlineTaskGeneration),
    operationId = ''
) {
    stopReviewOutlineProgressPolling();
    let observedRunning = false;
    const poll = async () => {
        if (!isCurrentReviewOutlineTask(panelContext)) {
            stopReviewOutlineProgressPolling();
            return;
        }
        const status = await refreshReviewOutlineProgress(tabId, true, panelContext, operationId);
        if (!isCurrentReviewOutlineTask(panelContext)) return;
        if (status?.running) observedRunning = true;
        if (status && !status.running && (observedRunning ||
            operationId && status.operationId === operationId)) stopReviewOutlineProgressPolling();
    };
    void poll();
    reviewOutlineProgressTimer = setInterval(poll, 600);
}

async function restoreReviewOutlineProgress() {
    try {
        const tab = await queryPanelTargetTab();
        if (!tab?.id) return;
        const status = await refreshReviewOutlineProgress(tab.id, false);
        if (hasRunningFigureProgress(status)) {
            startReviewOutlineProgressPolling(tab.id, undefined, status.operationId || '');
            applyReviewOutlineProgress({ status, hasOutline: status.hasOutline }, true);
        }
    } catch (error) {
        // 当前网页不支持内容脚本时保留普通按钮状态。
    }
}

function stopFigureProgressPolling({ preserveTerminationObservation = false } = {}) {
    figureProgressPollingGeneration += 1;
    figureProgressRefreshSequence += 1;
    if (figureProgressTimer !== null) {
        clearInterval(figureProgressTimer);
        figureProgressTimer = null;
    }
    if (!preserveTerminationObservation) stopFigureTerminationObservation();
}

function stopFigureTerminationObservation() {
    const observation = figureTerminationObservation;
    figureTerminationObservation = null;
    if (observation?.timer !== null) clearTimeout(observation?.timer);
    if (figureNativeDiagnosticRead) {
        clearTimeout(figureNativeDiagnosticRead.timer);
        figureNativeDiagnosticRead.resolve(null);
        figureNativeDiagnosticRead = null;
    }
}

async function readFigureNativeDiagnosticStatus(tabId, timeoutMs = 2000) {
    if (figureNativeDiagnosticRead) return null;
    const read = { timer: null, resolve: null };
    figureNativeDiagnosticRead = read;
    try {
        return await Promise.race([
            Promise.resolve().then(() => sendTabMessage(tabId, { action: 'getFigureAnalysisStatus' })),
            new Promise(resolve => { read.resolve = resolve; read.timer = setTimeout(() => resolve(null), Math.max(1, Math.min(2000, timeoutMs))); })
        ]);
    } catch (_) { return null; }
    finally {
        clearTimeout(read.timer);
        if (figureNativeDiagnosticRead === read) figureNativeDiagnosticRead = null;
    }
}

function figureNativeDiagnosticText(status = {}) {
    if (status.nativeTerminationDiagnostic?.message) return status.nativeTerminationDiagnostic.message;
    const stage = status.nativeRequestDiagnostic?.stage;
    return { handshake: '正在连接本地模型桥接，尚未派发请求。',
        submitted: '已派发到本地桥接，等待上游确认开始。',
        running: '上游已开始执行；科学结果仍待返回与校验。',
        cancel_requested: '已请求停止，等待上游终止回执。',
        outcome_unknown: '上游执行结果尚未确认；原超时或取消结果保留。',
        completed: '本地响应已结束，科学结果仍须校验。' }[stage] || '';
}

function renderFigureNativeDiagnostic(status = {}) {
    const doc = globalThis.document;
    const anchor = doc?.getElementById('figureHeaderTaskStatus');
    if (!anchor?.parentNode) return;
    let line = doc.getElementById('figureNativeRequestStatus');
    if (!line) {
        line = doc.createElement('p'); line.id = 'figureNativeRequestStatus';
        line.className = 'module-task-status'; line.setAttribute('role', 'status');
        line.setAttribute('aria-live', 'polite'); anchor.after(line);
    }
    const text = figureNativeDiagnosticText(status);
    line.textContent = text; line.hidden = !text;
}

function applyFigureNativeDiagnosticSnapshot(status) {
    if (!status || status.operationId !== figureAnalysisState.operationId) return false;
    const prior = figureAnalysisState.nativeTerminationDiagnostic;
    // This read never restores running state, counters, results or retry eligibility.
    figureAnalysisState = { ...figureAnalysisState,
        nativeRequestDiagnostic: status.nativeRequestDiagnostic || null,
        nativeTerminationDiagnostic: status.nativeTerminationDiagnostic || prior || null,
        nativeTerminationObservationExpiresAt: status.nativeTerminationObservationExpiresAt || 0 };
    updateFigureButton();
    const diagnostic = status.nativeTerminationDiagnostic;
    if (diagnostic?.message && (!prior || diagnostic.requestId !== prior.requestId ||
        diagnostic.portSessionId !== prior.portSessionId || diagnostic.state !== prior.state)) {
        showStatus(diagnostic.message, diagnostic.state === 'terminal_confirmed' ? 'success' : 'warning');
    }
    return true;
}

function startFigureTerminationObservation(tabId, status, taskToken = figureTaskGeneration) {
    const operationId = status?.operationId, expiresAt = status?.nativeTerminationObservationExpiresAt;
    if (!operationId || operationId !== figureAnalysisState.operationId ||
        !Number.isFinite(expiresAt) || expiresAt <= Date.now() || expiresAt > Date.now() + 60000 ||
        !isCurrentFigureTask(taskToken, tabId)) return;
    if (figureTerminationObservation?.operationId === operationId &&
        figureTerminationObservation.taskToken === taskToken) return;
    stopFigureTerminationObservation();
    const panelContext = capturePanelContext(taskToken);
    const observation = { operationId, expiresAt, taskToken, panelContext, timer: null };
    figureTerminationObservation = observation;
    const current = () => figureTerminationObservation === observation &&
        Date.now() < expiresAt && isCurrentFigureTask(taskToken, tabId) &&
        isCurrentPanelContext(panelContext) && figureAnalysisState.operationId === operationId;
    const schedule = () => {
        if (!current()) { if (figureTerminationObservation === observation) stopFigureTerminationObservation(); return; }
        observation.timer = setTimeout(poll, Math.min(1000, expiresAt - Date.now()));
    };
    const poll = async () => {
        observation.timer = null;
        if (!current()) { if (figureTerminationObservation === observation) stopFigureTerminationObservation(); return; }
        try {
            const response = await readFigureNativeDiagnosticStatus(tabId, expiresAt - Date.now());
            if (!current()) return;
            if (response?.success && response.status?.operationId !== operationId) { stopFigureTerminationObservation(); return; }
            if (response?.success) {
                applyFigureNativeDiagnosticSnapshot(response.status);
                if (!response.status.nativeTerminationObservationExpiresAt) { stopFigureTerminationObservation(); return; }
            }
        } catch (_) { /* Read-only observation is bounded by the original native deadline. */ }
        finally { schedule(); }
    };
    schedule();
}

async function observeStoppedFigureNativeRequest(tabId, taskToken, operationId) {
    if (!operationId || !isCurrentFigureTask(taskToken, tabId)) return;
    const context = capturePanelContext(taskToken);
    try {
        const response = await readFigureNativeDiagnosticStatus(tabId);
        if (!isCurrentFigureTask(taskToken, tabId) || !isCurrentPanelContext(context) ||
            figureAnalysisState.operationId !== operationId || !response?.success ||
            response.status?.operationId !== operationId) return;
        applyFigureNativeDiagnosticSnapshot(response.status);
        startFigureTerminationObservation(tabId, response.status, taskToken);
    } catch (_) { /* No task work or retry is triggered by a missing diagnostic. */ }
}

let activeFigureVisionDialog = null;
const shownFigureVisionDecisions = new Set();
function maybeShowFigureVisionConfirmation(status) {
    const decision=getFigureProgressEntries(status).map(item=>item.visionConfirmation).find(Boolean);
    if (!decision || shownFigureVisionDecisions.has(decision.id)) return;
    const panelContext=capturePanelContext();
    if (Number(panelContext.tabId)!==decision.tabId) return;
    // Pin this live UI before any asynchronous Figure validation. A replacement
    // panel must never be adopted when the user eventually answers this dialog.
    const uiOwner = typeof chrome.runtime.getContexts === 'function'
        ? captureFigureUiOwnerBinding().then(binding=>({binding}),error=>({error}))
        : Promise.resolve({binding:null});
    shownFigureVisionDecisions.add(decision.id);
    if (shownFigureVisionDecisions.size>128) shownFigureVisionDecisions.delete(shownFigureVisionDecisions.values().next().value);
    if (activeFigureVisionDialog) activeFigureVisionDialog.finish('pause');
    const dialog=document.createElement('dialog');dialog.className='confirmation-dialog';
    const box=document.createElement('div');box.className='confirmation-dialog-content';
    const title=document.createElement('h3');title.textContent='继续文字解读？';
    const description=document.createElement('p');
    const label=decision.figureLabel || decision.figureId || '此 Figure';
    description.textContent=decision.reason==='runtime_vision_unsupported'
        ? `当前模型无法读取 ${label} 的图片。可继续依据图注与正文解读，图像细节将无法核对。`
        : decision.reason==='image_unavailable'
        ? `未能获取 ${label} 的图片。可继续依据图注与正文解读，图像细节将无法核对。`
        : `未能完成 ${label} 的图片解读。可继续依据图注与正文解读，图像细节将无法核对。`;
    const actions=document.createElement('div');actions.className='confirmation-dialog-actions';
    const pause=document.createElement('button');pause.type='button';pause.textContent='暂停';pause.autofocus=true;
    const proceed=document.createElement('button');proceed.type='button';proceed.textContent='继续文字解读';
    actions.append(pause,proceed);box.append(title,description,actions);dialog.append(box);document.body.append(dialog);
    const session={settled:false,finish:async choice=>{
        if(session.settled)return;session.settled=true;pause.disabled=true;proceed.disabled=true;
        let pdfTextEnvelope;
        if(choice==='continue_text') {
            try {
                const current=await sendTabMessage(decision.tabId,{action:decision.pdfContinuationRequired
                    ? 'prepareFigurePdfTextContinuation' : 'validateFigureVisionConfirmation',
                    id:decision.id,operationId:decision.operationId});
                if(!current?.success || session.closed || !isCurrentPanelContext(panelContext) ||
                    (decision.pdfContinuationRequired && !current.pdfTextEnvelope))choice='pause';
                else pdfTextEnvelope=current.pdfTextEnvelope;
            }catch(_){choice='pause';}
        }
        clearInterval(timer);window.removeEventListener('pagehide',onHide);
        if(dialog.open)dialog.close();dialog.remove();
        if(activeFigureVisionDialog===session)activeFigureVisionDialog=null;
        try {
            const owner=await uiOwner;
            if(owner.error || session.pageHidden || !isCurrentPanelContext(panelContext))return;
            const result=await chrome.runtime.sendMessage({type:'LLM_CONTROL_OPERATION',command:'figure-vision-decision',
                operationScope:'figure',operationId:decision.operationId,tabId:decision.tabId,
                ...(owner.binding ? {figureUiOwnerBinding:owner.binding} : {}),
                visionDecisionId:decision.id,choice,
                ...(choice==='continue_text' && pdfTextEnvelope ? {pdfTextEnvelope} : {})});
            if(!result?.success && isCurrentPanelContext(panelContext))showStatus('本次确认已失效，Figure 解读保持暂停。','warning');
        }catch(_){if(isCurrentPanelContext(panelContext))showStatus('Figure 解读保持暂停。','warning');}
    }};
    const onHide=()=>{session.pageHidden=true;session.closed=true;void session.finish('pause');};
    const timer=setInterval(()=>{if(!isCurrentPanelContext(panelContext))void session.finish('pause');},250);
    pause.addEventListener('click',event=>{if(event.isTrusted)void session.finish('pause');});
    proceed.addEventListener('click',event=>{if(event.isTrusted)void session.finish('continue_text');});
    dialog.addEventListener('cancel',()=>{session.closed=true;void session.finish('pause');});
    dialog.addEventListener('close',()=>{session.closed=true;void session.finish('pause');});
    window.addEventListener('pagehide',onHide,{once:true});
    activeFigureVisionDialog=session;dialog.showModal();
}


function applyFigureAnalysisProgress(status, announce = true) {
    if (!status || typeof status !== 'object') return null;
    if (figureAnalysisState.operationId && status.operationId &&
        status.operationId !== figureAnalysisState.operationId) {
        stopFigureTerminationObservation();
        figureAnalysisState = { ...figureAnalysisState, nativeRequestDiagnostic: null,
            nativeTerminationDiagnostic: null, nativeTerminationObservationExpiresAt: 0 };
    }
    const running = hasRunningFigureProgress(status);
    const figureProgress = getFigureProgressEntries(status).map(item => ({
        ...item,
        running: running ? item.running === true : false
    }));
    const snapshot = { ...status, figureProgress };
    maybeShowFigureVisionConfirmation(snapshot);
    figureAnalysisState = {
        ...figureAnalysisState,
        ...snapshot,
        running
    };
    updateFigureButton();
    updateReviewOutlineButton();
    if (!running && status.operationId) {
        startFigureTerminationObservation(activePanelTabContext.tabId, status);
    }
    const renderSignature = figureProgressUiSignature(figureAnalysisState);
    if (renderSignature !== figureProgressRenderSignature) {
        figureProgressRenderSignature = renderSignature;
        renderFigureWorkspaceSnapshot(currentWorkspaceSnapshot);
    } else {
        updateFigureElapsedLabels(figureAnalysisState);
    }
    if (announce && figureAnalysisState.running) {
        const activeProgress = figureProgress.find(item => item?.running === true) ||
            figureProgress[figureProgress.length - 1];
        const message = activeProgress
            ? `${activeProgress.figureLabel || activeProgress.figureId || 'Figure'}：` +
                formatFigureProgress(activeProgress).phaseText
            : figureAnalysisState.message || (
            figureAnalysisState.totalFigures > 0 && figureAnalysisState.currentFigure > 0
                ? `正在处理第 ${figureAnalysisState.currentFigure}/${figureAnalysisState.totalFigures} 张：` +
                    (figureAnalysisState.figureLabel || 'Figure')
                : '正在读取论文中的 Figure…');
        showStatus(message, 'success');
    }
    return figureAnalysisState;
}

async function refreshFigureAnalysisProgress(tabId, announce = true, taskToken = figureTaskGeneration) {
    const requestSequence = ++figureProgressRefreshSequence;
    try {
        const response = await sendTabMessage(tabId, {
            action: 'getFigureAnalysisStatus'
        });
        if (requestSequence !== figureProgressRefreshSequence) return null;
        if (!isCurrentFigureTask(taskToken, tabId)) return null;
        if (!response?.success) return null;
        const applied = applyFigureAnalysisProgress(response.status, announce);
        const signature = getFigureProgressEntries(applied).map(progress => [
            progress.figureId,
            progress.phase,
            progress.completedPanelBatches || 0,
            progress.recognizedPanelCount || 0,
            progress.completed === true
        ].join(':')).sort().join('|');
        const hasFreshResult = getFigureProgressEntries(applied).some(progress =>
            progress.phase === 'figure_panel_batch_complete' || progress.phase === 'figure'
        );
        if (hasFreshResult && signature && signature !== figureWorkspaceProgressSignature) {
            figureWorkspaceProgressSignature = signature;
            await refreshArticleWorkspace({ panelContext: capturePanelContext(taskToken) });
        }
        return applied;
    } catch (error) {
        return null;
    }
}

function startFigureProgressPolling(tabId, { waitForSnapshot = false } = {}) {
    stopFigureTerminationObservation();
    if (figureProgressTimer !== null) return;
    const taskToken = figureTaskGeneration;
    const pollingGeneration = ++figureProgressPollingGeneration;
    let receivedRunningSnapshot = !waitForSnapshot;
    let pollInFlight = false;
    let pollSequence = 0;
    const poll = async () => {
        if (pollInFlight) return;
        pollInFlight = true;
        const currentPoll = ++pollSequence;
        try {
            const status = await refreshFigureAnalysisProgress(tabId, true, taskToken);
            if (pollingGeneration !== figureProgressPollingGeneration ||
                currentPoll !== pollSequence || !isCurrentFigureTask(taskToken, tabId)) return;
            if (status && hasRunningFigureProgress(status)) receivedRunningSnapshot = true;
            if (status && receivedRunningSnapshot && !hasRunningFigureProgress(status)) {
                stopFigureProgressPolling({ preserveTerminationObservation: true });
            }
        } finally {
            pollInFlight = false;
        }
    };
    void poll();
    figureProgressTimer = setInterval(poll, 600);
}

async function restoreFigureAnalysisProgress() {
    try {
        const tab = await queryPanelTargetTab();
        if (!tab?.id) return;
        const status = await refreshFigureAnalysisProgress(tab.id, false);
        if (hasRunningFigureProgress(status)) {
            startFigureProgressPolling(tab.id);
            applyFigureAnalysisProgress(status, true);
        }
    } catch (error) {
        // 当前网页不支持内容脚本时保持普通按钮状态。
    }
}

globalThis.addEventListener?.('beforeunload', stopFigureProgressPolling);
globalThis.addEventListener?.('unload', stopFigureProgressPolling);
globalThis.addEventListener?.('pagehide', stopFigureProgressPolling);

async function updateLlmPreferencesCore(preferences) {
    llmSettingsState = await sendLlmMessage({
        type: 'LLM_UPDATE_PREFERENCES',
        preferences
    });
    return llmSettingsState;
}

async function updateViewCategorySelection(categoryId, checked, targetViewId) {
    const modes = (llmSettingsState?.settings?.analysisModes || []).map(mode => ({
        ...mode,
        categoryIds: Array.isArray(mode.categoryIds) ? [...mode.categoryIds] : []
    }));
    const mode = modes.find(item => item.id === targetViewId);
    if (!mode) throw new Error('分析模式不存在');
    const selected = new Set(mode.categoryIds);
    if (checked) selected.add(categoryId);
    else selected.delete(categoryId);
    mode.categoryIds = [...selected];
    return updateLlmPreferencesCore({
        analysisModes: modes,
        viewCategoryOverrides: {
            ...(llmSettingsState?.settings?.viewCategoryOverrides || {}),
            [targetViewId]: { add: [], remove: [] }
        }
    });
}

function applyPreparedComposition(prepared, document) {
    preparedDocumentState = { ...prepared, document };
    currentArticleDocument = document;
    prepareState = 'prepared';
    syncPreparedSelection();
    renderCategories();
    updateApplyButton();
    void restoreHighlightPresentationState().catch(() => undefined);
}

function queueReadingViewMutation(targetViewId) {
    const intent = preferenceMutationCoordinator.beginIntent();
    readingViewId = targetViewId;
    presentationDensity = 'all';
    hiddenDisplayFamilyIds = new Set();
    void restoreHighlightPresentationState().catch(() => undefined);
    reconcileRegexSelection();
    updateReadingViewControl();
    return runSavedMutation({
        coordinator: preferenceMutationCoordinator,
        intent,
        save: () => updateLlmPreferencesCore({ readingViewId: targetViewId }),
        onSaved: (saved, { isCurrent }) => {
            reconcilePersistedLlmControls(saved, isCurrent);
            persistedReadingViewId = saved.settings.readingViewId || targetViewId;
            if (analysisMode === 'llm') invalidatePreparedComposition();
            else reconcileRegexSelection();
            if (isCurrent()) {
                updateReadingViewControl();
                renderCategories();
                updateApplyButton();
            }
        },
        refresh: (_saved, { isCurrent }) => analysisMode === 'llm'
            ? refreshPreparedComposition({
                isCurrent,
                expectedViewId: targetViewId
            })
            : Promise.resolve({ prepared: false }),
        onSaveFailed: () => {
            readingViewId = persistedReadingViewId;
            updateReadingViewControl();
            if (analysisMode === 'llm') syncPreparedSelection();
            else reconcileRegexSelection();
            renderCategories();
            updateApplyButton();
            showStatus('切换分析模式失败，已恢复原选择', 'error');
        },
        onRefreshFailed: error => {
            renderCategories();
            updateApplyButton();
            showStatus(`分析模式已保存，但正文组合刷新失败：${error.message}`, 'error');
        }
    }).then(result => {
        if (result.status === 'refreshed') {
            const viewName = llmSettingsState?.readingViews?.[targetViewId]?.name || targetViewId;
            showStatus(`已切换到${viewName}`, 'success');
        }
        return result;
    });
}

function queueCategorySelectionMutation(categoryId, checked, targetViewId) {
    const intent = preferenceMutationCoordinator.beginIntent();
    const llmSelection = analysisMode === 'llm';
    return runSavedMutation({
        coordinator: preferenceMutationCoordinator,
        intent,
        save: () => updateViewCategorySelection(categoryId, checked, targetViewId),
        onSaved: (saved, { isCurrent }) => {
            reconcilePersistedLlmControls(saved, isCurrent);
            if (llmSelection) invalidatePreparedComposition();
            else reconcileRegexSelection();
            if (isCurrent()) {
                renderCategories();
                updateApplyButton();
            }
        },
        refresh: (_saved, { isCurrent }) => llmSelection
            ? refreshPreparedComposition({
                isCurrent,
                expectedViewId: targetViewId
            })
            : Promise.resolve({ prepared: false }),
        onSaveFailed: () => {
            if (llmSelection) syncPreparedSelection();
            else reconcileRegexSelection();
            renderCategories();
            updateApplyButton();
            showStatus('保存分类失败，已恢复原选择', 'error');
        },
        onRefreshFailed: error => {
            renderCategories();
            updateApplyButton();
            showStatus(`分类已保存，但正文组合刷新失败：${error.message}`, 'error');
        }
    });
}

function queueRestoreViewPreset(targetViewId) {
    const intent = preferenceMutationCoordinator.beginIntent();
    const llmSelection = analysisMode === 'llm';
    return runSavedMutation({
        coordinator: preferenceMutationCoordinator,
        intent,
        save: () => {
            const fallback = (llmSettingsState?.analysisModeDefaults || [])
                .find(mode => mode.id === targetViewId);
            if (!fallback) throw new Error('自定义分析模式没有内置预设');
            const modes = (llmSettingsState?.settings?.analysisModes || []).map(mode =>
                mode.id === targetViewId
                    ? { ...mode, categoryIds: [...fallback.categoryIds] }
                    : { ...mode, categoryIds: [...(mode.categoryIds || [])] }
            );
            return updateLlmPreferencesCore({
                analysisModes: modes,
                viewCategoryOverrides: {
                    ...(llmSettingsState?.settings?.viewCategoryOverrides || {}),
                    [targetViewId]: { add: [], remove: [] }
                }
            });
        },
        onSaved: (saved, { isCurrent }) => {
            reconcilePersistedLlmControls(saved, isCurrent);
            if (llmSelection) invalidatePreparedComposition();
            else reconcileRegexSelection();
            if (isCurrent()) {
                renderCategories();
                updateApplyButton();
            }
        },
        refresh: (_saved, { isCurrent }) => llmSelection
            ? refreshPreparedComposition({
                isCurrent,
                expectedViewId: targetViewId
            })
            : Promise.resolve({ prepared: false }),
        onSaveFailed: () => {
            if (llmSelection) syncPreparedSelection();
            else reconcileRegexSelection();
            renderCategories();
            updateApplyButton();
            showStatus('恢复预设失败，已保留原分类选择', 'error');
        },
        onRefreshFailed: error => {
            renderCategories();
            updateApplyButton();
            showStatus(`预设已保存，但正文组合刷新失败：${error.message}`, 'error');
        }
    });
}

function reconcilePersistedLlmControls(saved, isCurrent) {
    const savedSettings = saved?.settings || {};
    persistedAnalysisMode = savedSettings.mode || persistedAnalysisMode;
    const savedConfidence = Number(savedSettings.confidenceThreshold);
    if (Number.isFinite(savedConfidence)) {
        persistedConfidenceThreshold = savedConfidence;
    }
    if (!isCurrent()) return;
    analysisMode = persistedAnalysisMode;
    confidenceThreshold = persistedConfidenceThreshold;
    const modeRadio = document.querySelector(
        `input[name="analysisMode"][value="${analysisMode}"]`
    );
    if (modeRadio) modeRadio.checked = true;
    matchCounts = {};
    updateAnalysisModeUi();
    renderCategories();
}

function queueAnalysisModeMutation(targetMode) {
    regexApplySequence += 1;
    const intent = preferenceMutationCoordinator.beginIntent();
    analysisMode = targetMode;
    if (targetMode === 'regex') reconcileRegexSelection();
    const modeRadio = document.querySelector(
        `input[name="analysisMode"][value="${targetMode}"]`
    );
    if (modeRadio) modeRadio.checked = true;
    matchCounts = {};
    updateAnalysisModeUi();
    renderCategories();

    return runSavedMutation({
        coordinator: preferenceMutationCoordinator,
        intent,
        save: () => updateLlmPreferencesCore({ mode: targetMode }),
        onSaved: (saved, { isCurrent }) => {
            reconcilePersistedLlmControls(saved, isCurrent);
            if (isCurrent() && saved.settings.mode === 'llm') {
                invalidatePreparedComposition();
            } else if (isCurrent()) {
                reconcileRegexSelection();
            }
        },
        refresh: async (saved, { isCurrent }) => {
            if (saved.settings.mode !== 'llm' || saved.effectiveMode !== 'llm') {
                prepareState = 'idle';
                stopFigureProgressPolling();
                stopReviewOutlineProgressPolling();
                requestMatchCounts();
                return { prepared: false };
            }
            return prepareCurrentArticleCore({
                isCurrent,
                expectedViewId: readingViewId
            });
        },
        onSaveFailed: () => {
            analysisMode = persistedAnalysisMode;
            confidenceThreshold = persistedConfidenceThreshold;
            const rollbackRadio = document.querySelector(
                `input[name="analysisMode"][value="${analysisMode}"]`
            );
            if (rollbackRadio) rollbackRadio.checked = true;
            updateAnalysisModeUi();
            renderCategories();
            showStatus('无法切换识别模式，已恢复原设置', 'error');
        },
        onRefreshFailed: error => {
            prepareState = 'idle';
            updateApplyButton();
            showStatus(`识别模式已保存，但正文准备失败：${error.message}`, 'error');
        }
    }).then(async result => {
        if (!preferenceMutationCoordinator.isCurrent(intent)) return result;
        if (analysisMode === 'llm' && result.status === 'refreshed') {
            await refreshLlmDiagnostics();
            await restoreFigureAnalysisProgress();
            await restoreReviewOutlineProgress();
        }
        return result;
    });
}

function queueConfidenceThresholdMutation(targetThreshold) {
    const intent = preferenceMutationCoordinator.beginIntent();
    confidenceThreshold = targetThreshold;
    renderConfidenceControl();

    return runSavedMutation({
        coordinator: preferenceMutationCoordinator,
        intent,
        save: () => updateLlmPreferencesCore({
            confidenceThreshold: targetThreshold
        }),
        onSaved: (saved, { isCurrent }) => {
            reconcilePersistedLlmControls(saved, isCurrent);
        },
        refresh: async (saved, { isCurrent }) => {
            if (saved.settings.mode === 'llm' && saved.effectiveMode === 'llm') {
                await prepareCurrentArticleCore({
                    isCurrent,
                    expectedViewId: readingViewId
                });
            }
            if (!isCurrent()) return { applied: false, reason: 'superseded' };
            const tab = await queryPanelTargetTab();
            if (!tab?.id) throw new Error('无法获取当前论文页面');
            const response = await sendTabMessage(tab.id, {
                action: 'applyLlmConfidenceThreshold',
                threshold: targetThreshold
            });
            if (isCurrent() && response?.applied) {
                matchCounts = response.counts || matchCounts;
                presentationFamilyCounts = response.familyCounts || {};
                renderCategories();
            }
            return response;
        },
        onSaveFailed: () => {
            confidenceThreshold = persistedConfidenceThreshold;
            analysisMode = persistedAnalysisMode;
            const rollbackRadio = document.querySelector(
                `input[name="analysisMode"][value="${analysisMode}"]`
            );
            if (rollbackRadio) rollbackRadio.checked = true;
            updateAnalysisModeUi();
            renderCategories();
            showStatus('置信度保存失败，已恢复原设置', 'error');
        },
        onRefreshFailed: () => {
            renderConfidenceControl();
            showStatus('置信度已保存；刷新论文页面后重新分析即可应用', 'success');
        }
    }).then(async result => {
        if (!preferenceMutationCoordinator.isCurrent(intent)) return result;
        if (result.status === 'refreshed') {
            await refreshLlmDiagnostics();
            showStatus(
                `最低置信度已设为 ${Math.round(confidenceThreshold * 100)}%`,
                'success'
            );
        }
        return result;
    });
}

async function prepareArticleForAdaptiveAnalysis(tabId, {
    isCurrent = () => true,
    expectedViewId = readingViewId,
    forceRefresh = false
} = {}) {
    prepareState = 'preparing';
    updateApplyButton();
    const extracted = await sendTabMessage(tabId, {
        action: 'extractArticleForLLM',
        forceRefresh
    });
    if (!extracted?.success || !extracted.document?.paragraphs?.length) {
        throw new Error(extracted?.error || '未提取到论文正文');
    }
    if (!isCurrent()) return { stale: true };
    currentArticleDocument = extracted.document;
    const prepared = await sendLlmMessage({
        type: 'LLM_PREPARE_DOCUMENT',
        document: {
            title: extracted.document.title,
            paragraphs: extracted.document.paragraphs
        }
    });
    if (!shouldApplyPreparedResult({
        isCurrent: isCurrent(),
        expectedDocumentHash: null,
        expectedViewId,
        prepared
    })) {
        return { ...prepared, stale: true };
    }
    applyPreparedComposition(prepared, extracted.document);
    if (!isCurrent()) return { ...prepared, stale: true };
    await refreshManualAnnotationSummary(tabId);
    if (!isCurrent()) return { ...prepared, stale: true };
    return prepared;
}

async function prepareCurrentArticleCore({
    isCurrent = () => true,
    expectedViewId = readingViewId,
    forceRefresh = false
} = {}) {
    const tab = await queryPanelTargetTab();
    if (!tab?.id) throw new Error('无法获取当前论文页面');
    return prepareArticleForAdaptiveAnalysis(tab.id, {
        isCurrent,
        expectedViewId,
        forceRefresh
    });
}

async function prepareCurrentArticleForTypeChoice({
    throwOnError = false,
    forceRefresh = false
} = {}) {
    if (analysisMode !== 'llm' || llmSettingsState?.effectiveMode !== 'llm' ||
        prepareState === 'preparing' || prepareState === 'analyzing') return null;
    const intent = preferenceMutationCoordinator.beginIntent();
    const expectedViewId = readingViewId;
    lastArticlePreparationError = null;
    try {
        const prepared = await preferenceMutationCoordinator.enqueue(
            intent,
            ({ isCurrent }) => prepareCurrentArticleCore({
                isCurrent,
                expectedViewId,
                forceRefresh
            })
        );
        return prepared;
    } catch (error) {
        lastArticlePreparationError = error;
        if (preferenceMutationCoordinator.isCurrent(intent)) {
            prepareState = 'idle';
            updateApplyButton();
            showStatus(`正文准备失败：${error.message}`, 'error');
        }
        if (throwOnError) throw error;
        return null;
    }
}

async function refreshPreparedComposition({
    isCurrent = () => true,
    expectedViewId = readingViewId
} = {}) {
    const document = currentArticleDocument || preparedDocumentState?.document;
    if (!document) {
        syncPreparedSelection();
        renderCategories();
        return { applied: false, reason: 'document_unavailable' };
    }
    const expectedDocumentHash = preparedDocumentState?.documentHash || null;
    const prepared = await sendLlmMessage({
        type: 'LLM_PREPARE_DOCUMENT',
        document: {
            title: document.title,
            paragraphs: document.paragraphs
        }
    });
    const applies = shouldApplyPreparedResult({
        isCurrent: isCurrent(),
        expectedDocumentHash,
        expectedViewId,
        prepared
    });
    if (!applies) {
        if (!isCurrent()) return { applied: false, reason: 'superseded' };
        throw new Error('返回的正文组合与当前文献或分析模式不一致');
    }
    applyPreparedComposition(prepared, document);
    return { applied: true, prepared };
}

function confidenceDistributionContextKey() {
    return JSON.stringify([capturePanelContext()?.key || '', tabContextSequence,
        currentWorkspaceSnapshot?.documentId || '', currentWorkspaceSnapshot?.documentHash || '',
        readingViewId, presentationDensity, [...hiddenDisplayFamilyIds].sort()]);
}

async function refreshConfidenceDistribution({ force = false } = {}) {
    if (analysisMode !== 'llm') return;
    const key = confidenceDistributionContextKey();
    if (!force && confidenceDistributionState?.key === key) return;
    const sequence = ++confidenceDistributionRequest;
    confidenceDistributionState = { key, status:'loading' };
    renderConfidenceDistribution();
    try {
        const tab = await queryPanelTargetTab();
        if (!tab?.id) throw new Error('NO_TAB');
        const response = await sendTabMessage(tab.id, { action:'getLlmConfidenceDistribution' });
        if (sequence !== confidenceDistributionRequest || key !== confidenceDistributionContextKey()) return;
        if (!response?.success) throw new Error('UNAVAILABLE');
        const data = response.distribution;
        confidenceDistributionState = { key, status:'ready', data:
            data?.available && data.readingViewId === readingViewId ? data : null,
            reason:data?.reason || '' };
    } catch (_) {
        if (sequence !== confidenceDistributionRequest || key !== confidenceDistributionContextKey()) return;
        confidenceDistributionState = { key, status:'error' };
    }
    renderConfidenceDistribution();
}

function renderConfidenceDistribution() {
    const plot = document.getElementById('confidenceDistributionPlot');
    const summary = document.getElementById('confidenceDistributionSummary');
    const empty = document.getElementById('confidenceDistributionEmpty');
    if (!plot || !summary || !empty) return;
    const key = confidenceDistributionContextKey();
    const state = confidenceDistributionState?.key === key ? confidenceDistributionState : null;
    plot.replaceChildren();
    const selected = [...getConfiguredViewSelection()];
    const data = state?.data;
    const distribution = SciLLM.buildConfidenceSentenceDistribution(data?.groups, confidenceThreshold, selected);
    const ready = state?.status === 'ready' && data;
    summary.textContent = ready ? `保留 ${distribution.kept} 句 · 排除 ${distribution.excluded} 句` : '';
    empty.hidden = Boolean(ready && distribution.total);
    plot.hidden = !empty.hidden;
    if (!empty.hidden) {
        empty.textContent = !selected.length ? '勾选类别后查看分布' :
            !state || state.status === 'loading' ? '正在读取本地匹配分数…' :
            state.status === 'error' ? '分数分布暂不可用' :
            state.reason === 'PDF_PREVIEW_UNAVAILABLE' ? 'PDF 分数预览暂不可用；阈值筛选仍可使用' :
            !data ? '当前情境暂无分析结果' : '当前类别暂无可呈现的高亮句子';
    } else {
        const maximum = Math.max(1, ...distribution.bins.map(bin => bin.count));
        const categoryMap = new Map(getCategoryEntriesForEngine('llm', { includeUnsupported:true }));
        const bars = document.createElement('ol'); bars.className = 'confidence-distribution-bars';
        bars.setAttribute('aria-label', '本地匹配分数分布，按句子去重');
        for (const bin of distribution.bins) {
            const column = document.createElement('li'); column.className = 'confidence-distribution-bin';
            const description = `${Math.round(bin.lower*100)}–${Math.round(bin.upper*100)}分：${bin.count}句，保留${bin.kept}句，排除${bin.excluded}句`;
            column.title = description; column.setAttribute('aria-label', description);
            const count = document.createElement('span'); count.className = 'confidence-distribution-count';
            count.textContent = bin.count ? String(bin.count) : '';
            const stack = document.createElement('span'); stack.className = 'confidence-distribution-stack';
            stack.style.height = `${bin.count / maximum * 44}px`;
            for (const category of bin.categories) {
                const metadata = categoryMap.get(category.categoryId) || {};
                const name = metadata.name || category.categoryId;
                for (const [field, cls] of [['kept','is-kept'],['excluded','is-excluded']]) {
                    if (!category[field]) continue;
                    const segment = document.createElement('span'); segment.className = cls;
                    segment.dataset.categoryId = category.categoryId;
                    segment.dataset.count = String(category[field]);
                    const color = CSS.supports('color', metadata.color || '') ? metadata.color : '#2f80ed';
                    segment.style.setProperty('--confidence-category-color', color);
                    segment.style.height = `${category[field]/bin.count*100}%`;
                    const label = `${Math.round(bin.lower*100)}–${Math.round(bin.upper*100)}分 · ${name} · ${field === 'kept' ? '保留' : '排除'} ${category[field]}句`;
                    segment.title = label;
                    segment.setAttribute('aria-label', label);
                    segment.setAttribute('role', 'img');
                    stack.appendChild(segment);
                }
            }
            column.append(count, stack); bars.appendChild(column);
        }
        const marker = document.createElement('span'); marker.className = 'confidence-distribution-threshold';
        marker.style.left = `${(distribution.threshold-.5)/.5*100}%`;
        marker.setAttribute('aria-label',`当前阈值 ${Math.round(distribution.threshold*100)}分`);
        plot.append(bars,marker);
        plot.setAttribute('aria-label',`可定位高亮 ${distribution.total} 句；当前阈值保留 ${distribution.kept} 句，排除 ${distribution.excluded} 句`);
    }
    if (analysisMode === 'llm' && !state) void refreshConfidenceDistribution();
}

function renderConfidenceControl() {
    const slider = document.getElementById('confidenceThreshold');
    slider.value = String(confidenceThreshold);
    document.getElementById('confidenceValue').textContent =
        `${Math.round(confidenceThreshold * 100)}%`;
    renderConfidenceDistribution();
}

function updateAnalysisModeUi() {
    const isLlm = analysisMode === 'llm';
    document.getElementById('spanModeSection').hidden = isLlm;
    document.getElementById('llmAdaptiveControls').hidden = false;
    const hasPreset = (llmSettingsState?.analysisModeDefaults || [])
        .some(mode => mode.id === readingViewId);
    document.getElementById('restoreViewPreset').hidden = !hasPreset;
    document.getElementById('llmDiagnostics').hidden = !isLlm;
    document.getElementById('confidenceControl').hidden = !isLlm;
    updateReadingViewControl();
    renderHighlightPresentationControls();
    updateApplyButton();
    updateFigureButton();
    updateReviewOutlineButton();
    renderConfidenceControl();
}

async function refreshLlmDiagnostics() {
    void refreshConfidenceDistribution({ force:true });
    const element = document.getElementById('llmDiagnostics');
    if (analysisMode !== 'llm') {
        element.hidden = true;
        return;
    }
    element.hidden = false;
    element.textContent = '正在读取当前页面的正文提取诊断…';
    try {
        const tab = await queryPanelTargetTab();
        const response = await sendTabMessage(tab.id, { action: 'getLlmDiagnostics' });
        if (!response?.success) throw new Error(response?.error || '诊断不可用');
        const diagnostics = response.diagnostics || {};
        const extraction = diagnostics.extraction || {};
        const selected = extraction.selected || {};
        const parts = [
            `提取器 ${extraction.version || '未知'}`,
            `候选区 ${extraction.candidateCount ?? 0}`,
            `已选 ${extraction.selectedRoot || '未知'}`,
            `正文 ${selected.paragraphCount ?? 0} 段`,
            '图注不参与分析',
            `共 ${selected.characterCount ?? 0} 字符`
        ];
        const unrecognized = Array.isArray(extraction.unrecognizedTextBlocks)
            ? extraction.unrecognizedTextBlocks
            : [];
        if (unrecognized.length) {
            const patterns = unrecognized.slice(0, 4)
                .map(item => `${item.root}×${item.count}/${item.characterCount}字`)
                .join('；');
            parts.push(
                `未识别长文本 ${extraction.unrecognizedTextBlockCount ?? 0} 块/` +
                `${extraction.unrecognizedCharacterCount ?? 0} 字：${patterns}`
            );
        }
        if (diagnostics.studyProfile) {
            const profile = diagnostics.studyProfile;
            const primaryName = llmSettingsState?.studyTypes?.[profile.primaryType]?.name ||
                profile.primaryType;
            parts.push(`类型 ${primaryName}（用户选择）`);
            parts.push(`模式 ${llmSettingsState?.readingViews?.[diagnostics.readingViewId]?.name || diagnostics.readingViewId}`);
            parts.push('类型已选择');
        }
        if (Number.isInteger(diagnostics.annotationCount)) {
            parts.push(`模型返回 ${diagnostics.annotationCount} 条`);
            parts.push(`成功应用 ${diagnostics.highlightedCount ?? 0} 条`);
            parts.push(`定位拒绝 ${diagnostics.rejectedCount ?? 0} 条`);
            parts.push(`阈值 ${Math.round((diagnostics.confidenceThreshold || 0.8) * 100)}%`);
            parts.push(`低于阈值隐藏 ${diagnostics.hiddenConfidenceCount || 0} 条`);
            parts.push(`呈现层隐藏 ${diagnostics.hiddenPresentationCount || 0} 条`);
            parts.push(`语义拒绝 ${diagnostics.semanticRejectedCount || 0} 条`);
            parts.push(diagnostics.ledgerAvailable === false ? '台账复核不可用' :
                `台账关系 ${diagnostics.relationCount || 0} 条/审读 ${diagnostics.auditItemCount || 0} 条`);
        }
        element.textContent = parts.join('｜');
    } catch (error) {
        element.textContent = '提取诊断不可用，请刷新论文页面后重新打开插件。';
    }
}

// 渲染类别列表
function getLlmCategoryEntries() {
    return getCategoryEntriesForEngine('llm');
}

function openCategoryRuleEditor(categoryId) {
    const url = chrome.runtime.getURL('options.html#page=categories&category=' +
        encodeURIComponent(categoryId));
    return chrome.tabs.create({ url }).catch(error => {
        showStatus(`无法打开分类规则设置：${error.message}`, 'error');
        return null;
    });
}

function createCategoryItem(key, rule, { checked, idSuffix = '' } = {}) {
        const builtinName = SciLLM.getBuiltinCatalog?.('zh-CN')?.categories?.[key]?.name;
        const customName = rule.builtIn === false || rule.isBuiltIn === false || !builtinName || rule.name !== builtinName;
        const item = document.createElement('div');
        item.className = analysisMode === 'llm'
            ? 'category-item category-item-compact'
            : 'category-item';
        
        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.id = `cat-${key}${idSuffix}`;
        checkbox.checked = Boolean(checked);
        checkbox.setAttribute('aria-label', `${checkbox.checked ? '停用' : '启用'}${rule.name}`);
        if (customName) {
            checkbox.setAttribute('aria-label', `${t(checkbox.checked ? '停用' : '启用')} ${rule.name}`);
            checkbox.setAttribute('translate', 'no');
        }
        checkbox.addEventListener('change', async (e) => {
            const targetViewId = readingViewId;
            try {
                await queueCategorySelectionMutation(
                    key,
                    e.target.checked,
                    targetViewId
                );
                if (analysisMode === 'regex') {
                    await saveSettings();
                }
            } catch (error) {
                if (analysisMode === 'llm') syncPreparedSelection();
                else reconcileRegexSelection();
                renderCategories();
                showStatus(`保存分类失败，已恢复原选择：${error.message}`, 'error');
            }
        });

        const colorDiv = document.createElement('div');
        colorDiv.className = 'category-color';
        colorDiv.style.backgroundColor = rule.color;
        
        const infoDiv = document.createElement('div');
        infoDiv.className = 'category-info';
        
        const nameDiv = document.createElement('div');
        nameDiv.className = 'category-name';
        nameDiv.textContent = rule.name;
        if (customName) nameDiv.setAttribute('translate', 'no');
        
        // 显示匹配计数
        if (matchCounts[key] !== undefined && matchCounts[key] > 0) {
            const matchBadge = document.createElement('span');
            matchBadge.className = 'match-count';
            matchBadge.textContent = matchCounts[key];
            nameDiv.appendChild(matchBadge);
        }
        
        const countDiv = document.createElement('div');
        countDiv.className = 'category-count';
        const engines = Array.isArray(rule.enabledEngines)
            ? rule.enabledEngines : ['llm', 'regex'];
        const supportedByCurrentEngine = engines.includes(analysisMode);
        if (analysisMode === 'llm') {
            const sourceLabels = {
                view_default: '视图预设',
                primary_type: '主要类型',
                manual: '用户添加'
            };
            const source = sourceLabels[getPreparedCategorySource(key)] ||
                ((getReadingViewDefinition().categoryIds || []).includes(key)
                    ? '视图预设' : '可选类别');
            countDiv.textContent = rule.persistence === 'one-off'
                ? `${source} · 仅本次会话`
                : `${source} · LLM 语义识别`;
        } else {
            countDiv.textContent = supportedByCurrentEngine
                ? (rule.persistence === 'one-off' ? '正则识别 · 仅本次会话' : '正则识别')
                : '需要 LLM 识别';
        }
        
        infoDiv.appendChild(nameDiv);
        infoDiv.appendChild(countDiv);
        
        // 操作按钮
        const actionsDiv = document.createElement('div');
        actionsDiv.className = 'category-actions';
        
        const editBtn = document.createElement('button');
        editBtn.className = 'category-rule-button';
        editBtn.textContent = '查看/编辑规则';
        editBtn.addEventListener('click', event => {
            event.stopPropagation();
            openCategoryRuleEditor(key);
        });
        
        actionsDiv.appendChild(editBtn);

        item.appendChild(checkbox);
        item.appendChild(colorDiv);
        item.appendChild(infoDiv);
        item.appendChild(actionsDiv);
        return item;
}

function renderMoreCategoryGroups(entries, activeCategoryIds) {
    const panel = document.getElementById('moreCategoriesPanel');
    const container = document.getElementById('moreCategoryGroups');
    container.innerHTML = '';
    if (panel.hidden) return;
    const groups = getMoreCategoryGroups({
        readingViews: llmSettingsState?.readingViews || {},
        activeCategoryIds,
        entries,
        searchTerm: document.getElementById('categorySearch').value
    });
    groups.forEach(group => {
        const section = document.createElement('section');
        section.className = 'more-category-group';
        const heading = document.createElement('h4');
        heading.textContent = group.name;
        section.appendChild(heading);
        group.entries.forEach(([key, rule], index) => {
            section.appendChild(createCategoryItem(key, rule, {
                checked: false,
                idSuffix: `-more-${group.viewId}-${index}`
            }));
        });
        container.appendChild(section);
    });
    if (!groups.length) {
        const empty = document.createElement('div');
        empty.className = 'more-categories-empty';
        empty.textContent = '没有匹配的其他分类';
        container.appendChild(empty);
    }
}

function renderCategories() {
    const container = document.getElementById('categoriesContainer');
    const moreButton = document.getElementById('moreCategories');
    container.innerHTML = '';

    const entries = getCategoryEntriesForEngine(analysisMode, {
        includeUnsupported: true
    });
    const currentEntries = getCurrentViewCategoryEntries({
        entries,
        preparedState: preparedDocumentState,
        configuredCategoryIds: [...getConfiguredViewSelection()]
    });
    currentEntries.forEach(([key, rule]) => {
        container.appendChild(createCategoryItem(key, rule, { checked: true }));
    });
    moreButton.hidden = false;
    const activeCategoryIds = currentEntries.map(([categoryId]) => categoryId);
    renderMoreCategoryGroups(entries, activeCategoryIds);
    
    // 更新总匹配数
    updateTotalMatchCount();
    renderHighlightPresentationControls();
    renderConfidenceControl();
}

// 更新总匹配数
function updateTotalMatchCount() {
    const totalCount = Object.values(matchCounts).reduce((sum, count) => sum + count, 0);
    const badge = document.getElementById('totalMatchCount');
    if (totalCount > 0) {
        badge.textContent = `共 ${totalCount} 处匹配`;
        badge.style.display = 'inline-block';
    } else {
        badge.style.display = 'none';
    }
}

// 请求匹配计数
async function requestMatchCounts() {
    try {
        const tab = await queryPanelTargetTab();
        if (!tab?.id || analysisMode !== 'regex') return;
        const rules = await fetchCurrentRegexRules(tab.id);
        const response = await sendTabMessage(tab.id, {
            action: 'getMatchCounts',
            rules
        });
        
        if (response && response.counts) {
            matchCounts = response.counts;
            renderCategories();
        }
    } catch (error) {
        console.log('无法获取匹配计数:', error);
    }
}

async function fetchCurrentRegexRules(tabId) {
    const requestId = ++regexApplySequence;
    const selectedIds = getCategoryEntriesForEngine('regex')
        .map(([categoryId]) => categoryId)
        .filter(categoryId => selectedCategories.has(categoryId));
    const revision = Number(llmSettingsState?.settings?.userDataCategoryRevision) || 0;
    const documentId = manualAnnotationState.tabId === tabId
        ? manualAnnotationState.documentId : '';
    const resolved = await resolveRegexDetailsAtomically({
        categoryIds: selectedIds,
        fetchDetail: categoryId => sendLlmMessage({
            type: 'CATEGORY_GET',
            categoryId
        }),
        refreshState: () => sendLlmMessage({ type: 'LLM_GET_SETTINGS' }),
        validate: async refreshed => {
            const [currentTab] = await chrome.tabs.query({
                active: true,
                currentWindow: true
            });
            const currentRevision =
                Number(refreshed?.settings?.userDataCategoryRevision) || 0;
            const currentDocumentId = manualAnnotationState.tabId === currentTab?.id
                ? manualAnnotationState.documentId : '';
            return analysisMode === 'regex' && shouldApplyRegexSnapshot({
                requestId,
                currentRequestId: regexApplySequence,
                tabId,
                currentTabId: currentTab?.id,
                documentId,
                currentDocumentId,
                revision,
                currentRevision,
                selectedIds,
                currentSelectedIds: [...selectedCategories]
            });
        }
    });
    llmSettingsState = resolved.state;
    return translateUnifiedRegexCategories(resolved.details);
}

async function applyRegexOnTab(tabId, operationId = '') {
    const context = capturePanelContext();
    const categories = await fetchCurrentRegexRules(tabId);
    if (!isCurrentPanelContext(context) || isSidebarOperationStopping(operationId)) return { cancelled: true, notStarted: true };
    return sendTabMessage(tabId, {
        action: 'applyHighlight',
        operationId,
        categories,
        mode: highlightMode,
        analysisModeId: readingViewId
    });
}

function createSupplementalFigureImportTools(dependencies = {}) {
    const shared = dependencies.shared || {};
    const chromeApi = dependencies.chromeApi || globalThis.chrome;
    const cryptoApi = dependencies.cryptoApi || globalThis.crypto;
    const createImageBitmapImpl = dependencies.createImageBitmapImpl ||
        globalThis.createImageBitmap;
    const ImageImpl = dependencies.ImageImpl || globalThis.Image;
    const urlApi = dependencies.urlApi || globalThis.URL;
    const createCanvas = dependencies.createCanvas ||
        (() => globalThis.document?.createElement('canvas'));
    const btoaImpl = dependencies.btoaImpl || globalThis.btoa;
    const now = dependencies.now || (() => new Date().toISOString());
    const sendTabMessageWithRecovery = dependencies.sendTabMessageWithRecovery ||
        shared.sendTabMessageWithRecovery;
    const imageMaxSourceBytes = 20 * 1024 * 1024;
    const imageMaxBytes = Number(shared.SUPPLEMENTAL_TRANSIENT_IMAGE_MAX_BYTES) ||
        1572864;
    const imageMaxEdge = Number(shared.SUPPLEMENTAL_TRANSIENT_IMAGE_MAX_EDGE) || 1600;
    const imageMimeTypes = new Set(['image/png', 'image/jpeg', 'image/webp']);
    const extensionMimeTypes = Object.freeze({
        png: 'image/png',
        jpg: 'image/jpeg',
        jpeg: 'image/jpeg',
        webp: 'image/webp'
    });

    function importError(code, message, fieldId = '') {
        const error = new Error(message || code);
        error.code = code;
        error.fieldId = fieldId;
        return error;
    }

    function syncSourceMode(root, requestedMode) {
        const modes = ['pdf', 'manual'];
        const mode = modes.includes(String(requestedMode)) ? String(requestedMode) : 'pdf';
        const radios = [...(root?.querySelectorAll?.(
            'input[name="supplementalFigureSourceMode"]'
        ) || [])];
        const panes = [...(root?.querySelectorAll?.(
            '[data-supplemental-source-pane]'
        ) || [])];
        radios.forEach(radio => {
            radio.checked = radio.value === mode;
        });
        panes.forEach(pane => {
            pane.hidden = pane.dataset?.supplementalSourcePane !== mode;
        });
        return mode;
    }

    function validateTarget(input = {}) {
        const workspaceId = String(input.workspaceId || '').trim().toLowerCase();
        const workspaceGeneration = Number(input.workspaceGeneration);
        const targetArticleTabId = Number(input.targetArticleTabId);
        const rawCanonicalUrl = String(input.canonicalUrl || '').trim();
        const canonicalUrl = typeof shared.normalizeSupplementalUrl === 'function'
            ? shared.normalizeSupplementalUrl(rawCanonicalUrl)
            : rawCanonicalUrl;
        const rawDocumentHash = String(input.documentHash || '').trim().toLowerCase();
        const documentHashHex = rawDocumentHash.replace(/^sha256:/, '');
        const documentHash = /^[a-f0-9]{64}$/.test(documentHashHex)
            ? `sha256:${documentHashHex}` : '';
        if (!/^workspace:[a-f0-9]{64}$/.test(workspaceId) ||
            !Number.isSafeInteger(workspaceGeneration) || workspaceGeneration < 1 ||
            !Number.isSafeInteger(targetArticleTabId) || targetArticleTabId < 0 ||
            !canonicalUrl ||
            (rawDocumentHash && !documentHash)) {
            throw importError(
                'SUPPLEMENTAL_TARGET_INVALID',
                '当前论文工作区尚未准备完成，请刷新后重试'
            );
        }
        const target = {
            workspaceId,
            workspaceGeneration,
            targetArticleTabId,
            canonicalUrl
        };
        if (documentHash) target.documentHash = documentHash;
        return Object.freeze(target);
    }

    function buildTarget(snapshot, targetArticleTabId, documentHash = '') {
        const workspace = snapshot?.localWorkspace || {};
        return validateTarget({
            workspaceId: workspace.workspaceId,
            workspaceGeneration: workspace.workspaceGeneration,
            targetArticleTabId,
            // The article tab validates against its persisted workspace
            // identity. Prepared-document hashes and the visible page URL may
            // legitimately differ from that identity, so they are fallbacks
            // only when the workspace has not published the field yet.
            canonicalUrl: workspace.canonicalUrl || snapshot?.url,
            documentHash: workspace.contentHash || workspace.revision ||
                workspace.documentHash || snapshot?.documentHash || documentHash
        });
    }

    function validateImageFile(file) {
        const name = String(file?.name || '').trim();
        const mediaType = String(file?.type || '').trim().toLowerCase();
        const size = Number(file?.size);
        const extension = name.match(/\.([a-z0-9]+)$/i)?.[1]?.toLowerCase() || '';
        if (!file || !imageMimeTypes.has(mediaType) ||
            extensionMimeTypes[extension] !== mediaType ||
            !Number.isSafeInteger(size) || size <= 0 || size > imageMaxSourceBytes ||
            typeof file.arrayBuffer !== 'function') {
            throw importError(
                'SUPPLEMENTAL_IMAGE_INVALID',
                '请选择不超过 20 MiB 的 PNG、JPEG 或 WebP 图片，且扩展名与文件类型一致',
                'supplementalFigureImageFile'
            );
        }
        return file;
    }

    function normalizeCaption(value) {
        const caption = String(value || '').trim();
        if (!caption) {
            throw importError(
                'SUPPLEMENTAL_CAPTION_EMPTY', '请粘贴完整图注',
                'supplementalFigureImageCaption'
            );
        }
        if (caption.length > 8000) {
            throw importError(
                'SUPPLEMENTAL_CAPTION_TOO_LONG', '图注不能超过 8000 个字符',
                'supplementalFigureImageCaption'
            );
        }
        return caption;
    }

    function normalizeOptionalCaption(value) {
        const caption = String(value || '').trim();
        if (caption.length > 8000) {
            throw importError(
                'SUPPLEMENTAL_CAPTION_TOO_LONG', '图注不能超过 8000 个字符',
                'supplementalFigureImageCaption'
            );
        }
        return caption;
    }

    async function sha256Fingerprint(value) {
        if (!cryptoApi?.subtle?.digest) {
            throw importError('SUPPLEMENTAL_CRYPTO_UNAVAILABLE', '当前环境无法计算文件指纹');
        }
        const bytes = typeof value === 'string'
            ? new TextEncoder().encode(value)
            : value instanceof ArrayBuffer
                ? new Uint8Array(value)
                : new Uint8Array(value?.buffer || value || []);
        const digest = new Uint8Array(await cryptoApi.subtle.digest('SHA-256', bytes));
        return `sha256:${[...digest]
            .map(byte => byte.toString(16).padStart(2, '0')).join('')}`;
    }

    async function decodeImageFile(file) {
        let bitmapError = null;
        if (typeof createImageBitmapImpl === 'function') {
            try {
                const bitmap = await createImageBitmapImpl(file);
                return {
                    source: bitmap,
                    width: Number(bitmap?.width),
                    height: Number(bitmap?.height),
                    dispose: () => bitmap?.close?.()
                };
            } catch (error) {
                bitmapError = error;
            }
        }
        if (typeof ImageImpl === 'function' && urlApi?.createObjectURL) {
            const objectUrl = urlApi.createObjectURL(file);
            try {
                const image = new ImageImpl();
                await new Promise((resolve, reject) => {
                    image.onload = resolve;
                    image.onerror = () => reject(bitmapError ||
                        importError('SUPPLEMENTAL_IMAGE_DECODE', '图片无法解码'));
                    image.src = objectUrl;
                });
                return {
                    source: image,
                    width: Number(image.naturalWidth || image.width),
                    height: Number(image.naturalHeight || image.height),
                    dispose: () => urlApi.revokeObjectURL?.(objectUrl)
                };
            } catch (error) {
                urlApi.revokeObjectURL?.(objectUrl);
                throw error;
            }
        }
        if (bitmapError) throw bitmapError;
        throw importError('SUPPLEMENTAL_IMAGE_DECODE', '图片无法解码');
    }

    function canvasToBlob(canvas, mediaType, quality) {
        return new Promise((resolve, reject) => {
            try {
                canvas.toBlob(blob => {
                    if (blob) resolve(blob);
                    else reject(importError('SUPPLEMENTAL_IMAGE_ENCODE', '图片压缩失败'));
                }, mediaType, quality);
            } catch (error) {
                reject(error);
            }
        });
    }

    async function blobToDataUrl(blob, mediaType) {
        const bytes = new Uint8Array(await blob.arrayBuffer());
        let binary = '';
        for (let index = 0; index < bytes.length; index += 32768) {
            binary += String.fromCharCode(...bytes.subarray(index, index + 32768));
        }
        return `data:${mediaType};base64,${btoaImpl(binary)}`;
    }

    async function prepareTransientImage(file) {
        validateImageFile(file);
        const sourceBytes = await file.arrayBuffer();
        const sourceFingerprint = await sha256Fingerprint(sourceBytes);
        let decoded;
        try {
            decoded = await decodeImageFile(file);
        } catch (_) {
            throw importError(
                'SUPPLEMENTAL_IMAGE_DECODE', '无法解码这张图片，请重新导出后再试',
                'supplementalFigureImageFile'
            );
        }
        const sourceWidth = Number(decoded?.width);
        const sourceHeight = Number(decoded?.height);
        if (!Number.isFinite(sourceWidth) || !Number.isFinite(sourceHeight) ||
            sourceWidth <= 0 || sourceHeight <= 0) {
            decoded?.dispose?.();
            throw importError(
                'SUPPLEMENTAL_IMAGE_DECODE', '图片宽高无效，请重新选择',
                'supplementalFigureImageFile'
            );
        }
        const canvas = createCanvas();
        const context = canvas?.getContext?.('2d', { alpha: true });
        if (!canvas || !context || typeof canvas.toBlob !== 'function') {
            decoded?.dispose?.();
            throw importError('SUPPLEMENTAL_IMAGE_ENCODE', '当前环境无法处理图片');
        }
        let longestEdge = Math.min(imageMaxEdge, Math.max(sourceWidth, sourceHeight));
        let encoded = null;
        let outputWidth = 0;
        let outputHeight = 0;
        const qualities = file.type === 'image/png'
            ? [undefined]
            : [0.92, 0.84, 0.76, 0.68, 0.58];
        try {
            while (longestEdge >= 1 && !encoded) {
                const scale = Math.min(1, longestEdge / Math.max(sourceWidth, sourceHeight));
                outputWidth = Math.max(1, Math.round(sourceWidth * scale));
                outputHeight = Math.max(1, Math.round(sourceHeight * scale));
                canvas.width = outputWidth;
                canvas.height = outputHeight;
                context.drawImage(decoded.source, 0, 0, outputWidth, outputHeight);
                for (const quality of qualities) {
                    const candidate = await canvasToBlob(canvas, file.type, quality);
                    if (candidate.size > 0 && candidate.size <= imageMaxBytes) {
                        encoded = candidate;
                        break;
                    }
                }
                if (!encoded) {
                    if (longestEdge === 1) break;
                    longestEdge = Math.max(1, Math.floor(longestEdge * 0.82));
                }
            }
        } finally {
            decoded.dispose?.();
        }
        if (!encoded) {
            throw importError(
                'SUPPLEMENTAL_TRANSIENT_IMAGE_TOO_LARGE',
                '图片压缩后仍超过 1.5 MiB，请裁剪后重试',
                'supplementalFigureImageFile'
            );
        }
        const mediaType = imageMimeTypes.has(String(encoded.type).toLowerCase())
            ? String(encoded.type).toLowerCase() : file.type;
        const transient = {
            mediaType,
            dataUrl: await blobToDataUrl(encoded, mediaType),
            width: outputWidth,
            height: outputHeight,
            sourceFingerprint
        };
        return typeof shared.normalizeSupplementalTransientImage === 'function'
            ? shared.normalizeSupplementalTransientImage(transient, sourceFingerprint)
            : transient;
    }

    function sourceMaterialId(mode, sourceFingerprint) {
        return `manual-${mode}-${String(sourceFingerprint || '')
            .replace(/^sha256:/, '').slice(0, 16)}`;
    }

    function normalizeManualMetadata(input = {}) {
        const figureKind = String(input.figureKind || '').toLowerCase() === 'main'
            ? 'main' : 'supplemental';
        const figureLabel = typeof shared.canonicalManualFigureLabel === 'function'
            ? shared.canonicalManualFigureLabel(input.figureLabel, figureKind, '')
            : String(input.figureLabel || '').trim();
        if (figureKind === 'main' && !figureLabel) {
            throw importError(
                'MANUAL_FIGURE_LABEL',
                '主图需要填写 Figure 编号，例如 Figure 3',
                'supplementalFigureLabel'
            );
        }
        const rawPage = String(input.sourcePage ?? '').trim();
        const sourcePage = rawPage ? Number(rawPage) : 0;
        if (!Number.isSafeInteger(sourcePage) || sourcePage < 0 || sourcePage > 100000) {
            throw importError(
                'MANUAL_FIGURE_PAGE',
                'PDF 页码必须是正整数',
                'supplementalFigureSourcePage'
            );
        }
        return { figureKind, figureLabel, sourcePage };
    }

    function createImageImport(file, transientImage, caption = '', metadata = {}) {
        validateImageFile(file);
        const manualMetadata = normalizeManualMetadata(metadata);
        const sourceFingerprint = String(transientImage?.sourceFingerprint || '');
        const draftInput = {
            sourceMode: 'image',
            sourceMaterialId: sourceMaterialId('image', sourceFingerprint),
            sourceFileName: file.name,
            sourceMimeType: file.type,
            sourceFileSize: file.size,
            sourceImportedAt: now(),
            sourceFingerprint,
            caption: normalizeOptionalCaption(caption),
            ...manualMetadata
        };
        const draft = shared.createSupplementalFigureImportDraft(draftInput);
        return { draft, transientImage };
    }

    async function createCaptionImport(value, metadata = {}) {
        const caption = normalizeCaption(value);
        const manualMetadata = normalizeManualMetadata(metadata);
        const sourceFingerprint = await sha256Fingerprint(caption);
        const draft = shared.createSupplementalFigureImportDraft({
            sourceMode: 'caption',
            sourceMaterialId: sourceMaterialId('caption', sourceFingerprint),
            sourceImportedAt: now(),
            sourceFingerprint,
            caption,
            ...manualMetadata
        });
        return { draft };
    }

    function validateManualInput(file, caption, { hasExistingImage = false } = {}) {
        const normalizedCaption = normalizeOptionalCaption(caption);
        if (file) validateImageFile(file);
        if (!file && !normalizedCaption && !hasExistingImage) {
            throw importError(
                'SUPPLEMENTAL_MANUAL_INPUT_REQUIRED',
                '请上传或粘贴一张图片，或者填写图注',
                'supplementalFigureImageFile'
            );
        }
        return { file: file || null, caption: normalizedCaption };
    }

    function clipboardImageFile(clipboardData, FileImpl = globalThis.File) {
        const items = [...(clipboardData?.items || [])];
        const item = items.find(candidate =>
            candidate?.kind === 'file' && /^image\/(?:png|jpeg|webp)$/i.test(
                String(candidate?.type || '')
            )
        );
        const blob = item?.getAsFile?.();
        if (!blob) return null;
        const mediaType = String(blob.type || item.type || '').toLowerCase();
        const extension = mediaType === 'image/jpeg' ? 'jpg'
            : mediaType === 'image/webp' ? 'webp' : 'png';
        const currentName = String(blob.name || '');
        if (/\.(?:png|jpe?g|webp)$/i.test(currentName)) return blob;
        if (typeof FileImpl === 'function') {
            return new FileImpl([blob], `clipboard-${Date.now()}.${extension}`, {
                type: mediaType,
                lastModified: Date.now()
            });
        }
        try {
            Object.defineProperty(blob, 'name', {
                configurable: true,
                value: `clipboard-${Date.now()}.${extension}`
            });
        } catch (_) {}
        return blob;
    }

    function isClosedTabError(error) {
        const code = String(error?.code || '').trim().toUpperCase();
        if ([
            'TAB_NOT_FOUND',
            'NO_TAB',
            'INVALID_TAB_ID',
            'TAB_CLOSED',
            'TARGET_TAB_CLOSED'
        ].includes(code)) return true;
        return /No tab with id|Invalid tab ID|tab (?:was )?closed|tab not found/i
            .test(String(error?.message || error || ''));
    }

    function responseError(response, fallbackCode, fallbackMessage) {
        const structured = response?.error && typeof response.error === 'object'
            ? response.error : null;
        return importError(
            response?.code || structured?.code || fallbackCode,
            structured?.message || response?.error || fallbackMessage
        );
    }

    async function deliverImport(targetInput, request = {}) {
        const target = validateTarget(targetInput);
        const draft = request?.draft;
        if (!draft || typeof draft !== 'object' || Array.isArray(draft)) {
            throw importError('SUPPLEMENTAL_DRAFT_INVALID', '补充 Figure 草稿无效');
        }
        const message = {
            action: 'importSupplementalFigureDraft',
            target,
            draft
        };
        if (request.transientImage) {
            const transientImage = shared.normalizeSupplementalTransientImage(
                request.transientImage,
                request.transientImage.sourceFingerprint
            );
            message.transientImage = {
                mediaType: transientImage.mediaType,
                dataUrl: transientImage.dataUrl,
                width: transientImage.width,
                height: transientImage.height,
                sourceFingerprint: transientImage.sourceFingerprint
            };
        }
        try {
            const response = await sendTabMessageWithRecovery(
                chromeApi, target.targetArticleTabId, message
            );
            if (response?.success === false) {
                throw responseError(
                    response,
                    'SUPPLEMENTAL_IMPORT_FAILED',
                    '无法导入补充 Figure 草稿'
                );
            }
            return response;
        } catch (error) {
            if (!isClosedTabError(error)) throw error;
            const fallback = await chromeApi.runtime.sendMessage({
                type: 'ARTICLE_WORKSPACE_SAVE_SUPPLEMENTAL_DRAFT',
                target,
                draft,
                ...(message.transientImage
                    ? { transientImage: message.transientImage }
                    : {})
            });
            if (fallback?.success === false) {
                throw responseError(
                    fallback,
                    'SUPPLEMENTAL_DRAFT_SAVE_FAILED',
                    '无法保存补充 Figure 草稿'
                );
            }
            return { ...(fallback?.data || fallback || {}), savedAsDraft: true };
        }
    }

    async function deliverUpdate(targetInput, request = {}) {
        const target = validateTarget(targetInput);
        const figureId = String(request.figureId || '').trim();
        if (!figureId) {
            throw importError('SUPPLEMENTAL_FIGURE_NOT_FOUND', '没有找到要编辑的补充图');
        }
        const message = {
            action: 'updateSupplementalFigureDraft',
            target,
            figureId,
            caption: normalizeOptionalCaption(request.caption),
            figureLabel: String(request.figureLabel || '').trim(),
            sourcePage: String(request.sourcePage ?? '').trim()
        };
        if (request.transientImage) {
            const transientImage = shared.normalizeSupplementalTransientImage(
                request.transientImage,
                request.transientImage.sourceFingerprint
            );
            Object.assign(message, {
                transientImage: {
                    mediaType: transientImage.mediaType,
                    dataUrl: transientImage.dataUrl,
                    width: transientImage.width,
                    height: transientImage.height,
                    sourceFingerprint: transientImage.sourceFingerprint
                },
                sourceFingerprint: transientImage.sourceFingerprint,
                sourceFileName: String(request.sourceFileName || '').slice(0, 500),
                sourceMimeType: String(request.sourceMimeType || '').slice(0, 100),
                sourceFileSize: Math.max(0, Number(request.sourceFileSize) || 0)
            });
        }
        const response = await sendTabMessageWithRecovery(
            chromeApi, target.targetArticleTabId, message
        );
        if (response?.success === false) {
            throw responseError(response, 'SUPPLEMENTAL_UPDATE_FAILED', '补充图修改失败');
        }
        return response;
    }

    async function deliverDelete(targetInput, figureId) {
        const target = validateTarget(targetInput);
        const normalizedFigureId = String(figureId || '').trim();
        if (!normalizedFigureId) {
            throw importError('SUPPLEMENTAL_FIGURE_NOT_FOUND', '没有找到要删除的补充图');
        }
        const response = await sendTabMessageWithRecovery(
            chromeApi,
            target.targetArticleTabId,
            { action: 'deleteSupplementalFigure', target, figureId: normalizedFigureId }
        );
        if (response?.success === false) {
            throw responseError(response, 'SUPPLEMENTAL_DELETE_FAILED', '补充图删除失败');
        }
        return response;
    }

    return {
        syncSourceMode,
        validateTarget,
        buildTarget,
        validateImageFile,
        normalizeCaption,
        normalizeOptionalCaption,
        normalizeManualMetadata,
        validateManualInput,
        clipboardImageFile,
        prepareTransientImage,
        createImageImport,
        createCaptionImport,
        deliverImport,
        deliverUpdate,
        deliverDelete
    };
}

const supplementalFigureImportTools = createSupplementalFigureImportTools({
    shared: SciLLM,
    chromeApi: chrome
});

function supplementalPdfImportedPanelCount(snapshot, reportedCount = 0) {
    const figures = Array.isArray(snapshot?.figures?.figures)
        ? snapshot.figures.figures : [];
    const normalizedPanelId = value => String(
        value?.panelId ?? value?.panel ?? value ?? ''
    ).normalize('NFKC').trim().toUpperCase();
    const total = figures.filter(figure => figure?.isSupplemental === true)
        .reduce((sum, figure) => {
            const panelIds = new Set();
            const add = value => {
                const panelId = normalizedPanelId(value);
                if (panelId) panelIds.add(panelId);
            };
            (Array.isArray(figure?.panelHints) ? figure.panelHints : []).forEach(add);
            [figure?.standard, figure?.deep].forEach(analysis => {
                (Array.isArray(analysis?.panels) ? analysis.panels : []).forEach(add);
            });
            Object.keys(figure?.panelAnalyses || {}).forEach(add);
            return sum + panelIds.size;
        }, 0);
    return Math.max(total, Math.max(0, Number(reportedCount) || 0));
}

async function inspectSupplementalMaterialDocx(material, target, options = {}) {
    target = supplementalFigureImportTools.validateTarget(target);
    const panelContext = capturePanelContext();
    const read = options.readSnapshot || (() => refreshArticleWorkspace({ panelContext, forceRefresh: true, throwOnError: true }));
    const guard = () => {
        options.signal?.throwIfAborted(); options.assertCurrent?.();
        if (!isCurrentPanelContext(panelContext)) throw Object.assign(new Error('DOCX_PARENT_STALE'), { code: 'DOCX_PARENT_STALE' });
        const actual = supplementalFigureImportTools.buildTarget(currentWorkspaceSnapshot, target.targetArticleTabId);
        if (['workspaceId', 'workspaceGeneration', 'canonicalUrl', 'documentHash', 'targetArticleTabId'].some(key => actual[key] !== target[key]))
            throw Object.assign(new Error('DOCX_PARENT_STALE'), { code: 'DOCX_PARENT_STALE' });
    };
    const check = async () => {
        guard(); const snapshot = await read(); guard();
        const actual = supplementalFigureImportTools.buildTarget(snapshot, target.targetArticleTabId);
        if (['workspaceId', 'workspaceGeneration', 'canonicalUrl', 'documentHash', 'targetArticleTabId'].some(key => actual[key] !== target[key]))
            throw Object.assign(new Error('DOCX_PARENT_STALE'), { code: 'DOCX_PARENT_STALE' });
        SciLLM.assertDocxMaterial(material, snapshot?.figures?.supplemental?.materials);
    };
    await check();
    const fetched = await SciLLM.fetchSupplementalDocxSource(material, options); await check();
    const pkg = await SciLLM.unpackSupplementalDocxParts(fetched.bytes); await check();
    const actual = SciLLM.inspectSupplementalDocxAbsence(pkg);
    if (!actual.checkedNoFigures) {
        const figureImport=await SciLLM.prepareSupplementalDocxFigureAsset(fetched.bytes,material,target,{
            imageTools:supplementalFigureImportTools,check:guard});await check();
        const receipt=await SciLLM.sendTabMessageWithRecovery(chrome,target.targetArticleTabId,{
            action:'persistSupplementalDocxNoFigureInspection',target,material,figureImport});await check();
        if(receipt?.success!==true || receipt.directoryPersisted!==true || receipt.stage!=='complete' ||
            receipt.relativePath!==SciLLM.supplementalFigureAssetPath(material.materialId) ||
            receipt.importedCount!==figureImport.asset.figures.length ||
            JSON.stringify(receipt.sourceInspection)!==JSON.stringify(figureImport.asset.sourceInspection))
            throw Object.assign(new Error('DOCX Figure 尚未完成保存'),{code:'DOCX_INSPECTION_NOT_DURABLE'});
        await read();guard();return receipt;
    }
    const inspection = { ...actual, sourceFormat: 'docx', sourceMaterialId: material.materialId, sourceUrl: material.url,
        finalUrl: fetched.finalUrl, containerSha256: pkg.containerSha256, byteLength: fetched.byteLength,
        inspectedAt: new Date().toISOString(), complete: true };
    await check();
    const receipt = await SciLLM.sendTabMessageWithRecovery(chrome, target.targetArticleTabId, {
        action: 'persistSupplementalDocxNoFigureInspection', target, material, inspection
    }); await check();
    if (receipt?.success !== true || receipt.directoryPersisted !== true ||
        receipt.relativePath !== SciLLM.supplementalFigureAssetPath(material.materialId) ||
        JSON.stringify(receipt.sourceInspection) !== JSON.stringify({ ...inspection, target: { ...target } }))
        throw Object.assign(new Error(receipt?.error || 'DOCX 检查结果尚未保存'), { code: receipt?.code || 'DOCX_INSPECTION_NOT_DURABLE' });
    await read(); guard(); showStatus('已检查附件，未发现嵌入 Figure。', 'success');
    return receipt;
}

async function openSupplementalMaterialPdf(material, target, selectedFile = null, options = {}) {
    if (!selectedFile && (/^(?:docx?|word)$/i.test(String(material?.sourceFormat || '')) ||
        /\.docx?$/i.test(String(material?.url || '').split(/[?#]/u)[0]))) return inspectSupplementalMaterialDocx(material, target, options);
    target = supplementalFigureImportTools.validateTarget(target);
    const signal = options.signal;
    const cancelled = () => Object.assign(new Error('补图来源准备已取消'), { name: 'AbortError', code: 'CANCELLED' });
    const assertCurrent = () => {
        if (signal?.aborted) throw cancelled();
        if (typeof options.assertCurrent === 'function') {
            try { if (options.assertCurrent() === false) throw cancelled(); }
            catch (_) { throw cancelled(); }
        }
    };
    const waitForPoll = () => new Promise((resolve, reject) => {
        let timer;
        const abort = () => { clearTimeout(timer); signal?.removeEventListener('abort', abort); reject(cancelled()); };
        if (signal?.aborted) return abort();
        signal?.addEventListener('abort', abort, { once: true });
        timer = setTimeout(() => { signal?.removeEventListener('abort', abort); resolve(); }, 750);
    });
    let file = selectedFile, importToken = '', statusKey = '', tab = null, outcome = null, failure = null;
    const automaticSource = !(selectedFile instanceof Blob) && Boolean(material?.url);
    try {
        assertCurrent();
        if (automaticSource) {
            let fetched;
            try {
                fetched = await SciLLM.fetchSupplementalPdfSource(material, {
                    maximumBytes: SciLLM.PDF_MINERU_MAX_FILE_BYTES, signal
                });
            } catch (error) {
                assertCurrent();
                if (error?.code !== 'SUPPLEMENTAL_DATA_SOURCE_REQUIRED' || !error.wrapperInspection) throw error;
                const projected = SciLLM.projectSupplementalJciWrapperMaterial(material, error.wrapperInspection, target);
                const receipt = await SciLLM.sendTabMessageWithRecovery(chrome, target.targetArticleTabId, {
                    action: 'persistSupplementalDataWrapper', target, material, wrapperInspection: error.wrapperInspection
                });
                assertCurrent();
                if (receipt?.success !== true || receipt.directoryPersisted !== true ||
                    receipt.relativePath !== SciLLM.supplementalFigureAssetPath(material.materialId) ||
                    JSON.stringify(receipt.sourceWrapper) !== JSON.stringify(projected.sourceWrapper))
                    throw Object.assign(new Error(receipt?.error || '附件分类尚未保存'), { code: receipt?.code || 'SUPPLEMENTAL_WRAPPER_NOT_DURABLE' });
                await refreshArticleWorkspace(); assertCurrent();
                showStatus('已确认该附件为数据表格，已保留其来源。', 'success');
                return receipt;
            }
            assertCurrent();
            file = fetched.blob;
            target = supplementalFigureImportTools.validateTarget(target);
        }
        if (!(file instanceof Blob)) {
            file = await new Promise(resolve => {
                const input = document.createElement('input');
                input.type = 'file'; input.accept = 'application/pdf,.pdf';
                const abort = () => resolve(null);
                input.addEventListener('change', () => {
                    signal?.removeEventListener('abort', abort);
                    resolve(input.files?.[0] || null);
                }, { once: true });
                signal?.addEventListener('abort', abort, { once: true });
                if (signal?.aborted) abort(); else input.click();
            });
            assertCurrent();
        }
        if (!(file instanceof Blob)) return { cancelled: true, notStarted: true };
        if (file.size > SciLLM.PDF_MINERU_MAX_FILE_BYTES) {
            throw Object.assign(new Error('补充 PDF 超过文件大小限制'), { code: 'PDF_LOCAL_FILE_TOO_LARGE' });
        }
        const signature = await file.slice(0, 5).arrayBuffer();
        assertCurrent();
        if (!SciLLM.hasPdfByteSignature(signature)) {
            throw Object.assign(new Error('所选文件不是有效的 PDF'), { code: 'SUPPLEMENTAL_PDF_INVALID' });
        }
        importToken = await SciLLM.saveSupplementalPdfImportSession(file, {
            maximumBytes: SciLLM.PDF_MINERU_MAX_FILE_BYTES
        });
        assertCurrent();
        const readerUrl = SciLLM.createSupplementalPdfReaderUrl?.(
            chrome.runtime.getURL.bind(chrome.runtime), {
                sourceUrl: material?.url, title: material?.title, materialId: material?.materialId,
                parentWorkspaceId: target.workspaceId, parentWorkspaceGeneration: target.workspaceGeneration,
                parentCanonicalUrl: target.canonicalUrl, parentDocumentHash: target.documentHash,
                parentTabId: target.targetArticleTabId
            }
        );
        if (!readerUrl) throw Object.assign(new Error('补充材料 PDF 链接无效'), { code: 'SUPPLEMENTAL_PDF_SOURCE_INVALID' });
        const headlessUrl = new URL(readerUrl);
        headlessUrl.searchParams.set('supplementalImportToken', importToken);
        headlessUrl.searchParams.set('headlessImport', '1');
        headlessUrl.searchParams.set('localSourceImport', '1');
        statusKey = SciLLM.supplementalPdfImportStatusKey(importToken);
        await chrome.storage.session.set({ [statusKey]: { stage: 'queued', updatedAt: Date.now() } });
        assertCurrent();
        tab = await chrome.tabs.create({ url: headlessUrl.href, active: false });
        assertCurrent();
        await SciLLM.markTabActivated?.(chrome.storage.session, {
            ...tab, url: headlessUrl.href, pendingUrl: headlessUrl.href,
            title: material?.title || '补充材料 PDF'
        });
        assertCurrent();
        showStatus('补充 PDF 正在后台进行本地来源提取，可继续阅读正文', 'success');
        const deadline = Date.now() + 20 * 60 * 1000;
        let result = null;
        while (Date.now() < deadline) {
            assertCurrent();
            const stored = await chrome.storage.session.get(statusKey);
            assertCurrent();
            const status = stored?.[statusKey];
            if (status?.stage === 'complete') { result = status; break; }
            if (status?.stage === 'error') throw Object.assign(new Error(`[${status.code || 'SUPPLEMENTAL_PDF_IMPORT_FAILED'}] ${status.message || '补充 PDF 导入失败'}`), {
                code: status.code || 'SUPPLEMENTAL_PDF_IMPORT_FAILED'
            });
            await waitForPoll();
            assertCurrent();
        }
        if (!result) throw Object.assign(new Error('补充 PDF 导入超时'), { code: 'SUPPLEMENTAL_PDF_IMPORT_TIMEOUT' });
        const snapshot = await refreshArticleWorkspace();
        assertCurrent();
        const coverage = snapshot?.figures?.supplemental?.coverage || null;
        const missing = Array.isArray(coverage?.missingFigureLabels) ? coverage.missingFigureLabels : [];
        const figureCount = Math.max(0, Number(result.figureCount) || 0);
        const panelCount = supplementalPdfImportedPanelCount(snapshot, result.panelCount);
        const needsAttention = figureCount === 0 || missing.length > 0;
        const message = figureCount === 0 ? '解析已完成，但未识别到可导入的 Figure；请重试或手动补充图片/图注'
            : missing.length ? `已导入 ${figureCount} 张 Figure、识别 ${panelCount} 个 Panel；尚缺 ${missing.join('、')}，请手动补充或重试`
                : `已导入 ${figureCount} 张 Figure、识别 ${panelCount} 个 Panel`;
        outcome = { ...result, coverage, needsAttention, message };
    } catch (error) {
        failure = error;
    } finally {
        // Cleanup is unconditional and scoped to this call's token, status and reader.
        // A stop or page change must not prevent closing the already owned reader.
        if (Number.isInteger(tab?.id)) {
            await chrome.tabs.remove(tab.id).catch(() => undefined);
            try { assertCurrent(); } catch (error) { failure = error; }
        }
        if (importToken) {
            await SciLLM.discardSupplementalPdfImportSession(importToken).catch(() => false);
            try { assertCurrent(); } catch (error) { failure = error; }
        }
        if (statusKey) {
            await chrome.storage.session.remove(statusKey).catch(() => undefined);
            try { assertCurrent(); } catch (error) { failure = error; }
        }
    }
    try { assertCurrent(); } catch (error) { failure = error; }
    if (failure) {
        if (failure.name === 'AbortError' || failure.code === 'CANCELLED' || signal?.aborted) {
            return { cancelled: true, notStarted: true };
        }
        throw failure;
    }
    return outcome;
}

let supplementalFigureImportTarget = null;
let supplementalFigureImportSession = {
    action: 'create',
    figure: null,
    clipboardFile: null
};

function supplementalFigureImportMode(form = document.getElementById(
    'supplementalFigureImportForm'
)) {
    return form?.querySelector?.(
        'input[name="supplementalFigureSourceMode"]:checked'
    )?.value || 'pdf';
}

function setSupplementalFigureImportStatus(message = '', { error = false } = {}) {
    const status = document.getElementById('supplementalFigureImportStatus');
    if (!status) return;
    status.textContent = String(message || '');
    status.classList.toggle('is-error', error);
}

function focusSupplementalFigureImportError(error) {
    const field = error?.fieldId ? document.getElementById(error.fieldId) : null;
    if (field) {
        field.setAttribute('aria-invalid', 'true');
        field.focus();
    } else {
        document.getElementById('supplementalFigureImportStatus')?.focus?.();
    }
}

function updateSupplementalFigureSelectedImage(file = null, { existing = false } = {}) {
    const label = document.getElementById('supplementalFigureSelectedImage');
    const pasteTarget = document.getElementById('supplementalFigurePasteTarget');
    if (!label) return;
    const hasImage = Boolean(file || existing);
    label.textContent = file
        ? `已选择：${file.name}（${Math.max(1, Math.ceil(file.size / 1024))} KiB）`
        : existing ? '已保留当前图片；选择或粘贴新图片可替换。'
            : '未选择图片；也可以只填写图注。';
    label.classList.toggle('has-image', hasImage);
    pasteTarget?.classList.toggle('is-ready', hasImage);
}

function setSupplementalFigureClipboardFile(file) {
    supplementalFigureImportSession.clipboardFile = file || null;
    const input = document.getElementById('supplementalFigureImageFile');
    if (input && file && typeof DataTransfer === 'function') {
        try {
            const transfer = new DataTransfer();
            transfer.items.add(file);
            input.files = transfer.files;
        } catch (_) {}
    }
    updateSupplementalFigureSelectedImage(file, {
        existing: supplementalFigureImportSession.figure?.hasImage === true
    });
}

function resetSupplementalFigureImportForm({ editingFigure = null } = {}) {
    const form = document.getElementById('supplementalFigureImportForm');
    form?.reset?.();
    const fileInput = document.getElementById('supplementalFigureImageFile');
    const pdfFileInput = document.getElementById('supplementalFigurePdfFile');
    const captionInput = document.getElementById('supplementalFigureImageCaption');
    const kindInput = document.getElementById('supplementalFigureKind');
    const labelInput = document.getElementById('supplementalFigureLabel');
    const pageInput = document.getElementById('supplementalFigureSourcePage');
    if (fileInput) fileInput.value = '';
    if (pdfFileInput) pdfFileInput.value = '';
    if (captionInput) captionInput.value = editingFigure?.caption || '';
    if (kindInput) {
        kindInput.value = editingFigure?.isSupplemental === false ? 'main' : 'supplemental';
        kindInput.disabled = Boolean(editingFigure);
    }
    if (labelInput) {
        labelInput.value = editingFigure?.figureLabel || '';
        labelInput.placeholder = kindInput?.value === 'main'
            ? '例如 Figure 3' : '例如 Figure S2（留空则自动编号）';
    }
    if (pageInput) pageInput.value = Number(editingFigure?.sourcePage) > 0
        ? String(Math.floor(Number(editingFigure.sourcePage))) : '';
    form?.querySelectorAll('[aria-invalid="true"]').forEach(field =>
        field.removeAttribute('aria-invalid')
    );
    supplementalFigureImportSession = {
        action: editingFigure ? 'edit' : 'create',
        figure: editingFigure || null,
        clipboardFile: null
    };
    document.querySelectorAll('[data-supplemental-create-only]').forEach(element => {
        element.hidden = Boolean(editingFigure);
    });
    const title = document.getElementById('supplementalFigureImportTitle');
    const description = document.getElementById('supplementalFigureImportDescription');
    const submit = document.getElementById('submitSupplementalFigureImport');
    if (title) title.textContent = editingFigure
        ? `编辑 ${editingFigure.figureLabel || '手动 Figure'}` : '手动补全 Figure';
    if (description) description.textContent = editingFigure
        ? '可修改图注，或上传、粘贴新图片替换当前图片。保存后需要重新解图。'
        : '可上传主图或补充图原图、图注，并标注它在原 PDF 中的页码。';
    if (submit) submit.textContent = editingFigure ? '保存修改' : '继续';
    supplementalFigureImportTools.syncSourceMode(
        form,
        'manual'
    );
    updateSupplementalFigureSelectedImage(null, {
        existing: editingFigure?.hasImage === true
    });
    setSupplementalFigureImportStatus('');
}

function openSupplementalFigureImportDialog() {
    const dialog = document.getElementById('supplementalFigureImportDialog');
    try {
        supplementalFigureImportTarget = supplementalFigureImportTools.buildTarget(
            currentWorkspaceSnapshot,
            activePanelTabContext.tabId,
            preparedDocumentState?.documentHash || manualAnnotationState.documentHash
        );
    } catch (error) {
        showStatus(error.message, 'error');
        return;
    }
    resetSupplementalFigureImportForm();
    dialog?.showModal();
}

function openSupplementalFigureEditDialog(figure) {
    const dialog = document.getElementById('supplementalFigureImportDialog');
    try {
        supplementalFigureImportTarget = supplementalFigureImportTools.buildTarget(
            currentWorkspaceSnapshot,
            activePanelTabContext.tabId,
            preparedDocumentState?.documentHash || manualAnnotationState.documentHash
        );
    } catch (error) {
        showStatus(error.message, 'error');
        return;
    }
    resetSupplementalFigureImportForm({ editingFigure: figure });
    dialog?.showModal();
    document.getElementById('supplementalFigureImageCaption')?.focus?.();
}

async function deleteSupplementalFigureFromWorkspace(figure) {
    const label = String(figure?.figureLabel || '这张补充图');
    if (!globalThis.confirm?.(`确定删除 ${label}？\n\n这会同时移除其解图结果和串解关系。`)) {
        return;
    }
    const target = supplementalFigureImportTools.buildTarget(
        currentWorkspaceSnapshot,
        activePanelTabContext.tabId,
        preparedDocumentState?.documentHash || manualAnnotationState.documentHash
    );
    await supplementalFigureImportTools.deliverDelete(target, figure?.figureId);
    showStatus(`${label} 已删除`, 'success');
    await refreshArticleWorkspace();
}

function closeSupplementalFigureImportDialog() {
    document.getElementById('supplementalFigureImportDialog')?.close();
}

async function submitSupplementalFigureImport(event) {
    event.preventDefault();
    const form = event.currentTarget;
    const submit = document.getElementById('submitSupplementalFigureImport');
    const mode = supplementalFigureImportMode(form);
    form.querySelectorAll('[aria-invalid="true"]').forEach(field =>
        field.removeAttribute('aria-invalid')
    );
    if (submit?.disabled) return;
    if (submit) submit.disabled = true;
    setSupplementalFigureImportStatus('正在保存并识别 Panel…');
    try {
        const target = supplementalFigureImportTools.validateTarget(
            supplementalFigureImportTarget
        );
        let importResult = null;
        if (mode === 'pdf' && supplementalFigureImportSession.action === 'create') {
            const pdfFile = document.getElementById('supplementalFigurePdfFile')
                ?.files?.[0] || null;
            if (!pdfFile) {
                const error = new Error('请先选择要解析的补充 PDF');
                error.code = 'SUPPLEMENTAL_PDF_INVALID';
                error.fieldId = 'supplementalFigurePdfFile';
                throw error;
            }
            importResult = await openSupplementalMaterialPdf({
                materialId: `manual-supplement-${Date.now()}`,
                title: '本地补充材料 PDF',
                url: ''
            }, target, pdfFile);
            if (importResult?.cancelled) return;
            setSupplementalFigureImportStatus(importResult.message, {
                error: importResult.needsAttention === true
            });
            closeSupplementalFigureImportDialog();
            showStatus(
                importResult.message,
                importResult.needsAttention === true ? 'error' : 'success'
            );
            return;
        } else {
            const fileInput = document.getElementById('supplementalFigureImageFile');
            const file = supplementalFigureImportSession.clipboardFile ||
                fileInput?.files?.[0] || null;
            const captionValue = document.getElementById(
                'supplementalFigureImageCaption'
            )?.value;
            const manual = supplementalFigureImportTools.validateManualInput(
                file,
                captionValue,
                { hasExistingImage: supplementalFigureImportSession.figure?.hasImage === true }
            );
            const metadata = supplementalFigureImportTools.normalizeManualMetadata({
                figureKind: document.getElementById('supplementalFigureKind')?.value,
                figureLabel: document.getElementById('supplementalFigureLabel')?.value,
                sourcePage: document.getElementById('supplementalFigureSourcePage')?.value
            });
            let transientImage = null;
            if (manual.file) {
                setSupplementalFigureImportStatus('正在本地校验、缩放并压缩图片…');
                transientImage = await supplementalFigureImportTools
                    .prepareTransientImage(manual.file);
            }
            if (supplementalFigureImportSession.action === 'edit') {
                const editingFigure = supplementalFigureImportSession.figure;
                importResult = await supplementalFigureImportTools.deliverUpdate(target, {
                    figureId: editingFigure?.figureId,
                    caption: manual.caption,
                    figureLabel: metadata.figureLabel,
                    sourcePage: metadata.sourcePage,
                    ...(transientImage ? {
                        transientImage,
                        sourceFileName: manual.file.name,
                        sourceMimeType: manual.file.type,
                        sourceFileSize: manual.file.size
                    } : {})
                });
            } else if (manual.file) {
                const request = supplementalFigureImportTools.createImageImport(
                    manual.file, transientImage, manual.caption, metadata
                );
                importResult = await supplementalFigureImportTools.deliverImport(target, request);
            } else {
                const request = await supplementalFigureImportTools.createCaptionImport(
                    manual.caption, metadata
                );
                importResult = await supplementalFigureImportTools.deliverImport(target, request);
            }
        }
        const importedLabel = String(importResult?.figureLabel || '补充 Figure');
        const panelHints = Array.isArray(importResult?.panelHints)
            ? importResult.panelHints : [];
        const importedMessage = `${importedLabel} ${
            supplementalFigureImportSession.action === 'edit' ? '已更新' : '已新建'
        }` +
            (panelHints.length ? `；已识别 Panel ${panelHints.join('、')}` : '；暂未识别到 Panel');
        const directoryMessage = mode === 'pdf' ? ''
            : importResult?.directoryPersisted === true
                ? '；图片和图注已写入所选文件夹'
                : '；已保存在浏览器，但所选文件夹尚未完成写入，请重新授权文件夹后点击“保存全部”';
        const persistedMessage = `${importedMessage}${directoryMessage}`;
        setSupplementalFigureImportStatus(
            mode === 'pdf' ? '已在新标签页打开 PDF 工作区' : persistedMessage
        );
        closeSupplementalFigureImportDialog();
        showStatus(
            mode === 'pdf'
                ? '已在新标签页打开补充 PDF 工作区'
                : persistedMessage,
            mode !== 'pdf' && importResult?.directoryPersisted !== true
                ? 'error' : 'success'
        );
        await refreshArticleWorkspace();
    } catch (error) {
        setSupplementalFigureImportStatus(error.message, { error: true });
        focusSupplementalFigureImportError(error);
    } finally {
        if (submit) submit.disabled = false;
    }
}

function setupSupplementalFigureImport() {
    const dialog = document.getElementById('supplementalFigureImportDialog');
    const form = document.getElementById('supplementalFigureImportForm');
    document.getElementById('openSupplementalFigureImport')?.addEventListener(
        'click', openSupplementalFigureImportDialog
    );
    document.getElementById('closeSupplementalFigureImport')?.addEventListener(
        'click', closeSupplementalFigureImportDialog
    );
    document.getElementById('cancelSupplementalFigureImport')?.addEventListener(
        'click', closeSupplementalFigureImportDialog
    );
    form?.addEventListener('change', event => {
        if (event.target?.name === 'supplementalFigureSourceMode') {
            supplementalFigureImportTools.syncSourceMode(dialog, event.target.value);
            setSupplementalFigureImportStatus('');
            return;
        }
        if (event.target?.id === 'supplementalFigureImageFile') {
            supplementalFigureImportSession.clipboardFile = null;
            updateSupplementalFigureSelectedImage(event.target.files?.[0] || null, {
                existing: supplementalFigureImportSession.figure?.hasImage === true
            });
        } else if (event.target?.id === 'supplementalFigureKind') {
            const label = document.getElementById('supplementalFigureLabel');
            if (label) label.placeholder = event.target.value === 'main'
                ? '例如 Figure 3' : '例如 Figure S2（留空则自动编号）';
        }
    });
    document.getElementById('supplementalFigurePasteTarget')?.addEventListener(
        'click', event => event.currentTarget?.focus?.()
    );
    dialog?.addEventListener('paste', event => {
        const file = supplementalFigureImportTools.clipboardImageFile(
            event.clipboardData
        );
        if (!file) return;
        event.preventDefault();
        supplementalFigureImportTools.syncSourceMode(dialog, 'manual');
        setSupplementalFigureClipboardFile(file);
        setSupplementalFigureImportStatus('已从剪贴板导入图片');
    });
    form?.addEventListener('submit', event => {
        void submitSupplementalFigureImport(event);
    });
}

async function sendTabMessage(tabId, message, options = {}) {
    if (!activePanelTabContext.activated ||
        Number(tabId) !== Number(activePanelTabContext.tabId)) {
        const error = new Error('当前标签页尚未激活，请点击侧栏任意位置激活');
        error.code = 'PANEL_TAB_NOT_ACTIVATED';
        throw error;
    }
    if (activePanelTabContext.offlineMode === true) {
        const context = capturePanelContext();
        const response = await chrome.runtime.sendMessage({ type: 'OFFLINE_ARTICLE_GET_SNAPSHOT', tabId, readerUrl: context.url });
        if (!isCurrentPanelContext(context) || !response?.success || !response.data?.snapshot) throw Object.assign(
            new Error('这篇离线文献的保存记录暂不可用，请重新打开'), { code: 'OFFLINE_READER_UNAVAILABLE' });
        const snapshot = response.data.snapshot;
        if (message.action === 'getArticleWorkspaceSnapshot') return { success: true, snapshot };
        if (message.action === 'getFigureWorkspaceSnapshot') return { success: true, snapshot: snapshot.figures };
        if (message.action === 'getArticleAbbreviations') return { success: true, abbreviations: snapshot.abbreviations };
        if (message.action === 'getReviewOutlineStatus') return { success: true, status: { running: false, phase: 'idle' }, hasOutline: Boolean(snapshot.reviewOutline), outline: snapshot.reviewOutline };
        if (message.action === 'getContentScriptRevision') return { revision: 'offline-saved-records', documentIdentity: snapshot.documentId, navigationIdentity: context.url };
        if (message.action === 'prepareManualAnnotations') return { success: true, documentId: snapshot.documentId, documentHash: snapshot.documentHash,
            canonicalUrl: snapshot.url, title: snapshot.title, annotationCount: snapshot.manual?.annotations?.length || 0,
            unresolvedCount: snapshot.manual?.annotations?.filter(item => item.unresolved).length || 0 };
        throw Object.assign(new Error('离线记录为只读；需要修改或重新分析时请打开在线原文。'), { code: 'OFFLINE_ARTICLE_READ_ONLY' });
    }
    return SciLLM.sendTabMessageWithRecovery(chrome, tabId, message, options);
}

async function resolveSupplementalReaderTab(figure = {}) {
    const readerUrl = String(figure.sourceReaderUrl || '').trim();
    const storedTabId = Number(figure.sourceReaderTabId);
    let tab = null;
    if (Number.isInteger(storedTabId) && storedTabId >= 0) {
        tab = await chrome.tabs.get(storedTabId).catch(() => null);
        if (tab && !SciLLM.isPdfReaderUrl?.(tab.url || tab.pendingUrl)) tab = null;
    }
    if (!tab && readerUrl) {
        const tabs = await chrome.tabs.query({});
        tab = tabs.find(candidate => candidate.url === readerUrl ||
            candidate.pendingUrl === readerUrl) || null;
    }
    if (!tab && readerUrl) {
        const currentTabId = Number(activePanelTabContext.tabId);
        tab = Number.isInteger(currentTabId) && currentTabId >= 0
            ? await chrome.tabs.update(currentTabId, { url: readerUrl, active: true })
            : await chrome.tabs.create({ url: readerUrl, active: true });
        await SciLLM.markTabActivated?.(chrome.storage.session, {
            ...tab,
            url: readerUrl,
            pendingUrl: readerUrl,
            title: figure.sourceTitle || '补充材料 PDF'
        });
    } else if (tab?.id) {
        await chrome.tabs.update(tab.id, { active: true });
    }
    if (!tab?.id) throw new Error('补充 PDF 工作区已关闭，且无法恢复解析页面');
    if (Number.isInteger(tab.windowId)) {
        await chrome.windows.update(tab.windowId, { focused: true });
    }
    return tab;
}

async function waitForSupplementalReaderFigure(tabId, figure = {}) {
    const parsedLabel = SciLLM.parseFigureLabel?.(figure.figureLabel);
    const sourceFigureId = String(
        figure.originalFigureId || parsedLabel?.figureId || figure.figureId || ''
    );
    const deadline = Date.now() + 180000;
    let lastError = null;
    while (Date.now() < deadline) {
        try {
            const response = await SciLLM.sendTabMessageIfPresent(chrome, tabId, {
                action: 'getFigureWorkspaceSnapshot'
            });
            const figures = Array.isArray(response?.snapshot?.figures)
                ? response.snapshot.figures : [];
            const match = figures.find(item =>
                item.figureId === sourceFigureId ||
                item.figureLabel === figure.figureLabel
            );
            if (match) return match.figureId;
        } catch (error) {
            lastError = error;
        }
        await new Promise(resolve => setTimeout(resolve, 750));
    }
    throw lastError || new Error('补充 PDF 尚未完成解析，请稍后重试');
}

async function runExternalSupplementalFigureAnalysis(figure = {}, options = {}) {
    return runSingleFigureAnalysis(String(figure?.figureId || ''), options);
}

async function runPaperMetaExtraction(taskKind) {
    const task = taskKind === 'innovation' || taskKind === 'limitations'
        ? taskKind : 'research_logic';
    const labels = {
        research_logic: ['研究背景与科学问题', 'analyzeResearchLogicWithLLM'],
        innovation: ['全文创新点', 'analyzePaperInnovationWithLLM'],
        limitations: ['研究局限', 'analyzePaperLimitationsWithLLM']
    };
    if (!requireUsableLlm(labels[task][0])) return;
    const state = paperMetaTaskState[task];
    if (state.running) return;
    if (!literatureNoteDocumentState) await loadLiteratureNoteDocumentState();
    const noteContext = captureLiteratureNoteContext();
    const initialFieldRevisions = new Map(literatureNoteFieldEditVersions);
    const expectedDocumentHash = String(
        currentWorkspaceSnapshot?.documentHash ||
        preparedDocumentState?.documentHash ||
        manualAnnotationState?.documentHash || ''
    ).trim();
    let tab = null;
    let panelContext = null;
    state.running = true;
    state.error = '';
    state.phase = 'requesting';
    state.changedFields = 0;
    updatePaperMetaTaskButtons(task);
    showStatus(`正在提取${labels[task][0]}…`, 'success');
    try {
        tab = await queryPanelTargetTab();
        if (!tab?.id) throw new Error('无法获取当前论文页面');
        panelContext = capturePanelContext();
        const response = await sendTabMessage(tab.id, {
            action: labels[task][1]
        });
        if (!isCurrentPanelContext(panelContext) ||
            !isCurrentLiteratureNoteContext(noteContext)) {
            return { stale: true };
        }
        if (!response?.success) {
            const error = new Error(response?.error || `${labels[task][0]}提取失败`);
            error.code = response?.code;
            throw error;
        }
        const result = response.result || {};
        if (expectedDocumentHash &&
            String(result.documentHash || '').trim() !== expectedDocumentHash) {
            const error = new Error('论文正文身份已变化，已丢弃不属于当前文献的提取结果');
            error.code = 'LITERATURE_NOTE_DOCUMENT_CHANGED';
            throw error;
        }
        state.phase = 'integrating';
        updatePaperMetaTaskButtons(task);
        await refreshArticleWorkspace();
        if (!isCurrentPanelContext(panelContext) ||
            !isCurrentLiteratureNoteContext(noteContext)) {
            return { stale: true };
        }
        const integrated = applyCurrentPaperMetaToLiteratureNote(
            initialFieldRevisions
        );
        state.changedFields = integrated.changedFields.length;
        if (integrated.changedFields.length) {
            state.phase = 'saving';
            updatePaperMetaTaskButtons(task);
            const persisted = await persistLiteratureNoteDocumentState(noteContext);
            if (persisted?.stale || !isCurrentPanelContext(panelContext) ||
                !isCurrentLiteratureNoteContext(noteContext)) {
                return { stale: true };
            }
        }
        state.phase = 'complete';
        updatePaperMetaTaskButtons(task);
        const cacheHit = result?.cache?.atomicEvidence === 'hit';
        const partial = result?.partial === true;
        showStatus(
            `${labels[task][0]}${partial ? '已部分生成，需人工核验' : '已生成'}` +
                (cacheHit ? '（已复用正文证据缓存）' : ''),
            partial ? 'warning' : 'success'
        );
        await persistCurrentArticleArchive().catch(() => null);
        return {
            success: true,
            taskKind: task,
            changedFields: integrated.changedFields,
            partial,
            cacheHit
        };
    } catch (error) {
        if (panelContext && (!isCurrentPanelContext(panelContext) ||
            !isCurrentLiteratureNoteContext(noteContext))) {
            return { stale: true };
        }
        state.error = String(error?.message || '提取失败');
        state.phase = 'failed';
        showStatus(`${labels[task][0]}提取失败：${state.error}`, 'error');
        return { success: false, error: state.error, code: error?.code || '' };
    } finally {
        state.running = false;
        updatePaperMetaTaskButtons(task);
        const terminalPhase = state.phase;
        setTimeout(() => {
            if (!state.running && state.phase === terminalPhase &&
                ['complete', 'failed'].includes(terminalPhase)) {
                state.phase = '';
                state.changedFields = 0;
                updatePaperMetaTaskButtons(task);
            }
        }, 2400);
    }
}

// Inserted unchanged into popup/content worlds; uses existing workspace routes and hash helper.
function createFigureSourceJournalBridge({ target: sourceTarget, sendMessage, assertCurrent }) {
    const target = structuredClone(sourceTarget);
    const stable = value => JSON.stringify(value, (_key, item) => item && typeof item === 'object' && !Array.isArray(item)
        ? Object.fromEntries(Object.keys(item).sort().map(key => [key, item[key]])) : item);
    const unknown = cause => Object.assign(new Error('来源保存结果待核验；请双击“核验/恢复来源”，确认前不会重复保存。'), {
        code: 'WRITE_OUTCOME_UNKNOWN', reasonCode: 'SOURCE_WRITE_RECEIPT_UNCONFIRMED', retryable: false, cause });
    const query = async (entry, type = 'ARTICLE_WORKSPACE_FIGURE_SOURCE_WRITE_STATUS', acknowledge = false) => {
        assertCurrent();
        const response = await figureBulkAwaitRead(sendMessage({ type, workspaceId: target.workspaceId,
            workspaceGeneration: target.workspaceGeneration, target, relativePath: entry.message.relativePath,
            contentHash: entry.message.contentHash, ...(entry.writeId ? { figureSourceWriteId: entry.writeId } : {}),
            ...(acknowledge ? { acknowledge: true } : {}) }), null, { timeoutMs: 30000 });
        assertCurrent();
        return response;
    };
    const matches = (entry, response) => {
        const data = response?.data, receipt = data?.figureSourceWriteReceipt;
        return response?.success === true && receipt?.relativePath === entry.message.relativePath &&
            receipt.workspaceGeneration === target.workspaceGeneration &&
            (!entry.writeId || data.figureSourceWriteId === entry.writeId) &&
            receipt.writeId === data.figureSourceWriteId && /^figure-source-write-[A-Za-z0-9-]{8,100}$/.test(receipt.writeId);
    };
    const confirmed = (entry, response) => matches(entry, response) && response.data.confirmed === true &&
        response.data.saved === true && response.data.directoryPersisted === true &&
        ['committed', 'acknowledged'].includes(response.data.figureSourceWriteReceipt.status) &&
        response.data.asset?.relativePath === entry.message.relativePath &&
        Number.isSafeInteger(response.data.asset.revision) && response.data.asset.revision >= 1 &&
        response.data.asset.contentHash === entry.message.contentHash &&
        response.data.asset.revision === response.data.figureSourceWriteReceipt.committedRevision &&
        response.data.asset.contentHash === response.data.figureSourceWriteReceipt.committedContentHash;
    const confirmAndAck = async (entry, response) => {
        if (!confirmed(entry, response)) return null;
        entry.writeId = response.data.figureSourceWriteId;
        const read = await figureBulkAwaitRead(sendMessage({ type: 'ARTICLE_WORKSPACE_GET_ASSET', target,
            workspaceId: target.workspaceId, workspaceGeneration: target.workspaceGeneration,
            relativePath: entry.message.relativePath }), null, { timeoutMs: 15000 });
        assertCurrent();
        const asset = read?.data?.asset;
        if (read?.success !== true || read.data.workspaceGeneration !== target.workspaceGeneration || !asset || asset.revision !== response.data.asset.revision ||
            asset.contentHash !== entry.message.contentHash || stable(asset.content) !== entry.content) return null;
        const acknowledged = await query(entry, 'ARTICLE_WORKSPACE_FIGURE_SOURCE_WRITE_STATUS', true);
        if (!confirmed(entry, acknowledged) || acknowledged.data.asset.revision !== asset.revision ||
            acknowledged.data.figureSourceWriteReceipt.status !== 'acknowledged') return null;
        return acknowledged;
    };
    return {
        async save(message, entry) {
            entry.journalSourceWrite = true;
            entry.message = structuredClone(message);
            entry.content = stable(message.content);
            try {
                const existing = await query(entry);
                if (existing?.success === true) {
                    if (!matches(entry, existing)) throw unknown();
                    entry.writeId = existing.data.figureSourceWriteId;
                    entry.journalObserved = true;
                    const recovered = await confirmAndAck(entry, existing);
                    if (recovered) return recovered;
                    if (existing.data.figureSourceWriteReceipt.status !== 'fenced') throw unknown();
                    // Only an already persisted local fence permits a new write on this path.
                    entry.writeId = null;
                } else if (existing?.error?.code !== 'FIGURE_SOURCE_WRITE_NOT_FOUND') throw unknown();
                assertCurrent();
                entry.writeId = 'figure-source-write-' + crypto.randomUUID();
                entry.message.figureSourceWriteId = entry.writeId;
                entry.dispatched = true;
                let response;
                try { response = await figureBulkAwaitRead(sendMessage(entry.message), null, { timeoutMs: 30000, mutation: true }); }
                catch (_) { /* A lost callback is resolved only by independent journal evidence below. */ }
                if (response?.success === false && response.data == null &&
                    !response.error?.writeOutcomeUnknown && !response.error?.cleanupPending &&
                    ['ASSET_REVISION_CONFLICT', 'ASSET_HASH_CONFLICT', 'FIGURE_SOURCE_BASE_CONFLICT'].includes(response.error?.code)) {
                    throw Object.assign(new Error(response.error.message || response.error.code), {
                        code: response.error.code, sourceConflict: true, retryable: false });
                }
                const status = await query(entry);
                const verified = await confirmAndAck(entry, status);
                if (!verified) throw unknown();
                return verified;
            } catch (error) {
                if (error?.sourceConflict === true) throw error;
                throw unknown(error);
            }
        },
        async reconcile(entry, { explicitRecovery = false } = {}) {
            let response = await query(entry);
            if (!matches(entry, response)) return false; // Absence never proves a dispatched write was unwritten.
            entry.writeId ||= response.data.figureSourceWriteId;
            if (response.data.figureSourceWriteReceipt.status === 'fenced') return true;
            if (explicitRecovery && response.data.figureSourceWriteReceipt.status === 'intent') {
                response = await query(entry, 'ARTICLE_WORKSPACE_FIGURE_SOURCE_WRITE_FENCE');
                if (matches(entry, response) && response.data.status === 'fenced' && response.data.unwritten === true) return true;
            }
            return Boolean(await confirmAndAck(entry, response));
        }
    };
}

function figureBulkSourceError(detail = '') {
    return Object.assign(new Error('补充来源尚未准备完整，已保存结果保留。' + detail),
        { code: 'FIGURE_SOURCE_PREPARATION_REQUIRED' });
}

function figureBulkDeclaredPdfMaterials(materials = [], options = {}) {
    const byId = new Map();
    for (const material of materials) {
        // Known Word sources cannot be certified by the native PDF-only proof.
        // Query values do not identify the attachment format.
        if (/^(?:docx?|word)$/i.test(String(material?.sourceFormat || '')) ||
            /\.docx?$/i.test(String(material?.url || '').split(/[?#]/u)[0])) {
            if (!options.allowDocx) throw figureBulkSourceError('已声明的 Word 补充附件尚未具备逐图来源证明，请先准备该附件。');
        }
        // Opaque discovered attachments include publisher PDF wrapper pages.
        if (!['pdf', 'attachment'].includes(material?.kind) && material?.sourceMode !== 'pdf' &&
            !material?.sourceWrapper && !(options.allowDocx && (/^(?:docx?|word)$/i.test(String(material?.sourceFormat || '')) ||
            /\.docx?$/i.test(String(material?.url || '').split(/[?#]/u)[0])))) continue;
        if (!material.materialId || !material.url) throw figureBulkSourceError('补充材料缺少来源标识。');
        const prior = byId.get(material.materialId);
        if (prior && prior.url !== material.url) throw figureBulkSourceError('补充材料来源发生冲突。');
        byId.set(material.materialId, Object.freeze({ ...material }));
    }
    return [...byId.values()];
}

function figureBulkAwaitRead(promise, signal, { timeoutMs = 30000, mutation = false } = {}) {
    return new Promise((resolve, reject) => {
        let timer = null;
        const cleanup = () => { if (timer !== null) clearTimeout(timer); signal?.removeEventListener('abort', abort); };
        const finish = (handler, value) => { cleanup(); handler(value); };
        const abort = () => finish(reject, Object.assign(new Error('来源准备已停止'), { code: 'CANCELLED' }));
        if (timeoutMs > 0) timer = setTimeout(() => finish(reject, Object.assign(new Error('来源读取超过等待上限'), {
            code: 'FIGURE_SOURCE_TIMEOUT', reasonCode: mutation ? 'SOURCE_WRITE_RECEIPT_TIMEOUT' : 'SOURCE_READ_TIMEOUT', retryable: true })), timeoutMs);
        if (signal?.aborted) abort();
        else signal?.addEventListener('abort', abort, { once: true });
        // Retain both handlers so a late rejected reply is drained after timeout.
        Promise.resolve(promise).then(value => finish(resolve, value), error => finish(reject, error));
    });
}

async function figureBulkReadAuxiliarySource(material, target, dependencies) {
    const { assertCurrent, signal, sendMessage } = dependencies;
    const check = () => { if (signal?.aborted) throw Object.assign(new Error('来源准备已停止'), { code: 'CANCELLED' }); assertCurrent(); };
    const relativePath = SciLLM.supplementalFigureAssetPath(material.materialId);
    const read = async () => {
        check();
        const response = await figureBulkAwaitRead(sendMessage({ type: 'ARTICLE_WORKSPACE_GET_ASSET',
            workspaceId: target.workspaceId, workspaceGeneration: target.workspaceGeneration, relativePath, target }), signal);
        check();
        if (!response?.success) throw figureBulkSourceError('补充附件检查记录无法读取。');
        return response.data?.asset;
    };
    const stored = await read(), asset = stored?.content;
    if (!asset?.sourceInspection && !asset?.sourceWrapper) return null;
    if (!Number.isSafeInteger(stored.revision) || stored.revision < 1 || !stored.contentHash ||
        asset.materialId !== material.materialId || asset.sourceUrl !== material.url ||
        asset.parentWorkspaceId !== target.workspaceId || asset.parentWorkspaceGeneration !== target.workspaceGeneration ||
        asset.parentCanonicalUrl !== target.canonicalUrl || asset.parentDocumentHash !== target.documentHash)
        throw figureBulkSourceError('附件检查记录不属于当前论文。');
    let projected = SciLLM.projectSupplementalDocxNoFigureMaterial(material, asset, target);
    if (!projected && asset.sourceWrapper) {
        const wrapper = asset.sourceWrapper;
        if (wrapper.parentWorkspaceId !== target.workspaceId || wrapper.parentWorkspaceGeneration !== target.workspaceGeneration ||
            wrapper.parentCanonicalUrl !== target.canonicalUrl || wrapper.parentDocumentHash !== target.documentHash)
            throw figureBulkSourceError('附件下载页归属已变化。');
        try { projected = SciLLM.projectSupplementalJciWrapperMaterial(material, wrapper, target); }
        catch (_) { throw figureBulkSourceError('附件下载页检查记录未通过核验。'); }
        if (!['xlsx','csv'].includes(projected.sourceFormat) || !Array.isArray(asset.figures) || asset.figures.length) return null;
    }
    if (!projected) return null;
    // GET_ASSET reads the database. Force the existing mirror/readback path so a
    // previous directory failure cannot turn into a cache success on retry.
    check();
    const flushed = await figureBulkAwaitRead(sendMessage({ type: 'ARTICLE_WORKSPACE_SAVE_ASSET',
        workspaceId: target.workspaceId, workspaceGeneration: target.workspaceGeneration, relativePath, target,
        content: asset, expectedRevision: stored.revision, expectedContentHash: stored.contentHash,
        contentHash: stored.contentHash, requireDirectoryPersistence: true }), signal, { mutation: true });
    check();
    if (flushed?.success !== true || flushed.data?.saved !== true || flushed.data.directoryPersisted !== true ||
        flushed.data.asset?.relativePath !== relativePath) throw figureBulkSourceError('附件检查记录尚未保存到本地目录。');
    const after = await read();
    if (after?.revision !== flushed.data.asset.revision || after?.contentHash !== flushed.data.asset.contentHash ||
        JSON.stringify(after?.content) !== JSON.stringify(asset))
        throw figureBulkSourceError('附件检查记录在核验时发生变化。');
    return { materialId: material.materialId, sourceUrl: material.url, figureIds: [],
        projectedMaterial: projected, relativePath, revision: after.revision, contentHash: after.contentHash,
        sourceFormat: projected.sourceFormat, complete: true };
}

async function figureBulkReadNativeSource(material, target, dependencies) {
    const { assertCurrent, signal, sendMessage } = dependencies;
    const check = () => { if (signal?.aborted) throw Object.assign(new Error('来源准备已停止'), { code: 'CANCELLED' }); assertCurrent(); };
    check();
    const relativePath = SciLLM.supplementalFigureAssetPath(material.materialId);
    const getAsset = async () => {
        check();
        const response = await figureBulkAwaitRead(sendMessage({ type: 'ARTICLE_WORKSPACE_GET_ASSET',
            workspaceId: target.workspaceId, workspaceGeneration: target.workspaceGeneration, relativePath, target }), signal);
        check();
        if (!response?.success) throw figureBulkSourceError(response?.error?.message || '无法读取补充目录。');
        return response.data?.asset || null;
    };
    const stored = await getAsset();
    const asset = stored?.content;
    if (asset?.sourceFormat === 'docx' && asset.docxFigureManifest) {
        if (!Number.isSafeInteger(stored.revision) || stored.revision < 1 || !stored.contentHash)
            throw figureBulkSourceError('DOCX 保存身份未确认。');
        SciLLM.validateSupplementalDocxFigureAsset(asset,material,target);check();
        const flushed=await figureBulkAwaitRead(sendMessage({type:'ARTICLE_WORKSPACE_SAVE_ASSET',
            workspaceId:target.workspaceId,workspaceGeneration:target.workspaceGeneration,relativePath,target,
            content:asset,expectedRevision:stored.revision,expectedContentHash:stored.contentHash,
            contentHash:stored.contentHash,requireDirectoryPersistence:true}),signal,{mutation:true});check();
        if(flushed?.success!==true || flushed.data?.saved!==true || flushed.data.directoryPersisted!==true ||
            flushed.data.asset?.relativePath!==relativePath)throw figureBulkSourceError('DOCX 目录尚未完成本地保存。');
        const directoryStored=await getAsset();
        if(directoryStored?.revision!==flushed.data.asset.revision || directoryStored?.contentHash!==flushed.data.asset.contentHash ||
            JSON.stringify(directoryStored?.content)!==JSON.stringify(asset))throw figureBulkSourceError('DOCX 目录在保存核验时发生变化。');
        const proof=await SciLLM.verifySupplementalDocxFigureAsset(directoryStored.content,material,target,async image=>{
            check();const response=await figureBulkAwaitRead(sendMessage({type:'ARTICLE_WORKSPACE_GET_BINARY_ASSET',
                workspaceId:target.workspaceId,workspaceGeneration:target.workspaceGeneration,target,
                relativePath:image.relativePath,mimeType:image.mimeType}),signal);check();
            if(response?.success!==true)throw figureBulkSourceError('DOCX 原图读取失败。');return response.data;
        },check);
        const after=await getAsset();
        if(after?.revision!==directoryStored.revision || after?.contentHash!==directoryStored.contentHash ||
            JSON.stringify(after?.content)!==JSON.stringify(directoryStored.content))
            throw figureBulkSourceError('DOCX 目录在核验期间发生变化。');
        return {...proof,figureIds:asset.figures.map(f=>SciLLM.normalizeSupplementalFigure(f,asset).figureId)};
    }
    const manifest = asset?.parsedDocument?.pdfFigureManifest;
    if (!manifest || manifest.source !== 'pdffigures2') return null;
    if (!Number.isSafeInteger(stored.revision) || stored.revision < 1 || typeof stored.contentHash !== 'string' || !stored.contentHash) {
        throw figureBulkSourceError('补充目录保存身份未确认。');
    }
    if (asset.materialId !== material.materialId || asset.sourceUrl !== material.url ||
        asset.parentWorkspaceId !== target.workspaceId || asset.parentWorkspaceGeneration !== target.workspaceGeneration ||
        asset.parentCanonicalUrl !== target.canonicalUrl || (asset.parentDocumentHash || '') !== (target.documentHash || '')) {
        throw Object.assign(figureBulkSourceError('补充目录不属于当前论文。'), { sourceConflict: true });
    }
    // Existing source fingerprints must agree even for an incomplete manifest.
    const knownFingerprint = String(manifest.documentFingerprint || '').replace(/^sha256:/, '');
    if (knownFingerprint && (!/^[a-f0-9]{64}$/.test(knownFingerprint) || asset.parsedDocument.originalDocumentHash &&
        String(asset.parsedDocument.originalDocumentHash).replace(/^sha256:/, '') !== knownFingerprint))
        throw Object.assign(figureBulkSourceError('补充 PDF 原始文件指纹未确认。'), { sourceConflict: true });
    // The native manifest completion state is ready; the parent image count is conservative.
    // Verified cached bytes do not override pending/partial/cancelled/error parsing state.
    if (manifest.status !== 'ready' || manifest.error != null) {
        throw Object.assign(figureBulkSourceError('补充 PDF 解析尚未完成或存在解析错误。'), { retryableSource: true, sourceReason: 'incomplete-manifest', sourceState: manifest.status });
    }
    if (!Array.isArray(manifest.figures) || !manifest.figures.length || manifest.figures.length > 300) {
        throw Object.assign(figureBulkSourceError('补充图目录仍不完整。'), { retryableSource: true, sourceReason: Array.isArray(manifest.figures) && !manifest.figures.length ? 'zero-figures' : 'incomplete-manifest' });
    }
    const sourceSha256 = String(manifest.documentFingerprint || '').replace(/^sha256:/, '');
    if (!/^[a-f0-9]{64}$/.test(sourceSha256) || asset.parsedDocument.originalDocumentHash &&
        String(asset.parsedDocument.originalDocumentHash).replace(/^sha256:/, '') !== sourceSha256)
        throw Object.assign(figureBulkSourceError('补充 PDF 原始文件指纹未确认。'), { sourceConflict: true });
    const expected = new Map(), keys = new Set(), figureIds = [];
    for (const entry of SciLLM.supplementalPdfSourceImageEntries(manifest)) {
        const path = String(entry?.image?.workspacePath || ''), hash = String(entry?.image?.sha256 || '').toLowerCase();
        if (!/^pdf\/figures\/supplemental\/[^/]+\.(?:png|jpe?g|webp)$/i.test(path) || path.includes('\\') ||
            path.includes('..') || !/^[a-f0-9]{64}$/.test(hash) || expected.has(path) && expected.get(path) !== hash) {
            throw Object.assign(figureBulkSourceError('补充图片清单发生冲突。'), { sourceConflict: true });
        }
        expected.set(path, hash);
    }
    for (const entry of SciLLM.supplementalPdfLogicalEntries(manifest)) {
        const key = SciLLM.supplementalFigureKey(entry.figureLabel || entry.label || entry.name || entry.figureId);
        const matches = (asset.figures || []).filter(figure =>
            SciLLM.supplementalFigureKey(figure.figureLabel || figure.originalFigureId || figure.figureId) === key);
        if (!key || keys.has(key) || matches.length !== 1 || typeof matches[0].caption !== 'string' || !matches[0].caption.trim()) {
            throw figureBulkSourceError('补充图注与图像未能逐项对应。');
        }
        keys.add(key);
        const normalized = SciLLM.normalizeSupplementalFigure(matches[0], asset);
        if (!normalized?.figureId) throw figureBulkSourceError('补充 Figure 身份未确认。');
        figureIds.push(normalized.figureId);
    }
    const verifiedAssets = [];
    for (const [path, hash] of expected) {
        check();
        const response = await figureBulkAwaitRead(sendMessage({ type: 'ARTICLE_WORKSPACE_GET_BINARY_ASSET',
            workspaceId: target.workspaceId, workspaceGeneration: target.workspaceGeneration,
            relativePath: path, mimeType: 'image/png', target }), signal);
        check();
        const data = response?.data;
        const match = /^data:image\/(?:png|jpeg|webp);base64,([a-z0-9+/=]+)$/i.exec(String(data?.dataUrl || ''));
        if (!response?.success || !data?.found || data.relativePath !== path || String(data.sha256 || '').toLowerCase() !== hash || !match) {
            throw Object.assign(figureBulkSourceError('补充图片尚未在当前论文目录中核实。'), { retryableSource: !data?.found, sourceConflict: data?.found === true });
        }
        const bytes = Uint8Array.from(atob(match[1]), character => character.charCodeAt(0));
        const digest = typeof SciLLM.sha256FigureBytes === 'function'
            ? await SciLLM.sha256FigureBytes(bytes)
            : Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256', bytes))).map(value=>value.toString(16).padStart(2,'0')).join('');
        if (!bytes.byteLength || digest !== hash) throw Object.assign(figureBulkSourceError('补充图片字节校验未通过。'), { sourceConflict: true });
        check();
        verifiedAssets.push({ relativePath: path, sha256: hash, byteLength: bytes.byteLength, verified: true });
    }
    const after = await getAsset();
    if (after?.revision !== stored.revision || after?.contentHash !== stored.contentHash) throw Object.assign(figureBulkSourceError('补充目录在核验期间发生变化。'), { sourceConflict: true });
    const proof = { materialId: material.materialId, sourceUrl: material.url, sourceSha256, figureIds,
        sourceImagePersistence: { complete: true, workspaceId: target.workspaceId,
            workspaceGeneration: target.workspaceGeneration, canonicalUrl: target.canonicalUrl,
            documentHash: target.documentHash || '', verifiedAssets } };
    // Derive PDF completeness from this read of every image, never an old inspection flag.
    const inspection = SciLLM.supplementalMaterialInspectionFromAsset(material, { ...asset, sourceInspection: undefined }, target, proof);
    if (!inspection) throw figureBulkSourceError('补充 PDF 图目录与当前来源证明不一致。');
    return { ...proof, inspection };
}

function figureBulkRequireImportReceipt(result, target, expected) {
    const proof = result?.sourceImagePersistence;
    // needsAttention covers the entire parent, including materials not yet imported.
    // This receipt certifies only this material; final coverage is checked after the loop.
    if (result?.stage !== 'complete' || result.cancelled || proof?.complete !== true ||
        proof.workspaceId !== target.workspaceId || proof.workspaceGeneration !== target.workspaceGeneration ||
        proof.canonicalUrl !== target.canonicalUrl || (proof.documentHash || '') !== (target.documentHash || '') ||
        !Array.isArray(proof.verifiedAssets) || expected.sourceImagePersistence.verifiedAssets.some(required =>
            !proof.verifiedAssets.some(actual => actual?.relativePath === required.relativePath &&
                String(actual.sha256 || '').toLowerCase() === required.sha256 && actual.verified === true &&
                Number.isSafeInteger(actual.byteLength) && actual.byteLength === required.byteLength))) {
        throw figureBulkSourceError('补充导入尚未取得完整保存回执。');
    }
}

async function prepareFigureBulkSourcePreflight(context, options = {}) {
    const { target, assertCurrent, signal, sendMessage, readSnapshot, importMaterial } = context;
    const check = () => { if (signal?.aborted) throw Object.assign(new Error('来源准备已停止'), { code: 'CANCELLED' }); assertCurrent(); };
    const wait = promise => figureBulkAwaitRead(promise, signal, { timeoutMs: 120000 });
    check();
    let snapshot = await wait(readSnapshot()); check();
    const initialMaterials = figureBulkDeclaredPdfMaterials(snapshot?.figures?.supplemental?.materials || [], { allowDocx: true });
    const materialsKey = values => JSON.stringify(values.map(m => [m.materialId, m.url]));
    if (options.expectedDeclaredSources && materialsKey(initialMaterials) !== materialsKey(options.expectedDeclaredSources))
        throw figureBulkSourceError('已声明补充来源发生变化。');
    const deferredSource = id => options.deferSourceWork === true ||
        Array.isArray(options.recoveryMaterialIds) && !options.recoveryMaterialIds.includes(id);
    const initialInventory = snapshot?.figures?.figures || [];
    const independentUnfinished = initialInventory.some(figure =>
        !SciLLM.figureBulkSourceDependencyIds(figure, initialMaterials).length &&
        !figure.standard && !figure.modelStandard && !figure.deep && !figure.modelDeep);
    // Scheduling only: saved results do not certify reusable inputs. The
    // existing per-Figure cache/input checks still decide that in the queue.
    const deferUnrelated = options.deferUnrelatedSources === true && independentUnfinished &&
        options.forceSourceRecovery !== true;
    const deferredReadDeadline = Date.now() + 30000;
    const proofs = [], auxiliarySources = [], tiffSources = [], materialInspections = [], sourceIssues = [];
    const recordIssue = (material, error, deferred = false) => {
        check();
        if (['CANCELLED', 'WRITE_OUTCOME_UNKNOWN'].includes(error?.code) || error?.code === 'FIGURE_SOURCE_TIMEOUT' &&
            (error.reasonCode !== 'SOURCE_READ_TIMEOUT' || context.hasPendingSourceWork?.())) throw error;
        const unresolved = deferred || error?.sourceReason === 'zero-figures' ||
            /PDF_FIGURE_NONE_FOUND/.test(String(error?.code || '') + ' ' + String(error?.message || ''));
        sourceIssues.push({ materialId: material.materialId, title: material.title || material.materialId,
            url: material.url || '', status: unresolved ? 'pending' : 'failed',
            code: String(error?.code || 'SOURCE_PREPARATION_FAILED'),
            message: unresolved && !deferred ? 'PDF 尚未确认有无图，需补提取或完成格式分类。' : String(error?.message || '附件准备失败'),
            retryable: error?.sourceConflict !== true, deferred,
            retryAction: error?.sourceConflict ? 'resolve-source-conflict' : 'retry-source-preparation' });
    };
    for (const figure of initialInventory.filter(item => item.nativeTiffSource)) {
        check();
        if (deferUnrelated || deferredSource(figure.nativeTiffSource.materialId || figure.figureId)) {
            recordIssue({ materialId: figure.nativeTiffSource.materialId || figure.figureId,
                title: figure.figureLabel, url: figure.nativeTiffSource.sourceUrl },
                figureBulkSourceError('先解读可用网页图；TIFF 来源待核验，有明确依赖的目标将在本次操作内补来源，已有结果保留。'), true);
            continue;
        }
        try {
            if (typeof context.prepareTiffSource !== 'function') throw figureBulkSourceError('TIFF 来源尚未核验。');
            const result = await wait(context.prepareTiffSource(figure)); check();
            if (result?.success !== true || result.figureId !== figure.figureId ||
                result.sourceUrl !== figure.nativeTiffSource.sourceUrl || result.materialId !== figure.nativeTiffSource.materialId ||
                ['workspaceId', 'workspaceGeneration', 'canonicalUrl', 'documentHash', 'targetArticleTabId'].some(key => result.target?.[key] !== target[key]) ||
                result.persistence?.verified !== true || !/^[a-f0-9]{64}$/.test(result.persistence?.sha256 || '') ||
                !Number.isSafeInteger(result.persistence?.byteLength) || result.persistence.byteLength < 1 ||
                !/^[a-f0-9]{64}$/.test(result.sourceSha256 || '') || !Number.isSafeInteger(result.sourceByteLength) || result.sourceByteLength < 5)
                throw figureBulkSourceError(result?.message || 'TIFF 来源未取得完整保存回执。');
            const matches = (snapshot?.figures?.supplemental?.materials || []).filter(m => m.url === result.sourceUrl);
            if (matches.length !== 1) throw figureBulkSourceError('TIFF 与附件目录未能唯一对应。');
            const material = matches[0], sourceSha256 = result.sourceSha256;
            const record = SciLLM.createSupplementalMaterialInspection({ material, target, sourceSha256,
                sourceFormat: 'tiff', byteLength: result.sourceByteLength });
            const inspection = { sourceSha256, record: SciLLM.completeSupplementalMaterialInspection(record, {
                material, target, sourceSha256, inventoryComplete: true, classification: 'figure-material',
                figureKeys: [SciLLM.supplementalFigureKey(figure.figureLabel || figure.figureId)] }) };
            tiffSources.push(result); materialInspections.push(inspection);
        } catch (error) {
            recordIssue({ materialId: figure.nativeTiffSource.materialId || figure.figureId,
                title: figure.figureLabel, url: figure.nativeTiffSource.sourceUrl }, error);
        }
    }
    for (const material of initialMaterials) {
        check();
        if (independentUnfinished && (deferUnrelated || deferredSource(material.materialId)) && Date.now() >= deferredReadDeadline) {
            recordIssue(material, figureBulkSourceError('本轮附件读取预算已用完；先解读可用图，依赖此来源的图保留待补源。'), true);
            continue;
        }
        try {
            let auxiliary, proof, priorError;
            const cachedController = new AbortController();
            const cancelCached = () => cachedController.abort();
            if (signal?.aborted) cancelCached();
            else signal?.addEventListener('abort', cancelCached, { once: true });
            try {
                const cached = (async () => {
                    const dependencies = { assertCurrent, signal: cachedController.signal, sendMessage };
                    const auxiliary = await figureBulkReadAuxiliarySource(material, target, dependencies);
                    return { auxiliary, proof: auxiliary ? null : await figureBulkReadNativeSource(material, target, dependencies) };
                })();
                ({ auxiliary, proof } = await figureBulkAwaitRead(cached, signal, { timeoutMs:
                    independentUnfinished && (deferUnrelated || deferredSource(material.materialId))
                        ? Math.max(1, deferredReadDeadline - Date.now()) : 120000 }));
            } catch (error) {
                cachedController.abort();
                check();
                if (error?.code === 'CANCELLED' || error?.sourceConflict || error?.retryableSource !== true) throw error;
                priorError = error;
            } finally {
                signal?.removeEventListener('abort', cancelCached);
            }
            check();
            if (auxiliary) { auxiliarySources.push(auxiliary); continue; }
            if (!proof) {
                if (deferUnrelated || deferredSource(material.materialId)) {
                    recordIssue(material, figureBulkSourceError('先解读可用网页图；附件来源待补齐，有明确依赖的目标将在本次操作内补来源，已有结果保留。'), true);
                    continue;
                }
                if (!options.allowImport || typeof importMaterial !== 'function') throw priorError || figureBulkSourceError(material.title || '缺少已声明的补充来源。');
                const result = await wait(importMaterial(material, target, null, { signal, assertCurrent: check })); check();
                if (result?.cancelled === true) throw Object.assign(new Error('来源准备已停止'), { code: 'CANCELLED' });
                auxiliary = await wait(figureBulkReadAuxiliarySource(material, target, { assertCurrent, signal, sendMessage })); check();
                if (auxiliary) {
                    if (result?.success !== true || result.directoryPersisted !== true || result.relativePath !== auxiliary.relativePath)
                        throw figureBulkSourceError('附件检查尚未取得完整保存回执。');
                    auxiliarySources.push(auxiliary); continue;
                }
                proof = await wait(figureBulkReadNativeSource(material, target, { assertCurrent, signal, sendMessage })); check();
                if (!proof) {
                    const error = figureBulkSourceError(`补充来源尚未生成可核验目录。import stage=${String(result?.stage || '')}; cancelled=${result?.cancelled === true}; notStarted=${result?.notStarted === true}; path=${String(result?.relativePath || '')}`);
                    if ([result?.code, result?.error?.code].includes('PDF_FIGURE_NONE_FOUND')) error.sourceReason = 'zero-figures';
                    throw error;
                }
                figureBulkRequireImportReceipt(result, target, proof);
            }
            proofs.push(proof); materialInspections.push(proof.inspection);
        } catch (error) { recordIssue(material, error); }
    }
    snapshot = await wait(readSnapshot()); check();
    const materials = snapshot?.figures?.supplemental?.materials || [];
    if (materialsKey(figureBulkDeclaredPdfMaterials(materials, { allowDocx: true })) !== materialsKey(initialMaterials))
        throw figureBulkSourceError('已声明补充来源发生变化。');
    const inventory = snapshot?.figures?.figures || [];
    if (proofs.some(proof => proof.figureIds.some(id => !inventory.some(figure => figure.figureId === id))) ||
        tiffSources.some(proof => !inventory.some(figure => figure.figureId === proof.figureId && figure.nativeTiffSource?.sourceUrl === proof.sourceUrl)))
        throw figureBulkSourceError('来源准备期间 Figure 目录发生变化。');
    const projectedMaterials = materials.map(material => auxiliarySources.find(proof => proof.materialId === material.materialId)?.projectedMaterial || material);
    const coverage = SciLLM.buildSupplementalCoverage({ materials: projectedMaterials,
        references: snapshot?.figures?.supplemental?.references || [], figures: inventory, parentTarget: target, materialInspections });
    const plan = SciLLM.buildFigureBulkSourcePlan({ inventory, materials: initialMaterials, proofs, auxiliarySources,
        tiffSources, sourceIssues, coverage, priorCoverage: snapshot?.figures?.supplemental?.coverage || {} });
    if (!plan.readyFigureIds.length && options.allowEmpty !== true) {
        const error = figureBulkSourceError(SciLLM.formatFigureBulkSourceSummary(plan) || '没有已取得来源证明的可解读 Figure。');
        error.sourcePlan = plan; throw error;
    }
    return { target, declaredSources: initialMaterials, materials: proofs, auxiliarySources, tiffSources, coverage,
        ...plan, figureIds: plan.readyFigureIds, inventoryFigureIds: inventory.map(figure => figure.figureId) };
}

async function prepareFigureAnalysisDeclaredSources({ operationId, submittedContext, taskToken, tab, recoveryMaterialIds, expectedTarget, expectedDeclaredSources }) {
    const intent = sidebarBatchIntents.get(sidebarBatchKey('figures', submittedContext));
    if (intent?.sourceCleanupPending) {
        await intent.reconcileSourceWrites?.();
        if (intent.sourceCleanupPending) throw Object.assign(new Error('来源保存结果仍待核验；请双击核验/恢复来源。'), {
            code: 'WRITE_OUTCOME_UNKNOWN', reasonCode: 'SOURCE_WRITE_RECEIPT_UNCONFIRMED', retryable: false });
    }
    const controller = intent?.sourceController || new AbortController();
    let target = null;
    let sourceFailure = null;
    const pendingSourceWork = new Set();
    const sourceWrites = new Set();
    const trackSourceWork = promise => {
        const pending = Promise.resolve(promise);
        pendingSourceWork.add(pending);
        pending.then(() => pendingSourceWork.delete(pending), () => pendingSourceWork.delete(pending));
        return pending;
    };
    const stableSourceValue = value => JSON.stringify(value, (_key, item) => item &&
        typeof item === 'object' && !Array.isArray(item)
        ? Object.fromEntries(Object.keys(item).sort().map(key => [key, item[key]])) : item);
    let sourceJournalBridge;
    const journal = () => sourceJournalBridge ||= createFigureSourceJournalBridge({ target,
        sendMessage: message => chrome.runtime.sendMessage({ ...message,
            ...(intent?.figureUiOwnerBinding ? { figureUiOwnerBinding: intent.figureUiOwnerBinding } : {}) }), assertCurrent: () => {
            if (!isCurrentPanelContext(submittedContext) || sidebarBatchIntents.get(sidebarBatchKey('figures', submittedContext)) !== intent)
                throw Object.assign(new Error('来源核验对应的页面已变化'), { code: 'CANCELLED' });
            const actual = supplementalFigureImportTools.buildTarget(currentWorkspaceSnapshot, tab.id);
            if (['workspaceId', 'workspaceGeneration', 'canonicalUrl', 'documentHash', 'targetArticleTabId']
                .some(key => actual[key] !== target[key])) throw Object.assign(new Error('来源目标已变化'), { code: 'CANCELLED' });
        } });
    const verifySourceWrite = async (entry, { allowRefusal = false } = {}) => {
        if (entry.journalSourceWrite) return journal().reconcile(entry);
        const message = entry.message, receipt = entry.response?.data?.asset;
        const current = () => {
            if (!isCurrentPanelContext(submittedContext) || sidebarBatchIntents.get(sidebarBatchKey('figures', submittedContext)) !== intent) return false;
            const actual = supplementalFigureImportTools.buildTarget(currentWorkspaceSnapshot, tab.id);
            return ['workspaceId', 'workspaceGeneration', 'canonicalUrl', 'documentHash', 'targetArticleTabId']
                .every(key => actual[key] === target[key]);
        };
        if (!current()) return false;
        if (allowRefusal && entry.response?.success === false && entry.response.data == null &&
            !entry.response.writeOutcomeUnknown && !entry.response.cleanupPending &&
            !entry.response.error?.writeOutcomeUnknown && !entry.response.error?.cleanupPending &&
            ['ASSET_REVISION_CONFLICT', 'ASSET_HASH_CONFLICT', 'FIGURE_SOURCE_BASE_CONFLICT'].includes(entry.response.error?.code || entry.response.code)) return true;
        if (entry.response?.success !== true || entry.response.data.saved !== true ||
            entry.response.data.directoryPersisted !== true || receipt?.relativePath !== message.relativePath ||
            !Number.isSafeInteger(receipt.revision) || receipt.revision < message.expectedRevision ||
            receipt.contentHash !== message.contentHash) return false;
        const response = await figureBulkAwaitRead(chrome.runtime.sendMessage({ type: 'ARTICLE_WORKSPACE_GET_ASSET',
            workspaceId: target.workspaceId, workspaceGeneration: target.workspaceGeneration, target,
            relativePath: message.relativePath }), null, { timeoutMs: 15000 });
        const saved = response?.data?.asset;
        return current() && response?.success === true && saved?.revision === receipt.revision &&
            saved.contentHash === receipt.contentHash && stableSourceValue(saved.content) === entry.content;
    };
    const sourceWriteUnknown = cause => Object.assign(new Error('来源保存回执未确认，已保留任务；只读核验成功前不可重新开始。'), {
        code: 'WRITE_OUTCOME_UNKNOWN', reasonCode: 'SOURCE_WRITE_RECEIPT_UNCONFIRMED', retryable: false, cause });
    const trackSourceWrite = message => {
        const entry = { message, content: stableSourceValue(message.content), response: null, dispatched: false };
        sourceWrites.add(entry);
        if (/^figures\/supplemental\/[^/]+\.json$/.test(message.relativePath || '')) {
            return trackSourceWork(journal().save(message, entry).then(response => {
                sourceWrites.delete(entry);
                return response;
            }, error => {
                if (error?.sourceConflict === true) { sourceWrites.delete(entry); throw error; }
                throw sourceWriteUnknown(error);
            }));
        }
        return trackSourceWork(Promise.resolve().then(() => { assertCurrent(); entry.dispatched = true; return chrome.runtime.sendMessage(message); })
            .then(async response => {
                entry.response = response;
                // A timely structured result ends this write. The original
                // preflight still validates directory persistence and readback.
                if (!controller.signal.aborted && response && typeof response === 'object' &&
                    response.error?.code !== 'WRITE_OUTCOME_UNKNOWN' && response.code !== 'WRITE_OUTCOME_UNKNOWN') {
                    sourceWrites.delete(entry);
                    return response;
                }
                if (!await verifySourceWrite(entry)) throw sourceWriteUnknown();
                sourceWrites.delete(entry);
                return response;
            }).catch(error => {
                if (!entry.dispatched) { sourceWrites.delete(entry); throw error; }
                throw sourceWriteUnknown(error);
            }));
    };
    // This deadline covers the entire source phase, including importer cleanup
    // paths which may otherwise await a message forever. It never times a model.
    const sourceDeadline = setTimeout(() => {
        sourceFailure = Object.assign(new Error('来源准备超过 120 秒，已停止本轮补源；已保存结果保留。'), {
            code: 'FIGURE_SOURCE_TIMEOUT', reasonCode: 'SOURCE_PHASE_TIMEOUT', stage: 'figure_source_preparation', retryable: true });
        if (intent) intent.cancellationOrigin = 'source-timeout';
        controller.abort();
    }, 120000);
    const failSource = (reasonCode, message, bindingDiagnostics = null) => {
        sourceFailure = Object.assign(new Error(message + '；已保存结果保留，请刷新文献后重新解图。'), {
            code: 'FIGURE_SOURCE_CONTEXT_CHANGED', reasonCode, stage: 'figure_source_preparation', retryable: true, bindingDiagnostics });
        controller.abort();
        throw sourceFailure;
    };
    const assertCurrent = () => {
        if (controller.signal.aborted || isSidebarOperationStopping(operationId)) {
            controller.abort();
            throw Object.assign(new Error('来源准备已停止或论文页面已变化'), { code: 'CANCELLED' });
        }
        if (!isCurrentPanelContext(submittedContext) || !isCurrentFigureTask(taskToken, tab.id) ||
            intent && sidebarBatchIntents.get(sidebarBatchKey('figures', submittedContext)) !== intent) {
            failSource('SOURCE_OPERATION_CHANGED', '来源准备对应的页面或任务已变化');
        }
        if (target) {
            const current = supplementalFigureImportTools.buildTarget(currentWorkspaceSnapshot, tab.id);
            const changedFields = ['workspaceId', 'workspaceGeneration', 'canonicalUrl', 'documentHash', 'targetArticleTabId']
                .filter(key => current[key] !== target[key]);
            if (changedFields.length) failSource('SOURCE_TARGET_CHANGED', '来源准备的论文归属或版本已变化',
                { expected: { ...target }, actual: { ...current }, changedFields });
        }
    };
    const sourceIdentity = snapshot => ({ documentId: String(snapshot?.documentId || ''),
        documentHash: String(snapshot?.documentHash || ''),
        workspaceLifecycle: snapshot?.figures?.workspaceLifecycle ?? null,
        documentGeneration: snapshot?.documentGeneration ?? snapshot?.abbreviations?.documentGeneration ?? null });
    const originalSource = sourceIdentity(currentWorkspaceSnapshot);
    let originalTarget = null;
    const navigationIdentity = SciLLM.normalizeTabDocumentUrl(submittedContext.url);
    let originalWorld = null;
    let sourceReadRetries = 0;
    const probeSourceWorld = async ({ validate = true } = {}) => {
        assertCurrent();
        const probe = await figureBulkAwaitRead(sendTabMessage(tab.id, { action: 'getContentScriptRevision' }), controller.signal);
        assertCurrent();
        if (validate && (!probe?.documentIdentity || probe.navigationIdentity !== navigationIdentity))
            failSource('SOURCE_DOCUMENT_IDENTITY_CHANGED', '当前网页身份或地址无法确认', { actual: probe, navigationIdentity });
        return probe;
    };
    const assertRetrySource = async snapshot => {
        if (!originalWorld?.documentIdentity || originalWorld.navigationIdentity !== navigationIdentity ||
            !Number.isSafeInteger(originalSource.workspaceLifecycle) || originalSource.workspaceLifecycle < 0 ||
            !Number.isSafeInteger(originalSource.documentGeneration) || originalSource.documentGeneration < 0)
            failSource('SOURCE_DOCUMENT_IDENTITY_UNAVAILABLE', '本次操作的原网页身份尚未确认，无法安全重读');
        const probe = await probeSourceWorld();
        const actual = sourceIdentity(snapshot);
        const sidebar = sourceIdentity(currentWorkspaceSnapshot);
        const currentTarget = supplementalFigureImportTools.buildTarget(snapshot, tab.id);
        const changedFields = Object.keys(originalSource).filter(key => actual[key] !== originalSource[key]);
        for (const key of Object.keys(originalSource)) if (sidebar[key] !== originalSource[key]) changedFields.push('sidebar.' + key);
        for (const key of ['workspaceId', 'workspaceGeneration', 'canonicalUrl', 'documentHash', 'targetArticleTabId']) {
            if (currentTarget[key] !== originalTarget[key]) changedFields.push('target.' + key);
        }
        if (probe.documentIdentity !== originalWorld?.documentIdentity) changedFields.push('documentIdentity');
        if (!originalSource.documentId || !originalSource.documentHash || changedFields.length)
            failSource('SOURCE_RETRY_BINDING_CHANGED', '正文重读已超出本次操作的原文献版本', {
                expected: { ...originalSource, target: originalTarget, documentIdentity: originalWorld?.documentIdentity },
                actual: { ...actual, target: currentTarget, documentIdentity: probe.documentIdentity }, changedFields });
    };
    const readSourceSnapshot = async () => {
        for (;;) {
            try {
                assertCurrent();
                const snapshot = await figureBulkAwaitRead(refreshArticleWorkspace({ panelContext: submittedContext,
                    forceRefresh: true, throwOnError: true }), controller.signal);
                assertCurrent();
                if (!snapshot) throw Object.assign(new Error('来源快照未返回，请重新提取当前文献'), {
                    code: 'ARTICLE_WORKSPACE_READ_FAILED', reasonCode: 'SOURCE_SNAPSHOT_UNAVAILABLE', retryable: true });
                if (sourceReadRetries) await assertRetrySource(snapshot);
                return snapshot;
            } catch (error) {
                const canRetry = !sourceFailure && !controller.signal.aborted && sourceReadRetries === 0 &&
                    error?.code === 'ARTICLE_PAGE_LOADING' && error.retryable === true &&
                    ['ARTICLE_BROWSER_LOADING', 'ARTICLE_BODY_UNSTABLE', 'ARTICLE_SOURCE_CHANGED_DURING_READ'].includes(error.reasonCode);
                if (!canRetry) throw error;
                // A transient read may be retried once, only against the original
                // world, hash and lifecycle. Never adopt the returned new identity.
                await assertRetrySource(currentWorkspaceSnapshot);
                sourceReadRetries++;
            }
        }
    };
    const onHide = () => { if (intent) intent.cancellationOrigin = 'pagehide'; controller.abort(); };
    if (intent) intent.sourcePreparing = true;
    const monitor = setInterval(() => { try { assertCurrent(); } catch (_) { controller.abort(); } }, 150);
    window.addEventListener('pagehide', onHide, { once: true });
    try {
        assertCurrent();
        originalTarget = expectedTarget || supplementalFigureImportTools.buildTarget(currentWorkspaceSnapshot, tab.id);
        originalWorld = await probeSourceWorld({ validate: false });
        const initial = await readSourceSnapshot();
        assertCurrent();
        target = expectedTarget || supplementalFigureImportTools.buildTarget(initial, tab.id);
        assertCurrent();
        return await prepareFigureBulkSourcePreflight({ target, assertCurrent, signal: controller.signal,
            hasPendingSourceWork: () => pendingSourceWork.size > 0,
            sendMessage: message => {
                assertCurrent();
                return message.type === 'ARTICLE_WORKSPACE_SAVE_ASSET'
                    ? trackSourceWrite(message) : chrome.runtime.sendMessage(message);
            },
            readSnapshot: readSourceSnapshot,
            prepareTiffSource: figure => trackSourceWork((async () => {
                const resourceId = 'tiff-source-' + crypto.randomUUID();
                const cancel = () => { void SciLLM.sendTabMessageWithRecovery(chrome, tab.id, {
                    action: 'cancelArticleContentExport', operationId: resourceId
                }).catch(() => undefined); };
                controller.signal.addEventListener('abort', cancel, { once: true });
                try {
                    assertCurrent();
                    // Keep the actual source operation until its guarded reply settles.
                    const result = await SciLLM.sendTabMessageWithRecovery(chrome, tab.id, {
                        action: 'prepareFigureTiffSource', operationId: resourceId, target, figureId: figure.figureId
                    });
                    assertCurrent();
                    return result;
                } finally {
                    controller.signal.removeEventListener('abort', cancel);
                    if (controller.signal.aborted) cancel();
                }
            })()),
            importMaterial: (material, parent, file, options)=>trackSourceWork(openSupplementalMaterialPdf(material, parent, file, options))
        }, { allowImport: Array.isArray(recoveryMaterialIds), allowEmpty: true,
            deferSourceWork: !Array.isArray(recoveryMaterialIds), recoveryMaterialIds, expectedDeclaredSources });
    } catch (error) {
        // Preserve the new source failure instead of importing an older task's status.
        const failure = sourceFailure || error;
        if (['FIGURE_SOURCE_TIMEOUT', 'WRITE_OUTCOME_UNKNOWN'].includes(failure?.code)) {
            if (intent) intent.cancellationOrigin = 'source-timeout';
            controller.abort();
        }
        if (failure?.code === 'CANCELLED') {
            failure.stage ||= 'figure_source_preparation';
            failure.cancellationOrigin = intent?.cancellationOrigin || 'unknown';
        }
        if (failure?.code !== 'CANCELLED') {
            failure.code ||= 'FIGURE_SOURCE_READ_FAILED';
            failure.stage = 'figure_source_preparation';
            failure.reasonCode ||= 'SOURCE_PREPARATION_READ_FAILED';
            failure.retryable = failure.retryable === true;
            failure.bindingDiagnostics ||= { expected: { ...originalSource, target: originalTarget,
                documentIdentity: originalWorld?.documentIdentity }, sourceReadRetries };
            if (!/重新|重试/.test(failure.message || '')) failure.message += '；请等待页面稳定后重新提取文献，再重试图解，已保存结果保留。';
        }
        throw failure;
    } finally {
        clearTimeout(sourceDeadline);
        clearInterval(monitor);
        window.removeEventListener('pagehide', onHide);
        // A timed-out write/reader may still exist. Stop the spinner after 10s,
        // but retain ownership and reject another run until its actual cleanup
        // settles. A timeout is never proof of cancellation or persistence.
        if (controller.signal.aborted && (pendingSourceWork.size || sourceWrites.size)) {
            const settled = Promise.allSettled([...pendingSourceWork]);
            let cleanupExpired = false;
            try { await figureBulkAwaitRead(settled, null, { timeoutMs: 10000 }); }
            catch (_) { cleanupExpired = true; }
            if (cleanupExpired || sourceWrites.size) {
                if (intent) {
                    intent.sourceCleanupPending = true;
                    if (sourceWrites.size) intent.cleanupPendingReason = '来源保存回执未确认';
                    const release = () => {
                        if (sourceWrites.size || pendingSourceWork.size) return;
                        intent.sourceCleanupPending = false;
                        if (!intent.analysisDispatched) intent.stopRequested = false;
                        if (sidebarBatchIntents.get(sidebarBatchKey('figures', submittedContext)) === intent)
                            renderSidebarBatchActions();
                    };
                    intent.reconcileSourceWrites = async ({ explicitRecovery = false } = {}) => {
                        for (const entry of sourceWrites) {
                            try {
                                if (await (entry.journalSourceWrite ? journal().reconcile(entry, { explicitRecovery })
                                    : verifySourceWrite(entry, { allowRefusal: true }))) sourceWrites.delete(entry);
                            } catch (_) {}
                        }
                        release();
                    };
                    settled.then(release);
                }
            }
        }
        if (intent) intent.sourcePreparing = false;
    }
}

async function waitForFigureSourceResume(intent) {
    if (!intent?.sourcePaused) return;
    const controller = intent.sourceController;
    const check = () => {
        if (intent.stopRequested || !isCurrentPanelContext(intent.context) ||
            sidebarBatchIntents.get(sidebarBatchKey('figures', intent.context)) !== intent) controller?.abort();
    };
    const onHide = () => controller?.abort();
    const monitor = setInterval(check, 150);
    window.addEventListener('pagehide', onHide, { once: true });
    try {
        check();
        while (intent.sourcePaused) {
            await figureBulkAwaitRead(new Promise(resolve => { intent.sourceResume = resolve; }), controller?.signal, { timeoutMs: 0 });
            check();
        }
    } finally {
        delete intent.sourceResume;
        clearInterval(monitor);
        window.removeEventListener('pagehide', onHide);
    }
}

async function captureFigureUiOwnerBinding() {
    const unavailable = () => Object.assign(new Error('图解界面归属已变化，请重新打开侧栏后继续。'), {
        code: 'CANCELLED', reasonCode: 'UI_OWNER_CONTEXT_UNAVAILABLE', stage: 'figure_runtime_binding' });
    const documentUrl = chrome.runtime.getURL('popup.html');
    let hidden = false;
    const onHide = () => { hidden = true; };
    window.addEventListener('pagehide', onHide, { once: true });
    try {
        const contexts = await chrome.runtime.getContexts({ documentUrls: [documentUrl] });
        if (hidden || !Array.isArray(contexts)) throw unavailable();
        const sameUrl = contexts.filter(context => context.documentUrl === documentUrl);
        if (sameUrl.length !== 1) throw unavailable();
        const context = sameUrl[0];
        // A real extension TAB has a browser-supplied sender.documentId. The
        // missing-documentId compatibility branch is exclusively SIDE_PANEL.
        if (context.contextType === 'TAB') return null;
        const parsed = new URL(documentUrl), expectedOrigin = parsed.protocol + '//' + parsed.host;
        if (context.contextType !== 'SIDE_PANEL' || typeof context.contextId !== 'string' || !context.contextId ||
            typeof context.documentId !== 'string' || !context.documentId || context.frameId !== 0 ||
            !Number.isSafeInteger(context.tabId) || context.tabId < -1 ||
            !Number.isSafeInteger(context.windowId) || context.windowId < -1 || typeof context.incognito !== 'boolean' ||
            context.documentOrigin && context.documentOrigin !== expectedOrigin) throw unavailable();
        return Object.freeze(Object.fromEntries(['contextId', 'contextType', 'documentId', 'documentUrl',
            'tabId', 'frameId', 'windowId', 'incognito'].map(key => [key, context[key]])));
    } catch (_) {
        throw unavailable();
    } finally {
        window.removeEventListener('pagehide', onHide);
    }
}

let figureInputModeDialogPromise = null;
function requestFigureInputModeChoice({ allFigures = false, figureLabel = '' } = {}) {
    if (figureInputModeDialogPromise) return figureInputModeDialogPromise;
    figureInputModeDialogPromise = new Promise(resolve => {
        let settled = false;
        const dialog = createWorkspaceElement('dialog', 'workspace-figure-input-dialog');
        dialog.setAttribute('aria-labelledby', 'figureInputModeTitle');
        const title = createWorkspaceElement('h3', '', '选择本次解图依据');
        title.id = 'figureInputModeTitle';
        const description = createWorkspaceElement('p', '',
            `${allFigures ? '本次批量解图' : (figureLabel || '该 Figure')}将使用哪种证据？` +
            '使用 Figure 图像可以读取图像细节；仅文本模式只使用图注与正文。');
        const actions = createWorkspaceElement('div', 'workspace-figure-input-actions');
        const imageButton = createWorkspaceElement('button', 'btn btn-primary', '使用 Figure 图像');
        const textButton = createWorkspaceElement('button', 'btn btn-secondary', '仅用图注与正文');
        const cancelButton = createWorkspaceElement('button', 'btn btn-ghost', '取消');
        [imageButton, textButton, cancelButton].forEach(button => { button.type = 'button'; });
        imageButton.dataset.figureInputMode = 'vision';
        textButton.dataset.figureInputMode = 'text';
        const finish = value => {
            if (settled) return;
            settled = true;
            try { dialog.close(); } catch (_) {}
            dialog.remove();
            figureInputModeDialogPromise = null;
            resolve(value);
        };
        imageButton.addEventListener('click', () => finish('vision'));
        textButton.addEventListener('click', () => finish('text'));
        cancelButton.addEventListener('click', () => finish(null));
        dialog.addEventListener('cancel', event => { event.preventDefault(); finish(null); });
        dialog.addEventListener('close', () => { if (!settled) finish(null); });
        actions.append(imageButton, textButton, cancelButton);
        dialog.append(title, description, actions);
        document.body.appendChild(dialog);
        try { dialog.showModal(); } catch (_) { finish('vision'); return; }
        requestAnimationFrame(() => imageButton.focus());
    });
    return figureInputModeDialogPromise;
}

async function runFigureAnalysis({ allFigures = false, operationId = '', trustedUserGesture = false,
    figureExecutionWindow, figureInputMode = '' } = {}) {
    // The actual Figure route validates local reuse; physical dispatch admits consent.
    const startedAt = Date.now();
    const selectedFigureIds = allFigures ? [] : [...figureSelectedIds];
    const selectedDocumentHash = String(currentWorkspaceSnapshot?.documentHash || '');
    const submittedContext = capturePanelContext();
    const outerIntent = sidebarBatchIntents.get(sidebarBatchKey('figures', submittedContext));
    let figureUiOwnerBinding = null;
    let uiOwnerHidden = false;
    const onUiOwnerHide = () => { uiOwnerHidden = true; outerIntent?.sourceController?.abort(); };
    window.addEventListener('pagehide', onUiOwnerHide, { once: true });
    let tab = null;
    let taskToken = null;
    let initializationRecoveryFailed = false;
    const recoverInitializationWorkspace = async () => {
        if (!trustedUserGesture || !outerIntent) return;
        const initialization = typeof articleInitializationState === 'undefined' ? null : articleInitializationState;
        if (!initialization?.error || initialization.ready || !isCurrentPanelContext(initialization.context) ||
            !['ARTICLE_PREPARATION_TIMEOUT', 'ARTICLE_WORKSPACE_READ_FAILED', 'ARTICLE_PAGE_LOADING']
                .includes(initialization.error.code)) return;
        try { supplementalFigureImportTools.buildTarget(currentWorkspaceSnapshot, tab.id); return; }
        catch (error) { if (error?.code !== 'SUPPLEMENTAL_TARGET_INVALID') throw error; }
        const baseline = currentWorkspaceSnapshot;
        const document = baseline || preparedDocumentState;
        const identity = snapshot => JSON.stringify([snapshot?.documentId, snapshot?.documentHash,
            snapshot?.url, snapshot?.documentGeneration, snapshot?.localWorkspace]);
        const baselineIdentity = identity(baseline);
        const controller = new AbortController();
        const abort = () => controller.abort();
        const ownsIntent = () => !controller.signal.aborted && !outerIntent.sourceController.signal.aborted &&
            !isSidebarOperationStopping(operationId) && isCurrentPanelContext(submittedContext) &&
            isCurrentFigureTask(taskToken, tab.id) && articleInitializationState === initialization &&
            sidebarBatchIntents.get(sidebarBatchKey('figures', submittedContext)) === outerIntent;
        const acceptsSnapshot = snapshot => !snapshot ||
            (!document?.documentId || snapshot.documentId === document.documentId) &&
            (!document?.documentHash || snapshot.documentHash === document.documentHash) &&
            SciLLM.normalizeTabDocumentUrl(snapshot.url) === SciLLM.normalizeTabDocumentUrl(submittedContext.url);
        const isCurrentOwner = snapshot => ownsIntent() && currentWorkspaceSnapshot === baseline &&
            identity(currentWorkspaceSnapshot) === baselineIdentity && acceptsSnapshot(snapshot);
        const cancelled = () => Object.assign(new Error('正文准备已停止或当前论文已变化，已保存结果保留'), {
            code: 'CANCELLED', stage: 'figure_source_preparation' });
        outerIntent.sourceController.signal.addEventListener('abort', abort, { once: true });
        try {
            if (!isCurrentOwner()) throw cancelled();
            showStatus('正在重新准备当前论文的本地正文，完成后继续图解…', 'success');
            // One local retry only. Do not restart the initializer: its restore
            // and progress side effects do not belong to this Figure intent.
            const snapshot = await withPreparationDeadline(refreshArticleWorkspace({
                panelContext: submittedContext, forceRefresh: true, throwOnError: true,
                signal: controller.signal, isCurrentOwner
            }), 15000, error => controller.abort(error));
            if (!ownsIntent() || snapshot && currentWorkspaceSnapshot !== snapshot || !acceptsSnapshot(snapshot)) throw cancelled();
            if (!snapshot) throw Object.assign(new Error('本地正文准备未完成，请重新提取后重试图解，已保存结果保留'), {
                code: 'ARTICLE_WORKSPACE_READ_FAILED' });
            supplementalFigureImportTools.buildTarget(snapshot, tab.id);
        } catch (error) {
            initializationRecoveryFailed = true;
            error.stage ||= 'figure_source_preparation';
            throw error;
        } finally {
            controller.abort();
            outerIntent.sourceController.signal.removeEventListener('abort', abort);
        }
    };
    try {
        tab = await queryPanelTargetTab();
        if (!tab?.id) throw new Error('无法获取当前论文页面');
        if (!isCurrentPanelContext(submittedContext)) return;
        taskToken = figureTaskGeneration;
        if (!isCurrentFigureTask(taskToken, tab.id)) return;
        if (uiOwnerHidden) throw Object.assign(new Error('图解界面已关闭'), { code: 'CANCELLED' });
        if (typeof chrome.runtime.getContexts === 'function') figureUiOwnerBinding = await captureFigureUiOwnerBinding();
        if (uiOwnerHidden || !isCurrentPanelContext(submittedContext) || !isCurrentFigureTask(taskToken, tab.id))
            throw Object.assign(new Error('图解界面归属已变化'), { code: 'CANCELLED' });
        if (outerIntent) outerIntent.figureUiOwnerBinding = figureUiOwnerBinding;
        if (isSidebarOperationStopping(operationId)) return { cancelled: true, notStarted: true };
        const selectedFigureInputMode = figureInputMode ||
            await requestFigureInputModeChoice({ allFigures });
        if (!selectedFigureInputMode) return { cancelled: true, notStarted: true };
        figureAnalysisState = {
            running: true,
            paused: false,
            phase: 'extracting',
            currentFigure: 0,
            totalFigures: 0,
            completedFigures: 0,
            failedFigures: 0,
            figureLabel: '',
            message: '正在读取论文中的 Figure…'
        };
        updateFigureButton();
        showStatus('正在读取论文中的 Figure…', 'success');
        let figureSourcePreflight = null;
        if (allFigures) {
            if (outerIntent) outerIntent.sourcePhasePending = true;
            await recoverInitializationWorkspace();
            figureAnalysisState = { ...figureAnalysisState, phase: 'source_preparation', message: '正在核验已发现 Figure 的来源…' };
            showStatus(figureAnalysisState.message, 'success');
            figureSourcePreflight = await prepareFigureAnalysisDeclaredSources({ operationId, submittedContext, taskToken, tab });
            figureAnalysisState = { ...figureAnalysisState, totalFigures: figureSourcePreflight.inventoryFigureIds.length };
            const sourceSummary = SciLLM.formatFigureBulkSourceSummary(figureSourcePreflight);
            if (sourceSummary) showStatus('先解读可用图；' + sourceSummary, 'warning');
        }
        if (!isCurrentPanelContext(submittedContext) || !isCurrentFigureTask(taskToken, tab.id) ||
            isSidebarOperationStopping(operationId)) return { cancelled: true, notStarted: true };
        const outerOperationId = operationId;
        const expectedTarget = figureSourcePreflight?.target;
        const expectedDeclaredSources = figureSourcePreflight?.declaredSources;
        const attemptedIds = new Set(), phaseResponses = [];
        let response = null;
        let recoveryMaterialIds = [];
        let admittedBinding = null;
        for (let sourcePhase = 0; sourcePhase < (allFigures ? 2 : 1); sourcePhase++) {
            if (sourcePhase === 1) {
                const missingKeys = new Set((figureSourcePreflight.missingFigureLabels || []).map(SciLLM.supplementalFigureKey));
                recoveryMaterialIds = [...new Set((figureSourcePreflight.sourceIssues || [])
                    .filter(issue => issue.retryable !== false && ((issue.affectedFigureIds || []).length ||
                        (issue.declaredFigureLabels || []).some(label => missingKeys.has(SciLLM.supplementalFigureKey(label)))))
                    .map(issue => issue.materialId))];
                if (!recoveryMaterialIds.length) break;
                if (response?.paused || response?.runtimeTask?.status === 'paused' || figureAnalysisState.paused) break;
                stopFigureProgressPolling();
                figureAnalysisState = { ...figureAnalysisState, running: true, phase: 'source_preparation',
                    message: '正在补齐未完成 Figure 的附件来源，已有结果保留…' };
                showStatus(figureAnalysisState.message, 'success');
                // The first page operation has settled. Retain the outer intent,
                // but do not send its terminal task a stop intended for source I/O.
                if (outerIntent) { outerIntent.task = null; outerIntent.analysisDispatched = false; outerIntent.sourcePhasePending = true; }
                figureSourcePreflight = await prepareFigureAnalysisDeclaredSources({ operationId, submittedContext, taskToken, tab,
                    recoveryMaterialIds, expectedTarget, expectedDeclaredSources });
            }
            await waitForFigureSourceResume(outerIntent);
            if (!isCurrentPanelContext(submittedContext) || !isCurrentFigureTask(taskToken, tab.id) ||
                isSidebarOperationStopping(operationId) || outerIntent?.sourceController?.signal.aborted ||
                outerIntent && sidebarBatchIntents.get(sidebarBatchKey('figures', submittedContext)) !== outerIntent)
                throw Object.assign(new Error('图解已取消，已完成结果会保留'), { code: 'CANCELLED' });
            const inventory = currentWorkspaceSnapshot?.figures?.figures || [];
            let figureIds = allFigures ? figureSourcePreflight.figureIds.filter(id => !attemptedIds.has(id))
                : selectedFigureIds.length ? selectedFigureIds : inventory.map(figure => figure.figureId);
            if (sourcePhase === 1) figureIds = figureIds.filter(id => {
                const figure = inventory.find(row => row.figureId === id);
                return SciLLM.figureBulkSourceDependencyIds(figure, figureSourcePreflight.declaredSources || [])
                    .some(materialId => recoveryMaterialIds.includes(materialId));
            });
            if (!figureIds.length) continue;
            if (sourcePhase === 1 && phaseResponses.length) {
                // Resume intents are immutable per backend operation ID. A new
                // exact scope requires a new ID, still within this one button run.
                operationId = 'figure-' + crypto.randomUUID();
                if (outerIntent) { outerIntent.parentOperationId = outerOperationId; outerIntent.operationId = operationId; }
            }
            let figureUserResumeIntent = '', figureUserResumeBinding = null;
            if (trustedUserGesture) {
                const binding = await refreshSidebarRuntimeDocumentBinding(submittedContext, {
                    figureBinding: true, retryLoading: allFigures, signal: outerIntent?.sourceController?.signal,
                    assertCurrent: () => {
                        if (!isCurrentPanelContext(submittedContext) || !isCurrentFigureTask(taskToken, tab.id) ||
                            isSidebarOperationStopping(operationId) || outerIntent?.sourceController?.signal.aborted ||
                            outerIntent && sidebarBatchIntents.get(sidebarBatchKey('figures', submittedContext)) !== outerIntent)
                            throw Object.assign(new Error('图解已取消，已完成结果会保留'), { code: 'CANCELLED' });
                    }
                });
                await waitForFigureSourceResume(outerIntent);
                if (!binding) throw Object.assign(new Error('文献绑定不可用，请刷新文献后重新解图'), {
                    code: 'FIGURE_DOCUMENT_BINDING_STALE', reasonCode: 'BINDING_UNAVAILABLE', stage: 'figure_runtime_binding', retryable: true });
                if (!isCurrentFigureTask(taskToken, tab.id) || isSidebarOperationStopping(operationId) ||
                    outerIntent?.sourceController?.signal.aborted)
                    throw Object.assign(new Error('本次继续范围已失效'), { code: 'CANCELLED' });
                if (admittedBinding && ['documentIdentity', 'documentHash', 'workspaceLifecycle'].some(key => binding[key] !== admittedBinding[key]))
                    throw Object.assign(new Error('本次继续的论文身份已变化'), { code: 'FIGURE_SELECTION_STALE' });
                admittedBinding = binding;
                figureUserResumeBinding = { tabId: tab.id, documentIdentity: binding.documentIdentity,
                    navigationIdentity: SciLLM.normalizeTabDocumentUrl(submittedContext.url),
                    documentHash: binding.documentHash, workspaceLifecycle: binding.workspaceLifecycle, figureIds };
                const authorization = await chrome.runtime.sendMessage({ type: 'LLM_CONTROL_OPERATION',
                    operationScope: 'figure', command: 'authorize-user-resume', operationId, figureUserResumeBinding,
                    ...(figureUiOwnerBinding ? { figureUiOwnerBinding } : {}) });
                if (!authorization?.success) throw Object.assign(new Error(authorization?.error?.message || '无法确认本次继续范围'),
                    { code: authorization?.error?.code });
                figureUserResumeIntent = authorization.data?.figureUserResumeIntent || '';
            }
            await waitForFigureSourceResume(outerIntent);
            if (!isCurrentPanelContext(submittedContext) || !isCurrentFigureTask(taskToken, tab.id) ||
                isSidebarOperationStopping(operationId) || outerIntent?.sourceController?.signal.aborted)
                throw Object.assign(new Error('图解已取消，已完成结果会保留'), { code: 'CANCELLED' });
            if (outerIntent) { outerIntent.analysisDispatched = true; outerIntent.sourcePhasePending = false; }
            startFigureProgressPolling(tab.id);
            response = await sendTabMessage(tab.id, {
                action: 'analyzeFiguresWithLLM',
                ...(allFigures ? { allFigures: true, figureSourcePreflight: { ...figureSourcePreflight, figureIds },
                    figureIds, documentHash: String(currentWorkspaceSnapshot?.documentHash || selectedDocumentHash) } : {}),
                ...(figureUserResumeIntent ? { figureUserResumeIntent, figureUserResumeBinding } : {}),
                ...(figureExecutionWindow !== undefined ? { figureExecutionWindow } : {}),
                operationId,
                ...(selectedFigureIds.length ? { figureIds: selectedFigureIds, documentHash: selectedDocumentHash } : {}),
                analysisDepth: 'standard',
                figureInputMode: selectedFigureInputMode
            });
            if (!isCurrentFigureTask(taskToken, tab.id)) return;
            acceptSidebarRuntimeTask(response?.runtimeTask, submittedContext, 'figures');
            if (response?.cancelled || response?.code === 'CANCELLED')
                throw Object.assign(new Error('图解已取消，已完成结果会保留'), { code: 'CANCELLED' });
            if (!response?.success) throw Object.assign(new Error(response?.error || '逐图解读失败'), { code: response?.code });
            figureIds.forEach(id => attemptedIds.add(id));
            phaseResponses.push({ ...response, phaseFigureIds: figureIds });
            if (outerIntent) outerIntent.hasCompletedFigurePhase = true;
            figureAnalysisState = { ...figureAnalysisState,
                completedFigures: phaseResponses.reduce((count, phase) => count + (Number(phase.analyzedCount) || 0), 0),
                failedFigures: phaseResponses.reduce((count, phase) => count + (Number(phase.failedCount) || 0), 0) };
            if (allFigures && response.sourcePlan) figureSourcePreflight = { ...figureSourcePreflight, ...response.sourcePlan };
            if (response.paused || response.runtimeTask?.status === 'paused') {
                figureAnalysisState = { ...figureAnalysisState, running: false, paused: true, phase: 'paused' };
                return response;
            }
        }
        if (!phaseResponses.length) {
            const error = figureBulkSourceError(SciLLM.formatFigureBulkSourceSummary(figureSourcePreflight) || '没有已取得来源证明的可解读 Figure。');
            error.sourcePlan = figureSourcePreflight; throw error;
        }
        const sum = key => phaseResponses.reduce((total, phase) => total + (Number(phase[key]) || 0), 0);
        response = { ...response, analyzedCount: sum('analyzedCount'), failedCount: sum('failedCount'),
            totalCount: figureExecutionWindow !== undefined ? response.totalCount
                : allFigures ? Math.max(attemptedIds.size, figureSourcePreflight.inventoryFigureIds.length) : response.totalCount,
            cacheHits: sum('cacheHits'), visionFallbacks: sum('visionFallbacks'),
            sourcePlan: figureSourcePreflight,
            sourceIncomplete: (figureSourcePreflight?.figureScopeComplete ?? figureSourcePreflight?.complete) === false,
            attachmentCatalogIncomplete: figureSourcePreflight?.complete === false,
            partial: sum('failedCount') > 0 || (figureSourcePreflight?.figureScopeComplete ?? figureSourcePreflight?.complete) === false,
            phaseUsage: phaseResponses.map(phase => phase.usage).filter(Boolean) };
        if (response.phaseUsage.length && SciLLM.mergeTaskTelemetry) {
            response.usage = SciLLM.mergeTaskTelemetry(response.phaseUsage, {
                label: '逐图解读', operationId: outerOperationId, startedAt, finishedAt: Date.now(),
                status: response.partial ? 'failed' : 'success'
            });
            response.usage.taskSummaryText = SciLLM.formatTaskTelemetry(response.usage);
        }
        const failedCount = Number(response.failedCount) || 0;
        const analyzedCount = Number(response.analyzedCount) || 0;
        const totalCount = Number(response.totalCount) || analyzedCount + failedCount;
        const sourceIncomplete = response.sourceIncomplete === true ||
            (figureSourcePreflight?.figureScopeComplete ?? figureSourcePreflight?.complete) === false;
        const attachmentCatalogIncomplete = response.attachmentCatalogIncomplete === true;
        const sourcePlan = response.sourcePlan || figureSourcePreflight || {};
        const sourceSummary = sourceIncomplete ? SciLLM.formatFigureBulkSourceSummary(sourcePlan) : '';
        const partial = failedCount > 0 || response.partial === true || sourceIncomplete;
        const details = [];
        if (response.executionWindowSummary) details.push('本次窗口；全计划 ' + response.executionWindowSummary.totalPlanFigures + ' 张');
        if (sourceSummary) details.push('来源未完成：' + sourceSummary);
        if (response.cacheHits) details.push(response.cacheHits + ' 张来自缓存');
        if (response.visionFallbacks) {
            details.push(response.visionFallbacks + ' 张仅使用图注与正文');
        }
        if (partial) {
            showStatus(formatEffectiveRoute(
                `逐图解读完成 ${analyzedCount}/${totalCount} 张，${failedCount} 张失败；` +
                '成功结果已保留，重试时会复用缓存' +
                (details.length ? '（' + details.join('，') + '）' : ''),
                response.route
            ),
                'error',
                response.usage
            );
        } else {
            showStatus(formatEffectiveRoute(
                '逐图解读完成：' + analyzedCount + ' 张 Figure' +
                (details.length ? '（' + details.join('，') + '）' : ''),
                response.route
            ),
                'success',
                response.usage
            );
        }
        figureAnalysisState = {
            ...figureAnalysisState,
            running: false,
            phase: partial ? 'partial' : 'completed',
            currentFigure: totalCount,
            totalFigures: totalCount,
            completedFigures: analyzedCount,
            failedFigures: failedCount,
            sourceIncomplete, attachmentCatalogIncomplete, sourcePlan,
            message: partial
                ? `完成 ${analyzedCount}/${totalCount} 张，${failedCount} 张分析失败${sourceSummary ? '；' + sourceSummary : ''}`
                : `完成 ${analyzedCount}/${totalCount} 张`
        };
        // Batch Figure analysis ends here. 图表梳理 is an explicit separate task.
        return response;
    } catch (error) {
        if (!isCurrentFigureTask(taskToken, tab?.id) || initializationRecoveryFailed &&
            (!isCurrentPanelContext(submittedContext) ||
                sidebarBatchIntents.get(sidebarBatchKey('figures', submittedContext)) !== outerIntent)) return;
        if (error?.code === 'WRITE_OUTCOME_UNKNOWN' && outerIntent?.analysisDispatched && !outerIntent.sourceCleanupPending) {
            outerIntent.sourceCleanupPending = true;
            outerIntent.cleanupPendingReason = '来源保存结果待核验；双击核验/恢复来源';
            outerIntent.reconcileSourceWrites = async ({ explicitRecovery = false } = {}) => {
                if (!isCurrentPanelContext(submittedContext) || sidebarBatchIntents.get(sidebarBatchKey('figures', submittedContext)) !== outerIntent) return;
                const target = supplementalFigureImportTools.buildTarget(currentWorkspaceSnapshot, tab.id);
                const query = request => figureBulkAwaitRead(sendTabMessage(tab.id, { action: 'recoverFigureSourceWrites',
                    target, operationId, ...request }), null, { timeoutMs: 30000 });
                let result = await query({ explicitRecovery: false });
                if (explicitRecovery && result?.success === true && result.pending === true &&
                    result.operationId === operationId && Number.isSafeInteger(result.operationGeneration)) {
                    result = await query({ explicitRecovery: true, operationGeneration: result.operationGeneration });
                }
                if (isCurrentPanelContext(submittedContext) && result?.success === true && result.recovered === true &&
                    result.pending === false && result.operationId === operationId) {
                    outerIntent.sourceCleanupPending = false;
                    outerIntent.stopRequested = false;
                }
            };
        }
        if (error?.code === 'FIGURE_SOURCE_PREPARATION_REQUIRED') {
            figureAnalysisState = { ...figureAnalysisState, running: false, phase: 'source_preparation', message: error.message };
            showStatus(error.message, 'warning');
            return { notStarted: true, sourcePreparationRequired: true };
        }
        if (error?.code === 'CANCELLED' && !sidebarBatchIntents.get(sidebarBatchKey('figures', submittedContext))?.analysisDispatched) {
            const stage = error.stage || (outerIntent?.sourcePreparing ? 'figure_source_preparation' : 'figure_runtime_binding');
            const cancellationOrigin = error.cancellationOrigin || outerIntent?.cancellationOrigin || 'unknown';
            const message = (stage === 'figure_source_preparation' ? '来源准备已停止' : '图解启动已停止') +
                (cancellationOrigin === 'unknown' ? '（停止来源未确认）' : '') + '，已保存结果保留。';
            showStatus(message, 'warning');
            figureAnalysisState = { ...figureAnalysisState, running: false, phase: 'cancelled', errorStage: stage, cancellationOrigin, message };
            return { cancelled: true, stage, cancellationOrigin, sourcePreparationStopped: outerIntent?.sourceController?.signal.aborted === true &&
                outerIntent?.sourcePreparing !== true && outerIntent?.analysisDispatched !== true,
                notStarted: !sidebarBatchIntents.get(sidebarBatchKey('figures', submittedContext))?.hasCompletedFigurePhase };
        }
        if (['figure_runtime_binding', 'figure_source_preparation'].includes(error?.stage)) figureAnalysisState = { ...figureAnalysisState,
            running: false, phase: 'failed', errorCode: error.code, errorStage: error.stage,
            reasonCode: error.reasonCode || '', bindingDiagnostics: error.bindingDiagnostics || null,
            retryable: error.retryable === true, message: error.message };
        const progress = ['figure_runtime_binding', 'figure_source_preparation'].includes(error?.stage)
            ? figureAnalysisState
            : tab?.id ? await refreshFigureAnalysisProgress(tab.id, false) : figureAnalysisState;
        const progressText = progress?.totalFigures
            ? `（已完成 ${progress.completedFigures || 0}/${progress.totalFigures} 张` +
                (progress.failedFigures ? `，失败 ${progress.failedFigures} 张` : '') + '）'
            : '';
        if (error?.code === 'CANCELLED' || figureAnalysisState.phase === 'cancelled') {
            showStatus('Figure 解读已取消，已完成结果会保留' + progressText, 'success');
        } else {
            showStatus('逐图解读失败' + progressText + '：' + error.message, 'error');
        }
        if (['figure_runtime_binding', 'figure_source_preparation'].includes(error?.stage)) return { success: false, notStarted: !outerIntent?.hasCompletedFigurePhase,
            code: error.code, reasonCode: error.reasonCode || '', retryable: error.retryable === true,
            stage: error.stage, bindingDiagnostics: error.bindingDiagnostics || null };
    } finally {
        window.removeEventListener('pagehide', onUiOwnerHide);
        if (outerIntent) { outerIntent.sourcePhasePending = false; outerIntent.sourcePaused = false; }
        if (!isCurrentFigureTask(taskToken, tab?.id) || initializationRecoveryFailed &&
            (!isCurrentPanelContext(submittedContext) ||
                sidebarBatchIntents.get(sidebarBatchKey('figures', submittedContext)) !== outerIntent)) return;
        stopFigureProgressPolling({ preserveTerminationObservation: true });
        figureAnalysisState = { ...figureAnalysisState, running: false };
        void observeStoppedFigureNativeRequest(tab.id, taskToken, figureAnalysisState.operationId);
        updateFigureButton();
        // A mechanism result or the reader may have changed views while the
        // batch was running. Completion refreshes data without taking focus.
        // A binding failure happened before this operation reached the backend.
        // Catalog refresh may carry the previous task's progress; keep this failure.
        const bindingFailureState = ['figure_runtime_binding', 'figure_source_preparation'].includes(figureAnalysisState.errorStage)
            ? { ...figureAnalysisState } : null;
        if (!outerIntent?.sourceCleanupPending && !initializationRecoveryFailed) {
            let expired = false;
            let archiveStarted = false;
            let recovered = false;
            const finalizationReceipt = {};
            const ownsFinalization = () => isCurrentFigureTask(taskToken, tab?.id) && isCurrentPanelContext(submittedContext) &&
                sidebarBatchIntents.get(sidebarBatchKey('figures', submittedContext)) === outerIntent;
            const finishFinalization = error => {
                if (!outerIntent || recovered || !ownsFinalization()) return;
                const unknown = error && archiveStarted && finalizationReceipt.writeDispatched !== false &&
                    error.archiveWriteNotStarted !== true;
                if (unknown) {
                    outerIntent.sourceCleanupPending = true;
                    outerIntent.cleanupPendingReason = '归档写入回执丢失，需核验后恢复';
                    renderSidebarBatchActions();
                    return;
                }
                recovered = true;
                outerIntent.sourceCleanupPending = false;
                if (error) outerIntent.finalizationFailure = String(error.message || error);
                else delete outerIntent.finalizationFailure;
                outerIntent.cleanupRecoveryMessage = '图解归档保存回执已核验；请再次双击继续未完成图解。';
                if (expired || error) showStatus(error ? '图解归档收尾失败：' + outerIntent.finalizationFailure + '；已保存图解保留。'
                    : '图解收尾已完成，归档保存回执已核验。', error ? 'warning' : 'success');
                renderSidebarBatchActions();
            };
            const reconcileFinalization = async () => {
                if (recovered || !ownsFinalization() || !finalizationReceipt.archive) return;
                const expected = finalizationReceipt.archive;
                try {
                    const result = await figureBulkAwaitRead(sendLlmMessage({ type: 'ARTICLE_ARCHIVE_LOAD',
                        documentId: expected.documentId, canonicalUrl: expected.canonicalUrl }), null);
                    if (!ownsFinalization() || recovered) return;
                    const stable = value => JSON.stringify(value, (_key, item) => item && typeof item === 'object' && !Array.isArray(item)
                        ? Object.fromEntries(Object.keys(item).sort().map(key => [key, item[key]])) : item);
                    if (stable(SciLLM.validateArticleArchive(result?.archive)) === stable(expected)) finishFinalization();
                } catch (_) { /* Missing or unreadable archives cannot prove a write did not occur. */ }
            };
            const finalization = (async () => {
                await refreshArticleWorkspace();
                if (!isCurrentFigureTask(taskToken, tab?.id) || outerIntent && !ownsFinalization()) return;
                if (bindingFailureState) {
                    figureAnalysisState = bindingFailureState;
                    updateFigureButton();
                    renderFigureWorkspaceSnapshot(currentWorkspaceSnapshot);
                }
                archiveStarted = true;
                const result = await persistCurrentArticleArchive({ panelContext: submittedContext, finalizationReceipt,
                    canSave: () => isCurrentFigureTask(taskToken, tab?.id) && (!outerIntent || ownsFinalization()) });
                if (result?.saved?.saved !== true) throw Object.assign(new Error(finalizationReceipt.writeDispatched === false
                    ? '归档尚未保存：未取得当前论文档案。' : '归档保存回执未确认。'), {
                    archiveWriteNotStarted: finalizationReceipt.writeDispatched === false });
            })();
            try { await figureBulkAwaitRead(finalization, null, { mutation: true }); }
            catch (error) {
                if (!isCurrentFigureTask(taskToken, tab?.id) || !isCurrentPanelContext(submittedContext) ||
                    outerIntent && !ownsFinalization()) return;
                expired = true;
                if (error?.code === 'FIGURE_SOURCE_TIMEOUT' && outerIntent) {
                    outerIntent.sourceCleanupPending = true;
                    outerIntent.cleanupPendingReason = '刷新或归档保存回执未确认';
                    outerIntent.reconcileSourceWrites = reconcileFinalization;
                    finalization.then(() => finishFinalization(), finishFinalization);
                } else {
                    finishFinalization(error);
                    if (outerIntent?.sourceCleanupPending) outerIntent.reconcileSourceWrites = reconcileFinalization;
                }
                if (!outerIntent?.finalizationFailure)
                    showStatus('图解收尾未确认：' + error.message + '；已保存结果保留，请核对后继续。', 'warning');
            }
        }
    }
}

function currentFigureOriginalPdfRequest(figureId) {
    const id = String(figureId || '');
    const figures = Array.isArray(currentWorkspaceSnapshot?.figures?.figures)
        ? currentWorkspaceSnapshot.figures.figures : [];
    const figure = figures.find(item => String(item?.figureId || '') === id);
    if (figure?.sourceKind !== 'pdf-page-caption') return {};
    const request = {
        documentHash: String(figure.documentHash || ''),
        documentGeneration: Number(figure.pdfDocumentGeneration) || 0
    };
    const result = figure.activeDepth === 'standard'
        ? (figure.standard || figure.deep) : (figure.deep || figure.standard);
    const panelPageMap = result?.pdfPanelInventory?.panelPageMap;
    const resultBinding = result?.pdfEvidenceBinding;
    const artworkPages = Array.isArray(figure.artworkPageNumbers)
        ? figure.artworkPageNumbers : [];
    if (!panelPageMap || !artworkPages.length ||
        result?.pdfPanelInventory?.version !== 'pdf-figure-panel-inventory-v3' ||
        result.pdfPanelInventory?.provenance?.figureId !== id ||
        result.pdfPanelInventory?.provenance?.visualEvidenceSetDigest !==
            resultBinding?.visualEvidenceSet?.setDigest ||
        resultBinding?.figureId !== id ||
        resultBinding?.binding?.documentHash !== request.documentHash ||
        resultBinding?.binding?.documentGeneration !== request.documentGeneration) return request;
    const prefix = `${id}::`;
    const renderedActivePanels = Array.from(document.querySelectorAll(
        '.workspace-figure-panel-card[data-figure-id][data-panel-id]'
    )).filter(item => item.dataset.figureId === id && item.open === true);
    const renderedPanelId = String(
        renderedActivePanels[renderedActivePanels.length - 1]?.dataset?.panelId || ''
    ).toUpperCase();
    const storedPanelId = [...figurePanelExpansionState.entries()]
        .find(([key, open]) => open === true && key.startsWith(prefix))?.[0]
        ?.slice(prefix.length).toUpperCase() || '';
    const panelId = renderedPanelId || storedPanelId;
    const sourcePage = panelPageMap[panelId];
    const verifiedMarker = result.pdfPanelInventory.markers?.some(marker =>
        marker?.label === panelId && marker?.clarity === 'clear' &&
        marker?.pageNumber === sourcePage);
    if (panelId && verifiedMarker && Number.isSafeInteger(sourcePage) &&
        artworkPages.includes(sourcePage)) {
        request.panelId = panelId;
        request.sourcePage = sourcePage;
    }
    return request;
}

async function showFigureOriginalImage(figureId, { preserveSidebarOnOpen = false } = {}) {
    const panelContext = capturePanelContext();
    const pdfRequest = currentFigureOriginalPdfRequest(figureId);
    const expectsPdfPageNavigation = Boolean(
        pdfRequest.documentHash && pdfRequest.documentGeneration
    );
    const tab = await queryPanelTargetTab();
    if (!tab?.id || Number(tab.id) !== Number(panelContext.tabId) ||
        !isCurrentPanelContext(panelContext)) {
        throw new Error('当前论文页面已切换，请返回后重试');
    }
    const requestSequence = ++figureOriginalViewerState.requestSequence;
    figureOriginalViewerState = {
        open: !expectsPdfPageNavigation,
        tabId: tab.id,
        figureId: expectsPdfPageNavigation ? '' : figureId,
        captionVisible: false,
        preserveSidebarOnOpen: !expectsPdfPageNavigation && preserveSidebarOnOpen === true,
        requestSequence
    };
    let response;
    try {
        response = await sendTabMessage(tab.id, {
            action: 'showFigureOriginalImage', figureId, ...pdfRequest
        });
    } catch (error) {
        if (requestSequence === figureOriginalViewerState.requestSequence) {
            figureOriginalViewerState = {
                open: false,
                tabId: tab.id,
                figureId: '',
                captionVisible: false,
                requestSequence
            };
        }
        throw error;
    }
    if (requestSequence !== figureOriginalViewerState.requestSequence ||
        !isCurrentPanelContext(panelContext)) return;
    if (!response?.success) {
        figureOriginalViewerState = {
            open: false,
            tabId: tab.id,
            figureId: '',
            captionVisible: false,
            requestSequence
        };
        throw new Error(response?.code === 'IMAGE_NOT_FOUND'
            ? '未找到该 Figure 的高清原图' : '无法打开该 Figure 原图');
    }
    const pdfPageNavigation = response.mode === 'pdf-page';
    figureOriginalViewerState = {
        open: !pdfPageNavigation,
        tabId: tab.id,
        figureId: pdfPageNavigation ? '' : String(response.figureId || figureId),
        captionVisible: response.captionVisible === true,
        preserveSidebarOnOpen: !pdfPageNavigation && preserveSidebarOnOpen === true,
        requestSequence
    };
}

async function runFigurePanelFollowup(
    figureId,
    panelId,
    topics,
    customQuestion = '',
    historyLabel = ''
) {
    if (!hasUsableLlm()) throw new Error(llmUnavailableMessage('Panel 追问'));
    const taskToken = figureTaskGeneration;
    const panelText = figurePanelUiText(figureId, panelId);
    const tab = await queryPanelTargetTab();
    if (!tab?.id || !isCurrentFigureTask(taskToken, tab.id)) {
        throw new Error('当前论文页面已切换，请返回后重试');
    }
    showStatus(panelText.followupRunning, 'success');
    let response;
    try {
        response = await sendTabMessage(tab.id, {
            action: 'askFigurePanelWithLLM',
            figureId,
            panelId,
            topics,
            customQuestion,
            historyLabel
        });
    } catch (error) {
        if (!isCurrentFigureTask(taskToken, tab.id)) return { stale: true };
        throw error;
    }
    if (!isCurrentFigureTask(taskToken, tab.id)) return { stale: true };
    if (!response?.success) {
        const error = new Error(response?.error || 'FIGURE_PANEL_FOLLOWUP_FAILED');
        error.code = response?.code;
        throw error;
    }
    const followupKey = panelWorkspaceKey(figureId, panelId);
    const draft = getPanelFollowupDraft(figureId, panelId);
    draft.open = true;
    draft.topics.clear();
    draft.question = '';
    figureExpansionState.set(figureId, true);
    figurePanelExpansionState.set(followupKey, true);
    panelFollowupRevealKey = followupKey;
    await refreshArticleWorkspace();
    if (!isCurrentFigureTask(taskToken, tab.id)) return { stale: true };
    await persistCurrentArticleArchive().catch(() => null);
    if (!isCurrentFigureTask(taskToken, tab.id)) return { stale: true };
    requestAnimationFrame(() => {
        requestAnimationFrame(() => {
            revealPanelFollowupAnswer(followupKey);
            setTimeout(() => {
                if (panelFollowupRevealKey !== followupKey) return;
                stabilizePanelFollowupAnswer(followupKey);
                panelFollowupRevealKey = '';
            }, 280);
        });
    });
    showStatus(
        panelText.followupComplete,
        'success',
        response.usage
    );
    return response;
}

async function runSingleFigureAnalysis(figureId, { trustedUserGesture = false, figureInputMode = '' } = {}) {
    if (!requireUsableLlm('Figure 解读')) return;
    const panelContext = capturePanelContext();
    const key = sidebarBatchKey('figures', panelContext);
    const previous = sidebarBatchIntents.get(key);
    const existing = sidebarRuntimeTasks.get(sidebarTaskDocumentId(), 'figures');
    if (previous?.busy || existing?.busy || previous?.stopRequested && !previous.task?.terminal) return;
    const record = currentWorkspaceSnapshot?.documentId ? currentWorkspaceSnapshot : preparedDocumentState;
    const figure = record?.figures?.figures?.find(item => item.figureId === figureId);
    // The user must choose the evidence basis before this run acquires any
    // image bytes or sends a model request. Cancelling leaves every saved
    // result untouched and does not create a sidebar task.
    const selectedFigureInputMode = figureInputMode ||
        (typeof requestFigureInputModeChoice === 'function'
            ? await requestFigureInputModeChoice({ figureLabel: figure?.figureLabel || figureId })
            : 'vision');
    if (!selectedFigureInputMode || !isCurrentPanelContext(panelContext)) return;
    const intent = { module: 'figures', context: panelContext,
        operationId: `figure-${crypto.randomUUID()}`, documentId: record?.documentId || '',
        documentHash: record?.documentHash || '', busy: true, stopRequested: false, task: null };
    sidebarBatchIntents.set(key, intent);
    renderSidebarBatchActions();
    const taskToken = figureTaskGeneration;
    let tab = null;
    let dispatched = false;
    let uiOwnerHidden = false;
    const onUiOwnerHide = () => { uiOwnerHidden = true; };
    if (trustedUserGesture) window.addEventListener('pagehide', onUiOwnerHide, { once: true });
    const assertCurrent = () => {
        if (uiOwnerHidden || !isCurrentFigureTask(taskToken, tab?.id) || !isCurrentPanelContext(panelContext) ||
            isSidebarOperationStopping(intent.operationId) || sidebarBatchIntents.get(key) !== intent)
            throw Object.assign(new Error('本次解图已停止或页面归属已变化'), { code: 'CANCELLED' });
    };
    try {
        tab = await queryPanelTargetTab();
        if (!tab?.id) throw new Error('ACTIVE_TAB_NOT_FOUND');
        if (!isCurrentFigureTask(taskToken, tab.id) || !isCurrentPanelContext(panelContext) ||
            isSidebarOperationStopping(intent.operationId)) return;
        let figureUserResumeIntent = '', figureUserResumeBinding = null;
        let resumeIncomplete = false;
        if (trustedUserGesture) {
            if (!figure) throw Object.assign(new Error('本次解图的 Figure 已变化'), { code: 'FIGURE_SELECTION_STALE' });
            // A failed/partial run is an explicit continuation. A completed
            // Figure retains the existing double-click re-read intent.
            const hasCompletedResult = ['standard', 'deep'].some(depth => {
                const result = figure[depth];
                if (SciLLM.isUsableFigureAnalysisResult?.(result, figure, { analysisDepth: depth }) !== true) return false;
                const panelId = value => String(value || '').normalize('NFKC').trim().toUpperCase();
                const returned = new Set((result.panels || []).map(panel => panelId(panel.panel)));
                return (figure.panelHints || []).every(panel => returned.has(panelId(panel)));
            });
            resumeIncomplete = Boolean(!hasCompletedResult || figure.standardError || figure.deepError ||
                figure.pendingStandard || figure.pendingDeep || figure.pendingStandardCheckpointEnvelope ||
                figure.pendingDeepCheckpointEnvelope);
            if (resumeIncomplete) {
                const figureUiOwnerBinding = typeof chrome.runtime.getContexts === 'function'
                    ? await captureFigureUiOwnerBinding() : null;
                assertCurrent();
                intent.figureUiOwnerBinding = figureUiOwnerBinding;
                const binding = await refreshSidebarRuntimeDocumentBinding(panelContext, { figureBinding: true, assertCurrent });
                assertCurrent();
                if (!binding || binding.documentHash !== intent.documentHash)
                    throw Object.assign(new Error('本次继续的论文身份已变化'), { code: 'FIGURE_SELECTION_STALE' });
                figureUserResumeBinding = { tabId: tab.id, documentIdentity: binding.documentIdentity,
                    navigationIdentity: SciLLM.normalizeTabDocumentUrl(panelContext.url), documentHash: binding.documentHash,
                    workspaceLifecycle: binding.workspaceLifecycle, figureIds: [figureId] };
                const authorization = await chrome.runtime.sendMessage({ type: 'LLM_CONTROL_OPERATION',
                    operationScope: 'figure', command: 'authorize-user-resume', operationId: intent.operationId,
                    figureUserResumeBinding, ...(figureUiOwnerBinding ? { figureUiOwnerBinding } : {}) });
                assertCurrent();
                if (!authorization?.success) throw Object.assign(new Error(authorization?.error?.message || '无法确认本次继续范围'),
                    { code: authorization?.error?.code });
                figureUserResumeIntent = authorization.data?.figureUserResumeIntent || '';
            }
        }
        assertCurrent();
        startFigureProgressPolling(tab.id, { waitForSnapshot: true });
        showStatus(`\u6b63\u5728\u7cbe\u8bfb ${figureId}\u2026`, 'success');
        dispatched = true;
        const pending = sendTabMessage(tab.id, {
            action: 'analyzeSingleFigureWithLLM', figureId, forceRefresh: !resumeIncomplete, operationId: intent.operationId,
            figureInputMode: selectedFigureInputMode,
            ...(figureUserResumeIntent ? { figureUserResumeIntent, figureUserResumeBinding } : {})
        });
        void pollSidebarRuntimeTasks();
        const response = await pending;
        if (!isCurrentFigureTask(taskToken, tab.id) || !isCurrentPanelContext(panelContext)) return;
        if (response?.runtimeTaskReceipt) await retireSidebarFigureIntent(intent, response.runtimeTaskReceipt);
        acceptSidebarRuntimeTask(response?.runtimeTask, panelContext, 'figures');
        if (!response?.success) {
            const error = new Error(response?.error || 'FIGURE_ANALYSIS_FAILED');
            error.code = response?.code;
            error.cancellationOrigin = response?.cancellationOrigin || response?.runtimeTaskReceipt?.cancellationOrigin || '';
            throw error;
        }
        showStatus(
            `\u5df2\u5b8c\u6210 ${figureId} \u7684\u5355\u56fe\u7cbe\u8bfb`,
            'success',
            response.usage
        );
    } catch (error) {
        if (!isCurrentFigureTask(taskToken, tab?.id)) return;
        const sourceChanged = error.cancellationOrigin === 'article-source-changed';
        showStatus(error?.code === 'CANCELLED'
            ? sourceChanged ? '正文已更新，本次解图已停止；已保存结果保留。' : '解图已取消，已有结果会保留。'
            : '\u5355\u56fe\u7cbe\u8bfb\u5931\u8d25\uff1a' + error.message,
        sourceChanged ? 'warning' : error?.code === 'CANCELLED' ? 'success' : 'error');
    } finally {
        if (trustedUserGesture) window.removeEventListener('pagehide', onUiOwnerHide);
        intent.busy = false;
        if (!dispatched && !intent.task) intent.stopRequested = false;
        if (isCurrentPanelContext(panelContext)) { renderSidebarBatchActions(); void pollSidebarRuntimeTasks(); }
        if (!isCurrentFigureTask(taskToken, tab?.id)) return;
        const progress = tab?.id
            ? await refreshFigureAnalysisProgress(tab.id, false, taskToken)
            : null;
        if (!isCurrentFigureTask(taskToken, tab?.id) || !isCurrentPanelContext(panelContext) ||
            sidebarBatchIntents.get(key) !== intent) return;
        if (!hasRunningFigureProgress(progress)) stopFigureProgressPolling();
        renderFigureWorkspaceSnapshot(currentWorkspaceSnapshot);
        await refreshArticleWorkspace();
        if (!isCurrentFigureTask(taskToken, tab?.id) || !isCurrentPanelContext(panelContext) ||
            sidebarBatchIntents.get(key) !== intent) return;
        await persistCurrentArticleArchive().catch(() => null);
    }
}

function runFigureRecoveryFromUi(figure, panelIds, presentation, button = null) {
    const action = presentation?.action === 'deep_rerun'
        ? 'deep_rerun' : 'missing_panels';
    const tabId = Number(activePanelTabContext.tabId) || 0;
    const key = `${tabId}:${String(figure?.figureId || '')}:${action}`;
    return runKeyedFigureRecoveryAction(
        key,
        () => action === 'deep_rerun'
            ? runDeepFigureRecovery(figure)
            : runMissingFigurePanelRetry(figure, panelIds),
        () => {
            if (button) {
                button.disabled = true;
                button.setAttribute('aria-busy', 'true');
            }
            if (tabId) startFigureProgressPolling(tabId, { waitForSnapshot: true });
        },
        () => {
            if (button?.isConnected) {
                button.setAttribute('aria-busy', 'false');
            }
            if (tabId) {
                void refreshFigureAnalysisProgress(tabId, false, figureTaskGeneration)
                    .finally(() => renderFigureWorkspaceSnapshot(currentWorkspaceSnapshot));
            } else {
                renderFigureWorkspaceSnapshot(currentWorkspaceSnapshot);
            }
        }
    );
}

async function runDeepFigureRecovery(figure) {
    if (!requireUsableLlm('Figure 解读')) return null;
    const taskToken = figureTaskGeneration;
    let tab = null;
    try {
        tab = await queryPanelTargetTab();
        if (!tab?.id) throw new Error('ACTIVE_TAB_NOT_FOUND');
        if (!isCurrentFigureTask(taskToken, tab.id)) return null;
        showStatus(t('重新运行深度解读以补齐缺失 Panel'), 'success');
        const response = await sendTabMessage(tab.id, {
            action: 'analyzeSingleFigureDeepWithLLM',
            figureId: figure.figureId,
            operationId: createFigureRecoveryOperationId('deep', figure.figureId),
            expectedFigureInputHash: String(figure.figureInputHash || '')
        });
        if (!isCurrentFigureTask(taskToken, tab.id)) return null;
        if (!response?.success) {
            const error = new Error(response?.error || 'FIGURE_DEEP_RETRY_FAILED');
            error.code = response?.code;
            throw error;
        }
        showStatus(`${figure.figureLabel || figure.figureId}：${t('深度解读恢复完成')}`,
            'success', response.usage);
        return response;
    } catch (error) {
        if (!isCurrentFigureTask(taskToken, tab?.id)) return null;
        showStatus(error?.code === 'FIGURE_PANEL_RETRY_SCOPE_STALE'
            ? t('Figure 状态已变化，请刷新后按当前缺失 Panel 重试。')
            : `${t('深度解读恢复失败')}：${error.message}`, 'error');
        return null;
    } finally {
        if (isCurrentFigureTask(taskToken, tab?.id)) {
            await refreshArticleWorkspace();
            await persistCurrentArticleArchive().catch(() => null);
        }
    }
}

async function runMissingFigurePanelRetry(figure, panelIds) {
    if (!requireUsableLlm('Figure 解读')) return;
    const requestedPanels = normalizeFigureRecoveryPanelLabels(panelIds);
    if (!figure?.figureId || !requestedPanels.length) return;
    const taskToken = figureTaskGeneration;
    let tab = null;
    try {
        tab = await queryPanelTargetTab();
        if (!tab?.id) throw new Error('ACTIVE_TAB_NOT_FOUND');
        if (!isCurrentFigureTask(taskToken, tab.id)) return;
        showStatus(`${t('重试缺失 Panel')}：${requestedPanels.join('、')}`, 'success');
        const response = await sendTabMessage(tab.id, {
            action: 'retryMissingFigurePanelsWithLLM',
            figureId: figure.figureId,
            panelIds: requestedPanels,
            analysisDepth: figureKeyboardResult(figure)?.analysisDepth === 'deep' ? 'deep' : 'standard',
            operationId: createFigureRecoveryOperationId('panels', figure.figureId),
            expectedFigureInputHash: String(figure.figureInputHash || '')
        });
        if (!isCurrentFigureTask(taskToken, tab.id)) return;
        if (!response?.success) {
            const error = new Error(response?.error || 'FIGURE_PANEL_RETRY_FAILED');
            error.code = response?.code;
            throw error;
        }
        showStatus(
            response.partial
                ? `${t('已保留')} ${response.resolvedPanels?.length || 0} ` +
                    `${t('个恢复结果')}；${t('仍有 Panel 待补')}`
                : `${t('已完成缺失 Panel')}：${requestedPanels.join('、')}`,
            response.partial ? 'error' : 'success'
        );
    } catch (error) {
        if (!isCurrentFigureTask(taskToken, tab?.id)) return;
        const message = error?.code === 'FIGURE_PANEL_RETRY_SCOPE_STALE'
            ? t('Figure 状态已变化，请刷新后按当前缺失 Panel 重试。')
            : error?.code === 'FIGURE_DEEP_RETRY_REQUIRES_RERUN'
                ? t('深度解读的缺失 Panel 需要重新运行深度解读')
                : `${t('缺失 Panel 重试失败')}：${error.message}`;
        showStatus(message, 'error');
    } finally {
        if (!isCurrentFigureTask(taskToken, tab?.id)) return;
        await refreshArticleWorkspace();
        await persistCurrentArticleArchive().catch(() => null);
    }
}

async function runSingleFigurePanelAnalysis(figureId, panelId) {
    if (!requireUsableLlm('Panel 解读')) return;
    const panelText = figurePanelUiText(figureId, panelId);
    const taskToken = figureTaskGeneration;
    let tab = null;
    try {
        tab = await queryPanelTargetTab();
        if (!tab?.id) throw new Error('ACTIVE_TAB_NOT_FOUND');
        if (!isCurrentFigureTask(taskToken, tab.id)) return;
        figureExpansionState.set(figureId, true);
        figurePanelExpansionState.set(panelWorkspaceKey(figureId, panelId), true);
        startFigureProgressPolling(tab.id, { waitForSnapshot: true });
        showStatus(panelText.analysisRunning, 'success');
        const response = await sendTabMessage(tab.id, {
            action: 'analyzeSingleFigurePanelWithLLM',
            figureId,
            panelId,
            forceRefresh: true
        });
        if (!isCurrentFigureTask(taskToken, tab.id)) return;
        if (!response?.success) {
            const error = new Error(response?.error || 'FIGURE_PANEL_ANALYSIS_FAILED');
            error.code = response?.code;
            throw error;
        }
        showStatus(formatEffectiveRoute(
            panelText.analysisComplete, response.route
        ), 'success', response.usage);
    } catch (error) {
        if (!isCurrentFigureTask(taskToken, tab?.id)) return;
        showStatus(error?.code === 'CANCELLED'
            ? 'Panel 解读已取消，已有结果会保留。'
            : `Panel 解读失败：${error.message}`,
        error?.code === 'CANCELLED' ? 'success' : 'error');
    } finally {
        if (!isCurrentFigureTask(taskToken, tab?.id)) return;
        const progress = tab?.id
            ? await refreshFigureAnalysisProgress(tab.id, false, taskToken)
            : null;
        if (!hasRunningFigureProgress(progress)) stopFigureProgressPolling();
        await refreshArticleWorkspace();
        await persistCurrentArticleArchive().catch(() => null);
    }
}

async function runCrossFigureLogic({
    returnView = activeWorkspaceView === 'mechanism' ? 'mechanism' : 'figures',
    seedMode = returnView === 'mechanism' ? 'auto' : 'none'
} = {}) {
    if (!requireUsableLlm('机制链')) return;
    let tab = null;
    let taskToken = null;
    let operationId = '';
    let completedResponse = null;
    let generationContext = null;
    let generationPanelContext = null;
    try {
        tab = await queryPanelTargetTab();
        if (!tab?.id) throw new Error('ACTIVE_TAB_NOT_FOUND');
        taskToken = figureTaskGeneration;
        if (!isCurrentFigureTask(taskToken, tab.id)) return;
        generationPanelContext = capturePanelContext();
        // Another panel or an asynchronous Figure merge may have advanced the
        // shared draft since this sidebar rendered. Read the authoritative view
        // before binding a new operation; its later CAS checks remain strict.
        const generationSnapshot = await refreshArticleWorkspace({
            panelContext: generationPanelContext
        });
        if (!isCurrentFigureTask(taskToken, tab.id) ||
            !isCurrentPanelContext(generationPanelContext)) return;
        if (!generationSnapshot) {
            const error = new Error('MECHANISM_WORKSPACE_SYNC_FAILED');
            error.code = 'MECHANISM_WORKSPACE_SYNC_FAILED';
            throw error;
        }
        if (generationSnapshot.figures?.inventoryReady === false) {
            const error = new Error('图目录尚未保存，请刷新解图目录后再生成图表梳理。');
            error.code = generationSnapshot.figures.inventoryError?.code ||
                'FIGURE_WORKSPACE_INVENTORY_SEED_FAILED';
            throw error;
        }
        generationContext = captureFigureWorkspaceEditContext();
        operationId = createMechanismOperationId();
        const binding = Object.freeze({
            documentId: generationContext.documentId,
            workspaceId: generationContext.workspaceId,
            workspaceGeneration: generationContext.workspaceGeneration,
            workspaceLifecycle: generationContext.workspaceLifecycle,
            baseWorkspaceRevision: generationContext.draftRevision,
            mechanismChainFingerprint: generationContext.mechanismChainFingerprint
        });
        const evidenceFirstVersions = SciLLM.normalizeEvidenceFirstVersions?.(
            SciLLM.EVIDENCE_FIRST_VERSIONS
        );
        if (!evidenceFirstVersions) {
            const error = new Error('MECHANISM_REQUEST_INVALID');
            error.code = 'MECHANISM_REQUEST_INVALID';
            throw error;
        }
        const generationRequest = createEvidenceFirstMechanismPopupRequest({
            evidenceFirstVersion: '2',
            evidenceFirstRouterVersion: '2',
            evidenceFirstVersions,
            operationId,
            documentId: binding.documentId,
            workspaceId: binding.workspaceId,
            baseWorkspaceRevision: binding.baseWorkspaceRevision,
            workspaceGeneration: binding.workspaceGeneration,
            workspaceLifecycle: binding.workspaceLifecycle,
            mechanismChainFingerprint: binding.mechanismChainFingerprint
        }, SciLLM);
        const controller = replaceMechanismGenerationUiController(tab.id);
        controller.start({ operationId, epoch: 0, binding, evidenceFirstVersions });
        renderMechanismGenerationStatus();
        const rawResponse = await sendTabMessage(tab.id, generationRequest);
        const response = Object.freeze({
            success: mechanismGenerationOwnData(rawResponse, 'success'),
            code: mechanismGenerationOwnData(rawResponse, 'code'),
            operationEpoch: mechanismGenerationOwnData(rawResponse, 'operationEpoch'),
            status: mechanismGenerationOwnData(rawResponse, 'status'),
            operationId: mechanismGenerationOwnData(rawResponse, 'operationId'),
            evidenceFirstVersions: mechanismGenerationOwnData(
                rawResponse, 'evidenceFirstVersions'
            ),
            result: mechanismGenerationOwnData(rawResponse, 'result'),
            workspaceCommitted: mechanismGenerationOwnData(
                rawResponse, 'workspaceCommitted'
            ),
            route: mechanismGenerationOwnData(rawResponse, 'route'),
            usage: mechanismGenerationOwnData(rawResponse, 'usage')
        });
        const presentation = mechanismGenerationUiController.presentation();
        if (!isCurrentFigureTask(taskToken, tab.id) ||
            presentation.operation?.operationId !== operationId ||
            ['cancelling', 'cancelled'].includes(presentation.status)) return;
        const responseVersions = SciLLM.normalizeEvidenceFirstVersions?.(
            response.evidenceFirstVersions
        );
        if (!responseVersions) {
            mechanismGenerationUiController.fail(operationId, 'INVALID_RESPONSE');
            renderMechanismGenerationStatus();
            const error = new Error('INVALID_RESPONSE');
            error.code = 'INVALID_RESPONSE';
            throw error;
        }
        if (response.success !== true) {
            const suppliedResponseCode = response.code;
            const responseCode = /^[A-Z][A-Z0-9_-]{2,80}$/u.test(
                String(suppliedResponseCode || '')
            ) ? String(suppliedResponseCode) : 'MECHANISM_GENERATION_FAILED';
            mechanismGenerationUiController.fail(operationId, responseCode);
            renderMechanismGenerationStatus();
            const error = new Error(responseCode);
            error.code = responseCode;
            throw error;
        }
        const responseEpoch = Number(response.operationEpoch);
        const responseStatus = String(response.status || '');
        const responseOperationId = response.operationId;
        const responseResult = response.result;
        if (responseOperationId !== operationId ||
            !Number.isSafeInteger(responseEpoch) || responseEpoch < 1 ||
            !['complete', 'needs_review', 'failed', 'cancelled',
                'revision_conflict'].includes(responseStatus)) {
            mechanismGenerationUiController.fail(operationId, 'INVALID_RESPONSE');
            renderMechanismGenerationStatus();
            const error = new Error('INVALID_RESPONSE');
            error.code = 'INVALID_RESPONSE';
            throw error;
        }
        if (responseStatus === 'complete' &&
            (!isSeedableMechanismGenerationResult(responseResult) ||
                response.workspaceCommitted !== true)) {
            mechanismGenerationUiController.fail(operationId, 'INVALID_RESPONSE');
            renderMechanismGenerationStatus();
            const error = new Error('INVALID_RESPONSE');
            error.code = 'INVALID_RESPONSE';
            throw error;
        }
        const terminalEvent = {
            status: responseStatus,
            errorCode: response.code,
            operationId,
            operationEpoch: responseEpoch,
            evidenceFirstVersions: responseVersions,
            ...binding
        };
        const acceptedTerminal = mechanismGenerationUiController.complete(terminalEvent);
        const terminalPresentation = mechanismGenerationUiController.presentation();
        if (!acceptedTerminal && (terminalPresentation.operation?.operationId !== operationId ||
            terminalPresentation.status !== responseStatus)) return;
        renderMechanismGenerationStatus();
        if (responseStatus === 'complete') {
            completedResponse = Object.freeze({
                success: true,
                status: 'complete',
                operationId,
                operationEpoch: responseEpoch,
                evidenceFirstVersions: responseVersions,
                result: responseResult,
                workspaceCommitted: true,
                route: response.route || null,
                usage: response.usage || null
            });
        } else {
            const failed = responseStatus === 'failed' || responseStatus === 'revision_conflict';
            showStatus(failed
                ? formatLlmFailureMessage('机制链生成', { code: terminalPresentation.code })
                : mechanismGenerationStatusLabel(terminalPresentation),
            failed ? 'error' : responseStatus === 'cancelled' ? 'success' : 'warning');
            // The content realm persists valid partial evidence separately from
            // the editable chain. Refresh it so a needs-review result is visible
            // immediately instead of leaving the user at an old manual node.
            if (responseStatus === 'needs_review' || responseResult?.evidenceFirstMechanism) {
                await refreshArticleWorkspace({ panelContext: generationPanelContext });
                if (isCurrentPanelContext(generationPanelContext)) {
                    // Pending generated evidence stays in the existing review surface;
                    // it is never treated as an accepted editable drawing.
                    switchWorkspaceView('mechanism');
                }
            }
            return {
                success: true, status: responseStatus, operationId,
                operationEpoch: responseEpoch,
                code: terminalPresentation.code
            };
        }
        const result = responseResult;
        const resultNodes = mechanismGenerationOwnData(result, 'nodes');
        const resultDominoChain = mechanismGenerationOwnData(result, 'dominoChain');
        const evidenceFirstMechanism = mechanismGenerationOwnData(
            result, 'evidenceFirstMechanism'
        );
        const evidenceNodes = mechanismGenerationOwnData(
            evidenceFirstMechanism, 'nodes'
        );
        const evidenceRelations = mechanismGenerationOwnData(
            evidenceFirstMechanism, 'relations'
        );
        const boundedArrayLength = (value, maximum) => {
            let isArray = false;
            try { isArray = Array.isArray(value); } catch (_) { return 0; }
            const length = isArray ? mechanismGenerationOwnData(value, 'length') : 0;
            return Number.isSafeInteger(length) && length >= 0 && length <= maximum
                ? length : 0;
        };
        const legacyNodeCount = boundedArrayLength(resultNodes, 128);
        const evidenceNodeCount = boundedArrayLength(evidenceNodes, 64);
        const legacyLinkCount = boundedArrayLength(resultDominoChain, 256);
        const evidenceRelationCount = boundedArrayLength(evidenceRelations, 64);
        let supportedRelationCount = 0;
        for (let index = 0; index < evidenceRelationCount; index += 1) {
            const relation = mechanismGenerationOwnData(evidenceRelations, String(index));
            if (mechanismGenerationOwnData(relation, 'relationStatus') === 'supported') {
                supportedRelationCount += 1;
            }
        }
        const nodes = legacyNodeCount || evidenceNodeCount;
        const links = legacyLinkCount || supportedRelationCount;
        showStatus(
            `跨图综合已生成：${nodes} 个节点、${links} 条跨图连接` +
                (mechanismGenerationOwnData(result, 'cacheHit') === true
                    ? '（已复用缓存）' : ''),
            'success',
            completedResponse.usage
        );
        switchWorkspaceView(returnView === 'mechanism' ? 'figures' : returnView);
        return completedResponse;
    } catch (error) {
        if (!isCurrentFigureTask(taskToken, tab?.id) ||
            (operationId && mechanismGenerationUiController.presentation()
                .operation?.operationId !== operationId)) return;
        showStatus(error?.code === 'CANCELLED'
            ? '机制链生成已取消。'
            : formatLlmFailureMessage('机制链生成', error),
        error?.code === 'CANCELLED' ? 'success' : 'error');
        return null;
    } finally {
        const stillCurrent = isCurrentFigureTask(taskToken, tab?.id) &&
            (!operationId || mechanismGenerationUiController.presentation()
                .operation?.operationId === operationId);
        if (!stillCurrent) return;
        renderMechanismGenerationStatus();
        if (completedResponse) {
            await finalizeSuccessfulMechanismGeneration({
                response: completedResponse,
                seedMode: 'none',
                generationContext,
                refresh: () => refreshArticleWorkspace({
                    panelContext: generationPanelContext
                }),
                seed: seedMechanismChainFromCrossFigure,
                isContextCurrent: isCurrentFigureWorkspaceEditContext,
                matchesSnapshot: mechanismSnapshotMatchesContext,
                onBlocked(message) {
                    setMechanismChainSaveStatus(message, 'error');
                    showStatus(message, 'error');
                }
            }).catch(() => {
                if (returnView === 'mechanism') {
                    showStatus('机制链初始化失败；可继续手动新增节点。', 'error');
                }
            });
        } else {
            await refreshArticleWorkspace({ panelContext: generationPanelContext })
                .catch(() => null);
        }
        if (returnView === 'mechanism') {
            if (completedResponse && !currentWorkspaceSnapshot?.figures?.crossFigureLogic?.pendingResult) {
                switchWorkspaceView('figures');
                await openMechanismChainWorkspace();
            } else switchWorkspaceView('mechanism');
            figureWorkspaceRenderCoordinator.request(currentWorkspaceSnapshot);
        }
        await persistCurrentArticleArchive().catch(() => null);
    }
}

async function runReviewOutlineAnalysis({ forceRefresh = false, operationId = '', scopeSnapshot = currentWorkspaceSnapshot, scopeSectionIds = null, scopeSelectionProvided = null } = {}) {
    const panelContext = capturePanelContext(reviewOutlineTaskGeneration);
    if (!isCurrentReviewOutlineTask(panelContext)) return;
    if (!requireUsableLlm('逐段摘要')) return { notStarted: true };
    const tabId = panelContext.tabId;
    const scopeSignature = snapshot => JSON.stringify([
        snapshot?.documentId, snapshot?.documentHash, snapshot?.url, snapshot?.revision,
        snapshot?.documentGeneration ?? snapshot?.abbreviations?.documentGeneration,
        snapshot?.figures?.workspaceLifecycle, selectedWorkspaceAnalysisSectionIds(snapshot).sort(),
        snapshot?.analysisSelectionCustomized === true
    ]);
    const capturedScopeSignature = scopeSignature(scopeSnapshot);
    const requestedScope = Array.isArray(scopeSectionIds) ? [...scopeSectionIds] : selectedWorkspaceAnalysisSectionIds(scopeSnapshot);
    const selectionCustomized = scopeSelectionProvided ?? (scopeSnapshot?.analysisSelectionCustomized === true);
    const scopeError = () => Object.assign(new Error('REVIEW_OUTLINE_SCOPE_STALE'), { code: 'REVIEW_OUTLINE_SCOPE_STALE' });
    const assertScopeCurrent = () => {
        if (!isCurrentReviewOutlineTask(panelContext) || !scopeSnapshot?.documentId || !scopeSnapshot?.documentHash ||
            scopeSignature(currentWorkspaceSnapshot) !== capturedScopeSignature ||
            workspaceAnalysisSelectionPending.get(panelContext.key)?.size ||
            JSON.stringify([...requestedScope].sort()) !== JSON.stringify(selectedWorkspaceAnalysisSectionIds(scopeSnapshot).sort())) {
            throw scopeError();
        }
    };
    const verifyScopeSource = async previousBinding => {
        assertScopeCurrent();
        const binding = await refreshSidebarRuntimeDocumentBinding(panelContext);
        assertScopeCurrent();
        if (!binding || binding.documentId !== scopeSnapshot.documentId || binding.documentHash !== scopeSnapshot.documentHash ||
            previousBinding && binding.documentIdentity !== previousBinding.documentIdentity) throw scopeError();
        const live = await sendTabMessage(tabId, {
            action: 'getArticleWorkspaceSnapshot',
            expectedDocumentIdentity: binding.documentIdentity,
            expectedNavigationIdentity: SciLLM.normalizeTabDocumentUrl(panelContext.url)
        });
        assertScopeCurrent();
        if (!live?.success || scopeSignature(live.snapshot) !== capturedScopeSignature) throw scopeError();
        return binding;
    };
    try {
        if (!preparedDocumentState) {
            await prepareArticleForAdaptiveAnalysis(tabId, {
                isCurrent: () => isCurrentReviewOutlineTask(panelContext)
            });
            if (!isCurrentReviewOutlineTask(panelContext)) return;
        }
        if (!isCurrentReviewOutlineTask(panelContext)) return;
        const scopeBinding = await verifyScopeSource();
        if (selectionCustomized && !requestedScope.length) {
            showStatus('请先选择要概述的章节；当前没有发送模型请求。', 'warning');
            return { notStarted: true };
        }
        showStatus('正在生成逐段摘要…', 'success');
        reviewOutlineState = {
            ...reviewOutlineState,
            running: true,
            phase: 'extracting',
            completedParagraphs: 0,
            totalParagraphs: preparedDocumentState?.document?.paragraphs?.length || 0,
            message: '正在提取正文层级…'
        };
        updateReviewOutlineButton();
        startReviewOutlineProgressPolling(tabId, panelContext, operationId);
        if (isSidebarOperationStopping(operationId)) return { cancelled: true, notStarted: true };
        assertScopeCurrent();
        const response = await sendTabMessage(panelContext.tabId, {
            action: 'analyzeReviewOutlineWithLLM',
            operationId,
            forceRefresh,
            documentId: scopeSnapshot.documentId,
            documentHash: scopeSnapshot.documentHash,
            scopeSectionIds: requestedScope,
            scopeSelectionProvided: selectionCustomized,
            expectedDocumentIdentity: scopeBinding.documentIdentity,
            expectedNavigationIdentity: SciLLM.normalizeTabDocumentUrl(panelContext.url)
        });
        if (!isCurrentReviewOutlineTask(panelContext)) return;
        await verifyScopeSource(scopeBinding);
        acceptSidebarRuntimeTask(response?.runtimeTask, panelContext, 'navigation');
        if (!response?.success) {
            const error = new Error(response?.error || '论文大纲生成失败');
            error.code = response?.code;
            throw error;
        }
        // Pull the real final counts/save receipt even if the task finished between polls.
        await refreshReviewOutlineProgress(tabId, false, panelContext,
            operationId || response.runtimeTask?.operationId || '');
        if (!isCurrentReviewOutlineTask(panelContext)) return;
        reviewOutlineState = {
            ...reviewOutlineState,
            running: false,
            phase: 'completed',
            completedParagraphs: response.outline?.paragraphCount ||
                reviewOutlineState.totalParagraphs,
            hasOutline: true,
            globalSynthesisAvailable: response.outline?.globalSynthesisAvailable
        };
        await refreshArticleWorkspace({ panelContext });
        if (!isCurrentReviewOutlineTask(panelContext)) return;
        await persistCurrentArticleArchive({ panelContext }).catch(() => null);
        if (!isCurrentReviewOutlineTask(panelContext)) return;
        const synthesisNotice = SciLLM.formatReviewSynthesisNotice(response.outline);
        showStatus(
            `论文大纲已生成：${reviewOutlineState.completedParagraphs} 段` +
                (synthesisNotice ? '；' + synthesisNotice : ''),
            synthesisNotice ? 'error' : 'success',
            response.usage
        );
    } catch (error) {
        if (!isCurrentReviewOutlineTask(panelContext)) return;
        const progress = tabId
            ? await refreshReviewOutlineProgress(tabId, false, panelContext)
            : reviewOutlineState;
        if (!isCurrentReviewOutlineTask(panelContext)) return;
        const progressText = progress?.totalParagraphs
            ? `（已完成 ${progress.completedParagraphs || 0}/${progress.totalParagraphs} 段）`
            : '';
        const resumeNotice = progress?.saveConfirmed === true
            ? '；档案保存队列已确认，重新点击可恢复'
            : progress?.checkpointCached === true
                ? '；已生成段落已有缓存，档案保存尚未确认；重试会复用缓存'
                : '';
        showStatus('论文大纲生成失败' + progressText + '：' + error.message +
            resumeNotice, 'error');
    } finally {
        if (!isCurrentReviewOutlineTask(panelContext)) return;
        stopReviewOutlineProgressPolling();
        reviewOutlineState = { ...reviewOutlineState, running: false };
        updateReviewOutlineButton();
    }
}

function renderManualAnnotationSummary() {
    const summary = document.getElementById('manualAnnotationSummary');
    if (!manualAnnotationState.documentId) {
        summary.textContent = '当前页面尚未准备好手动标注数据';
    } else {
        summary.textContent = `本文手动标注 ${manualAnnotationState.annotationCount} 条` +
            ` · 待重新定位 ${manualAnnotationState.unresolvedCount} 条`;
    }
    const automaticButton = document.getElementById('clearAutomaticHighlights');
    const manualButton = document.getElementById('clearManualAnnotations');
    if (automaticButton) automaticButton.disabled = automaticClearPending;
    if (manualButton) {
        manualButton.disabled = manualClearPending ||
            !manualAnnotationState.documentId || manualAnnotationState.annotationCount === 0;
    }
}

function applyManualAnnotationStateEvent(event = {}, tabId = null) {
    if (manualAnnotationEventRefreshPromise?.tabId === Number(tabId)) return false;
    const commitMode = SciLLM.manualAnnotationEventCommitMode(
        manualAnnotationState,
        event,
        tabId,
        activePanelTabContext.tabId
    );
    if (commitMode !== 'verified') return false;
    manualSummarySequence += 1;
    manualAnnotationState = {
        ...manualAnnotationState,
        title: String(event.title || ''),
        annotationCount: Math.max(0, Number(event.annotationCount) || 0),
        unresolvedCount: Math.max(0, Number(event.unresolvedCount) || 0)
    };
    renderManualAnnotationSummary();
    return true;
}

function refreshManualAnnotationSummaryAfterUnverifiedEvent(tabId) {
    const numericTabId = Number(tabId);
    if (!Number.isSafeInteger(numericTabId)) return Promise.resolve(null);
    if (manualAnnotationEventRefreshPromise?.tabId === numericTabId) {
        return manualAnnotationEventRefreshPromise.promise;
    }
    const promise = refreshManualAnnotationSummary(numericTabId)
        .then(state => {
            if (state) void refreshArticleWorkspace();
            return state;
        })
        .finally(() => {
            if (manualAnnotationEventRefreshPromise?.promise === promise) {
                manualAnnotationEventRefreshPromise = null;
            }
        });
    manualAnnotationEventRefreshPromise = { tabId: numericTabId, promise };
    return promise;
}

async function refreshManualAnnotationSummary(tabId = null, { signal } = {}) {
    if (signal?.aborted) return null;
    const requestId = ++manualSummarySequence;
    try {
        const capturedTab = await queryPanelTargetTab();
        if (signal?.aborted) return null;
        const targetTabId = tabId || capturedTab?.id;
        if (!targetTabId) throw new Error('无法获取当前论文页面');
        if (Number(capturedTab?.id) !== Number(targetTabId)) return null;
        const response = await sendTabMessage(targetTabId, {
            action: 'prepareManualAnnotations'
        });
        if (signal?.aborted) return null;
        if (!response?.success) {
            throw new Error(response?.error || '手动标注数据不可用');
        }
        const liveProof = await sendTabMessage(targetTabId, {
            action: 'prepareManualAnnotations'
        });
        if (signal?.aborted) return null;
        const currentTab = await queryPanelTargetTab();
        if (signal?.aborted) return null;
        const commitMode = SciLLM.manualAnnotationRefreshCommitMode({
            expectedTabId: targetTabId,
            capturedTab,
            currentTab,
            response,
            liveProof,
            committedState: manualAnnotationState,
            superseded: requestId !== manualSummarySequence
        });
        if (commitMode === 'committed') return manualAnnotationState;
        if (commitMode !== 'response') return null;
        manualAnnotationState = {
            tabId: targetTabId,
            documentId: liveProof.documentId,
            documentHash: liveProof.documentHash || '',
            canonicalUrl: liveProof.canonicalUrl || '',
            contentWorldNonce: liveProof.contentWorldNonce || '',
            documentEpoch: Number(liveProof.documentEpoch) || 0,
            title: liveProof.title || '',
            annotationCount: Math.max(0, Number(liveProof.annotationCount) || 0),
            unresolvedCount: Math.max(0, Number(liveProof.unresolvedCount) || 0)
        };
        renderManualAnnotationSummary();
        return manualAnnotationState;
    } catch (error) {
        if (signal?.aborted || requestId !== manualSummarySequence) return null;
        manualAnnotationState = {
            tabId: null,
            documentId: '',
            documentHash: '',
            canonicalUrl: '',
            title: '',
            annotationCount: 0,
            unresolvedCount: 0
        };
        renderManualAnnotationSummary();
        return null;
    }
}

async function clearAutomaticHighlightsFromCurrentTab() {
    if (automaticClearPending) return;
    automaticClearPending = true;
    renderManualAnnotationSummary();
    try {
        const tab = await queryPanelTargetTab();
        if (!tab?.id) throw new Error('无法获取当前论文页面');
        const response = await sendTabMessage(tab.id, {
            action: 'clearAutomaticHighlights'
        });
        if (!response?.success) throw new Error(response?.error || '清除自动高亮失败');
        matchCounts = {};
        renderCategories();
        await persistCurrentArticleArchive().catch(() => null);
        showStatus(response.persisted === false
            ? `自动高亮已清除，手动标注保留不变；本地状态保存失败：` +
                `${response.persistenceError || '请稍后重试'}`
            : '自动高亮已清除，手动标注保留不变',
        response.persisted === false ? 'error' : 'success');
    } catch (error) {
        showStatus(`清除自动高亮失败：${error.message}`, 'error');
    } finally {
        automaticClearPending = false;
        renderManualAnnotationSummary();
    }
}

function openManualClearConfirmation() {
    if (manualClearPending || !manualAnnotationState.documentId ||
        manualAnnotationState.annotationCount === 0) return;
    document.getElementById('clearManualDescription').textContent =
        `将删除本文 ${manualAnnotationState.annotationCount} 条手动标注，` +
        `其中 ${manualAnnotationState.unresolvedCount} 条待重新定位。自动高亮不会受影响。`;
    document.getElementById('clearManualDialog').showModal();
}

async function confirmManualAnnotationClear(event) {
    event.preventDefault();
    if (manualClearPending) return;
    const snapshot = { ...manualAnnotationState };
    if (!snapshot.documentId || snapshot.annotationCount === 0) return;
    manualClearPending = true;
    renderManualAnnotationSummary();
    const confirmButton = document.getElementById('confirmClearManual');
    confirmButton.disabled = true;
    try {
        const tab = await queryPanelTargetTab();
        if (tab?.id !== snapshot.tabId ||
            manualAnnotationState.documentId !== snapshot.documentId) {
            throw new Error('当前论文已变化，请重新确认');
        }
        const currentDocument = await sendTabMessage(snapshot.tabId, {
            action: 'prepareManualAnnotations'
        });
        if (!currentDocument?.success ||
            currentDocument.documentId !== snapshot.documentId) {
            throw new Error('当前论文已变化，请重新确认');
        }
        await runManualClear({
            documentId: snapshot.documentId,
            clearDocument: ({ documentId }) => sendLlmMessage({
                type: 'ANNOTATION_CLEAR_DOCUMENT',
                documentId
            }),
            unwrap: message => sendTabMessage(snapshot.tabId, {
                action: 'clearManualAnnotations',
                ...message,
                completionType: 'ANNOTATION_CLEAR_DOCUMENT'
            })
        });
        manualAnnotationState = {
            ...snapshot,
            annotationCount: 0,
            unresolvedCount: 0
        };
        document.getElementById('clearManualDialog').close();
        await persistCurrentArticleArchive().catch(() => null);
        showStatus('本文手动标注已清除，自动高亮保留不变', 'success');
    } catch (error) {
        if (error?.backgroundCleared) {
            manualAnnotationState = {
                ...snapshot,
                annotationCount: 0,
                unresolvedCount: 0
            };
            document.getElementById('clearManualDialog').close();
            showStatus('手动标注数据已清除；请刷新页面以移除残留标记', 'error');
        } else {
            showStatus(`清除手动标注失败，页面标记保持不变：${error.message}`, 'error');
        }
    } finally {
        manualClearPending = false;
        confirmButton.disabled = false;
        renderManualAnnotationSummary();
    }
}

function normalizePopupFigurePanelHeaderFields(value) {
    const source = value && typeof value === 'object' && !Array.isArray(value)
        ? value : {};
    return Object.fromEntries(Object.entries(DEFAULT_FIGURE_PANEL_HEADER_FIELDS)
        .map(([key, fallback]) => [
            key,
            typeof source[key] === 'boolean' ? source[key] : fallback
        ]));
}

function renderFigurePanelHeaderFieldsControl() {
    document.querySelectorAll('[data-figure-panel-header-field]').forEach(checkbox => {
        const key = checkbox.dataset.figurePanelHeaderField;
        checkbox.checked = figurePanelHeaderFieldsState[key] === true;
        checkbox.disabled = figurePanelHeaderFieldsSaving;
    });
}

function closeFigurePanelHeaderFieldsMenu() {
    const button = document.getElementById('figurePanelHeaderFieldsButton');
    const menu = document.getElementById('figurePanelHeaderFieldsMenu');
    if (!button || !menu) return;
    menu.hidden = true;
    button.setAttribute('aria-expanded', 'false');
}

function setupFigurePanelHeaderFieldsMenu() {
    if (figurePanelHeaderFieldsMenuInitialized) return;
    const button = document.getElementById('figurePanelHeaderFieldsButton');
    const menu = document.getElementById('figurePanelHeaderFieldsMenu');
    if (!button || !menu) return;
    figurePanelHeaderFieldsMenuInitialized = true;
    // Portal avoids the toolbar's overflow clipping at narrow widths.
    document.body.appendChild(menu);
    const positionMenu = () => SciLLM.SidebarUI.positionViewportPanel(menu, button, window);
    window.addEventListener('resize', positionMenu, { passive: true });
    window.addEventListener('scroll', positionMenu, { passive: true, capture: true });
    window.visualViewport?.addEventListener('resize', positionMenu, { passive: true });
    window.visualViewport?.addEventListener('scroll', positionMenu, { passive: true });
    renderFigurePanelHeaderFieldsControl();
    button.addEventListener('click', () => {
        const open = menu.hidden;
        menu.hidden = !open;
        button.setAttribute('aria-expanded', String(open));
        if (open) positionMenu();
    });
    menu.addEventListener('change', event => {
        const checkbox = event.target.closest('[data-figure-panel-header-field]');
        if (!checkbox) return;
        const key = checkbox.dataset.figurePanelHeaderField;
        if (!Object.hasOwn(DEFAULT_FIGURE_PANEL_HEADER_FIELDS, key)) return;
        const previous = { ...figurePanelHeaderFieldsState };
        const next = { ...previous, [key]: checkbox.checked === true };
        const boundedError = error => String(error?.message || '未知错误')
            .normalize('NFKC').replace(/\s+/g, ' ').trim().slice(0, 120);
        void runFigurePanelHeaderFieldsMutation({
            isPending: () => figurePanelHeaderFieldsSaving,
            previous,
            next,
            persist: value => updateLlmPreferencesCore({
                figurePanelHeaderFields: value
            }).then(saved => saved?.settings?.figurePanelHeaderFields),
            normalizeSaved: value => normalizePopupFigurePanelHeaderFields(value),
            setState: value => {
                figurePanelHeaderFieldsState = { ...value };
            },
            setPending: value => {
                figurePanelHeaderFieldsSaving = value === true;
                renderFigurePanelHeaderFieldsControl();
            },
            render: () => {
                renderFigureWorkspaceSnapshot(currentWorkspaceSnapshot);
            },
            onSaveFailed: error => showStatus(
                `Panel 标题信息保存失败：${boundedError(error)}`, 'error'
            ),
            onRenderFailed: error => showStatus(
                `Panel 标题显示刷新失败：${boundedError(error)}`, 'error'
            )
        });
    });
    document.addEventListener('pointerdown', event => {
        if (menu.hidden || menu.contains(event.target) || button.contains(event.target)) return;
        closeFigurePanelHeaderFieldsMenu();
    });
    document.addEventListener('keydown', event => {
        if (event.key === 'Escape' && !menu.hidden) {
            event.preventDefault();
            closeFigurePanelHeaderFieldsMenu();
            button.focus();
        }
    });
}

// 设置事件监听
async function handleWorkspaceHighlightAnalysis({ operationId = '' } = {}) {
    const submittedContext = capturePanelContext();
        if (regexApplyPending) return { notStarted: true };
        regexApplyPending = true;
        updateApplyButton();
        try {
            await preferenceMutationCoordinator.drainLatest();
            const tab = await queryPanelTargetTab();
            if (!tab?.id) throw new Error('无法获取当前论文页面');
            // The tab lookup yields; drain again before validating the final mode,
            // type and prepared composition used by the analysis request.
            await preferenceMutationCoordinator.drainLatest();

            if (!isCurrentPanelContext(submittedContext) || tab.id !== submittedContext.tabId) return { notStarted: true, stale: true };
            if (isSidebarOperationStopping(operationId)) return { cancelled: true, notStarted: true };
            if (analysisMode === 'llm') {
            if (llmSettingsState?.effectiveMode !== 'llm') {
                showStatus('请先完成 API、模型和正文发送许可设置', 'error');
                chrome.runtime.openOptionsPage();
                return { notStarted: true };
            }
            if (!preparedDocumentState) {
                await prepareCurrentArticleForTypeChoice();
                return { notStarted: true };
            }
            if (llmSelectedCategories.size === 0) {
                showStatus('请至少选择一个 LLM 识别类别', 'error');
                return { notStarted: true };
            }
            try {
                prepareState = 'analyzing';
                highlightTaskState = {
                    running: true, paused: false, cancelled: false,
                    phase: 'preparing', completed: 0, total: 0
                };
                updateApplyButton();
                showStatus('正在提取并分析全文，可在页面右下角查看进度', 'success');
                await applyHighlightPresentationToPage({ persist: false });
                if (!isCurrentPanelContext(submittedContext) || isSidebarOperationStopping(operationId)) return { notStarted: true, cancelled: true };
                const response = await sendTabMessage(tab.id, {
                    action: 'analyzeArticleWithLLM',
                    documentId: preparedDocumentState.documentId,
                    documentHash: preparedDocumentState.documentHash,
                    readingViewId,
                    operationId
                });
                if (response?.cancelled || response?.code === 'CANCELLED') {
                    const error = new Error('分析已取消，已完成分块结果会保留');
                    error.code = 'CANCELLED';
                    throw error;
                }
                if (!response?.success) {
                    const error = new Error(response?.error || 'LLM 分析失败');
                    error.code = response?.code;
                    throw error;
                }
                acceptSidebarRuntimeTask(response.runtimeTask, submittedContext, 'highlights');
                if (!isCurrentPanelContext(submittedContext)) return;
                matchCounts = response.counts || {};
                presentationFamilyCounts = response.familyCounts || {};
                prepareState = 'prepared';
                preparedDocumentState = {
                    ...preparedDocumentState,
                    fullTextAnalyzed: true
                };
                updateApplyButton();
                renderCategories();
                await refreshLlmDiagnostics();
                await refreshArticleWorkspace();
                await persistCurrentArticleArchive().catch(() => null);
                showStatus(formatEffectiveRoute(
                    `LLM 已高亮 ${response.highlightedCount || 0} 处`, response.analysis?.route
                ), 'success', response.usage);
            } catch (error) {
                if (!isCurrentPanelContext(submittedContext)) return;
                prepareState = 'prepared';
                updateApplyButton();
                if (error?.code === 'CANCELLED' || highlightTaskState.cancelled) {
                    showStatus('全文 LLM 高亮已取消，已完成分块结果会保留。', 'success');
                    void Promise.resolve()
                        .then(() => refreshArticleWorkspace())
                        .catch(() => undefined);
                    return;
                }
                showStatus(
                    'LLM 分析未全部完成；已完成分块和高亮均已保留。再次点击只会重试未完成分块。',
                    'error'
                );
                void Promise.resolve()
                    .then(() => refreshLlmDiagnostics())
                    .catch(() => undefined)
                    .then(() => refreshArticleWorkspace())
                    .catch(() => undefined)
                    .then(() => persistCurrentArticleArchive())
                    .catch(() => undefined);
            }
                return;
            }

            try {
                const response = await applyRegexOnTab(tab.id, operationId);
                if (response?.cancelled) return response;
                if (response?.success !== true) throw new Error(response?.error || response?.code || '高亮保存未确认');
                acceptSidebarRuntimeTask(response?.runtimeTask, submittedContext, 'highlights');
                if (!isCurrentPanelContext(submittedContext)) return;
                if (response && response.counts) {
                    matchCounts = response.counts;
                    renderCategories();
                }
                await refreshArticleWorkspace();
                await persistCurrentArticleArchive().catch(() => null);
                showStatus('高亮已应用', 'success');
            } catch (error) {
                if (isCurrentPanelContext(submittedContext)) showStatus(`应用失败：${error.message}`, 'error');
            }
        } finally {
            regexApplyPending = false;
            if (isCurrentPanelContext(submittedContext)) {
                highlightTaskState = {
                    running: false, paused: false, cancelled: false,
                    phase: '', completed: 0, total: 0
                };
                updateApplyButton();
            }
        }
}

